package main

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type edge struct {
	to      int
	minutes int
	energy  int
}

type pqItem struct {
	dist  int
	swaps int
	state int
}

type minHeap []pqItem

func (h *minHeap) push(x pqItem) {
	*h = append(*h, x)
	i := len(*h) - 1
	for i > 0 {
		p := (i - 1) >> 1
		if (*h)[p].dist < (*h)[i].dist || ((*h)[p].dist == (*h)[i].dist && (*h)[p].swaps <= (*h)[i].swaps) {
			break
		}
		(*h)[p], (*h)[i] = (*h)[i], (*h)[p]
		i = p
	}
}

func (h *minHeap) pop() pqItem {
	top := (*h)[0]
	n := len(*h) - 1
	(*h)[0] = (*h)[n]
	*h = (*h)[:n]
	i := 0
	for {
		left := (i << 1) + 1
		if left >= n {
			break
		}
		best := left
		right := left + 1
		if right < n {
			if (*h)[right].dist < (*h)[left].dist || ((*h)[right].dist == (*h)[left].dist && (*h)[right].swaps < (*h)[left].swaps) {
				best = right
			}
		}
		if (*h)[i].dist < (*h)[best].dist || ((*h)[i].dist == (*h)[best].dist && (*h)[i].swaps <= (*h)[best].swaps) {
			break
		}
		(*h)[i], (*h)[best] = (*h)[best], (*h)[i]
		i = best
	}
	return top
}

func FastestDelivery(n int, roads []Tuple1, stations []int, capacity int, swap_time int, max_swaps int, s int, t int) *Tuple2 {
	if s == t {
		return &Tuple2{F0: 0, F1: 0}
	}

	adj := make([][]edge, n)
	for _, r := range roads {
		adj[r.F0] = append(adj[r.F0], edge{
			to:      r.F1,
			minutes: r.F2,
			energy:  r.F3,
		})
	}

	isStation := make([]bool, n)
	for _, st := range stations {
		isStation[st] = true
	}

	capCount := capacity + 1
	swapCount := max_swaps + 1
	totalStates := n * capCount * swapCount

	const inf = int(1 << 60)
	dist := make([]int, totalStates)
	for i := range dist {
		dist[i] = inf
	}

	startState := (s*capCount + capacity) * swapCount
	dist[startState] = 0

	var h minHeap
	h.push(pqItem{dist: 0, swaps: 0, state: startState})

	for len(h) > 0 {
		cur := h.pop()
		d := cur.dist
		state := cur.state
		if d > dist[state] {
			continue
		}

		k := state % swapCount
		tmp := state / swapCount
		c := tmp % capCount
		u := tmp / capCount

		if u == t {
			return &Tuple2{F0: d, F1: k}
		}

		for _, e := range adj[u] {
			if c >= e.energy {
				nc := c - e.energy
				if nc > capacity {
					nc = capacity
				}
				nextState := (e.to*capCount+nc)*swapCount + k
				nd := d + e.minutes
				if nd < dist[nextState] {
					dist[nextState] = nd
					h.push(pqItem{dist: nd, swaps: k, state: nextState})
				}
			}
		}

		if isStation[u] && k < max_swaps {
			nextState := (u*capCount+capacity)*swapCount + (k + 1)
			nd := d + swap_time
			if nd < dist[nextState] {
				dist[nextState] = nd
				h.push(pqItem{dist: nd, swaps: k + 1, state: nextState})
			}
		}
	}

	return nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3) {}

    public record Tuple2(long f0, long f1) {}

    private static final class MinHeap {
        private long[] dists;
        private int[] states;
        private int size;
        private final int kMod;

        MinHeap(int initialCapacity, int kMod) {
            this.dists = new long[Math.max(16, initialCapacity)];
            this.states = new int[this.dists.length];
            this.size = 0;
            this.kMod = kMod;
        }

        boolean isEmpty() {
            return size == 0;
        }

        void push(long d, int s) {
            if (size == dists.length) {
                int newCap = dists.length << 1;
                dists = Arrays.copyOf(dists, newCap);
                states = Arrays.copyOf(states, newCap);
            }
            int i = size++;
            int k = s % kMod;
            while (i > 0) {
                int p = (i - 1) >>> 1;
                long pd = dists[p];
                int ps = states[p];
                if (d < pd || (d == pd && k < ps % kMod)) {
                    dists[i] = pd;
                    states[i] = ps;
                    i = p;
                } else {
                    break;
                }
            }
            dists[i] = d;
            states[i] = s;
        }

        long peekDist() {
            return dists[0];
        }

        int popState() {
            int res = states[0];
            int n = --size;
            if (n > 0) {
                long d = dists[n];
                int s = states[n];
                int k = s % kMod;
                int i = 0;
                int half = n >>> 1;
                while (i < half) {
                    int child = (i << 1) + 1;
                    long cd = dists[child];
                    int cs = states[child];
                    int ck = cs % kMod;
                    int right = child + 1;
                    if (right < n) {
                        long rd = dists[right];
                        int rs = states[right];
                        int rk = rs % kMod;
                        if (rd < cd || (rd == cd && rk < ck)) {
                            child = right;
                            cd = rd;
                            cs = rs;
                            ck = rk;
                        }
                    }
                    if (d < cd || (d == cd && k <= ck)) {
                        break;
                    }
                    dists[i] = cd;
                    states[i] = cs;
                    i = child;
                }
                dists[i] = d;
                states[i] = s;
            }
            return res;
        }
    }

    public static Tuple2 fastestDelivery(
            long n,
            List<Tuple1> roads,
            List<Long> stations,
            long capacity,
            long swap_time,
            long max_swaps,
            long s,
            long t) {
        if (s == t) {
            return new Tuple2(0L, 0L);
        }

        int numNodes = (int) n;
        int cap = (int) capacity;
        int cSize = cap + 1;
        int maxSwaps = (int) max_swaps;
        int kSize = maxSwaps + 1;
        int startNode = (int) s;
        int targetNode = (int) t;

        boolean[] isStation = new boolean[numNodes];
        for (long st : stations) {
            isStation[(int) st] = true;
        }

        int m = roads.size();
        int[] head = new int[numNodes];
        Arrays.fill(head, -1);
        int[] to = new int[m];
        long[] edgeMin = new long[m];
        int[] edgeEnergy = new int[m];
        int[] next = new int[m];
        for (int i = 0; i < m; i++) {
            Tuple1 r = roads.get(i);
            int u = (int) r.f0();
            to[i] = (int) r.f1();
            edgeMin[i] = r.f2();
            edgeEnergy[i] = (int) r.f3();
            next[i] = head[u];
            head[u] = i;
        }

        int totalStates = numNodes * cSize * kSize;
        long[] dist = new long[totalStates];
        Arrays.fill(dist, Long.MAX_VALUE);

        int startState = (startNode * cSize + cap) * kSize;
        dist[startState] = 0L;

        MinHeap pq = new MinHeap(Math.min(totalStates, 4096), kSize);
        pq.push(0L, startState);

        while (!pq.isEmpty()) {
            long d = pq.peekDist();
            int state = pq.popState();
            if (d != dist[state]) {
                continue;
            }

            int k = state % kSize;
            int uc = state / kSize;
            int c = uc % cSize;
            int u = uc / cSize;

            if (u == targetNode) {
                return new Tuple2(d, k);
            }

            for (int e = head[u]; e != -1; e = next[e]) {
                int energy = edgeEnergy[e];
                if (c >= energy) {
                    int nc = c - energy;
                    if (nc > cap) {
                        nc = cap;
                    }
                    int v = to[e];
                    int ns = (v * cSize + nc) * kSize + k;
                    long nd = d + edgeMin[e];
                    if (nd < dist[ns]) {
                        dist[ns] = nd;
                        pq.push(nd, ns);
                    }
                }
            }

            if (isStation[u] && k < maxSwaps) {
                int ns = (u * cSize + cap) * kSize + (k + 1);
                long nd = d + swap_time;
                if (nd < dist[ns]) {
                    dist[ns] = nd;
                    pq.push(nd, ns);
                }
            }
        }

        return null;
    }
}

