std::optional<std::tuple<long long, long long>> fastest_delivery(
    long long n,
    const std::vector<std::tuple<long long, long long, long long, long long>>& roads,
    const std::vector<long long>& stations,
    long long capacity,
    long long swap_time,
    long long max_swaps,
    long long s,
    long long t) {
    if (s == t) {
        return std::make_tuple(0LL, 0LL);
    }

    const int N = static_cast<int>(n);
    const int cap = static_cast<int>(capacity);
    const int C = cap + 1;
    const int max_k = static_cast<int>(max_swaps);
    const int K = max_k + 1;

    struct Edge {
        int to;
        long long minutes;
        int energy;
    };

    std::vector<std::vector<Edge>> adj(N);
    for (const auto& [u, v, minutes, energy] : roads) {
        adj[static_cast<int>(u)].push_back(
            {static_cast<int>(v), minutes, static_cast<int>(energy)});
    }

    std::vector<bool> is_station(N, false);
    for (long long st : stations) {
        is_station[static_cast<int>(st)] = true;
    }

    auto idx = [C, K](int u, int c, int k) -> int {
        return (u * C + c) * K + k;
    };

    constexpr long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> dist(N * C * K, INF);

    struct Node {
        long long d;
        int k;
        int u;
        int c;
        bool operator>(const Node& other) const {
            if (d != other.d) return d > other.d;
            return k > other.k;
        }
    };

    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
    const int start_u = static_cast<int>(s);
    const int target_u = static_cast<int>(t);

    dist[idx(start_u, cap, 0)] = 0;
    pq.push({0, 0, start_u, cap});

    while (!pq.empty()) {
        auto [d, k, u, c] = pq.top();
        pq.pop();

        if (d > dist[idx(u, c, k)]) {
            continue;
        }

        if (u == target_u) {
            return std::make_tuple(d, static_cast<long long>(k));
        }

        for (const auto& e : adj[u]) {
            if (c >= e.energy) {
                int nc = std::min(cap, c - e.energy);
                long long nd = d + e.minutes;
                int nidx = idx(e.to, nc, k);
                if (nd < dist[nidx]) {
                    dist[nidx] = nd;
                    pq.push({nd, k, e.to, nc});
                }
            }
        }

        if (is_station[u] && k < max_k && c < cap) {
            long long nd = d + swap_time;
            int nidx = idx(u, cap, k + 1);
            if (nd < dist[nidx]) {
                dist[nidx] = nd;
                pq.push({nd, k + 1, u, cap});
            }
        }
    }

    return std::nullopt;
}

export function fastestDelivery(
  n: number,
  roads: [number, number, number, number][],
  stations: number[],
  capacity: number,
  swap_time: number,
  max_swaps: number,
  s: number,
  t: number
): [number, number] | null {
  if (s === t) {
    return [0, 0];
  }

  const isStation = new Uint8Array(n);
  for (let i = 0; i < stations.length; i++) {
    isStation[stations[i]] = 1;
  }

  const m = roads.length;
  const head = new Int32Array(n).fill(-1);
  const to = new Int32Array(m);
  const edgeMin = new Float64Array(m);
  const edgeEnergy = new Int32Array(m);
  const nextEdge = new Int32Array(m);

  for (let i = 0; i < m; i++) {
    const road = roads[i];
    const u = road[0];
    to[i] = road[1];
    edgeMin[i] = road[2];
    edgeEnergy[i] = road[3];
    nextEdge[i] = head[u];
    head[u] = i;
  }

  const C = capacity + 1;
  const S = max_swaps + 1;
  const totalStates = n * C * S;

  const dist = new Float64Array(totalStates);
  dist.fill(Infinity);

  let heapCap = 4096;
  let heapSize = 0;
  let heapDist = new Float64Array(heapCap);
  let heapId = new Int32Array(heapCap);

  const push = (d: number, id: number): void => {
    if (heapSize === heapCap) {
      heapCap *= 2;
      const nextDist = new Float64Array(heapCap);
      nextDist.set(heapDist);
      heapDist = nextDist;
      const nextId = new Int32Array(heapCap);
      nextId.set(heapId);
      heapId = nextId;
    }
    let i = heapSize++;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heapDist[p] <= d) break;
      heapDist[i] = heapDist[p];
      heapId[i] = heapId[p];
      i = p;
    }
    heapDist[i] = d;
    heapId[i] = id;
  };

  const startId = (s * C + capacity) * S;
  dist[startId] = 0;
  push(0, startId);

  let bestMinutes = Infinity;
  let bestSwaps = Infinity;

  while (heapSize > 0) {
    const d = heapDist[0];
    const id = heapId[0];

    const lastIdx = --heapSize;
    if (lastIdx > 0) {
      const ld = heapDist[lastIdx];
      const lid = heapId[lastIdx];
      let i = 0;
      const half = lastIdx >> 1;
      while (i < half) {
        let child = (i << 1) + 1;
        const right = child + 1;
        if (right < lastIdx && heapDist[right] < heapDist[child]) {
          child = right;
        }
        if (ld <= heapDist[child]) break;
        heapDist[i] = heapDist[child];
        heapId[i] = heapId[child];
        i = child;
      }
      heapDist[i] = ld;
      heapId[i] = lid;
    }

    if (d > bestMinutes) {
      break;
    }
    if (d > dist[id]) {
      continue;
    }

    const k = id % S;
    const uc = (id / S) | 0;
    const c = uc % C;
    const u = (uc / C) | 0;

    if (u === t) {
      bestMinutes = d;
      if (k < bestSwaps) {
        bestSwaps = k;
      }
      continue;
    }

    if (isStation[u] === 1 && k < max_swaps && c < capacity) {
      const nid = (u * C + capacity) * S + (k + 1);
      const nd = d + swap_time;
      if (nd < dist[nid]) {
        dist[nid] = nd;
        push(nd, nid);
      }
    }

    for (let e = head[u]; e !== -1; e = nextEdge[e]) {
      const energy = edgeEnergy[e];
      if (c >= energy) {
        let nc = c - energy;
        if (nc > capacity) nc = capacity;
        const v = to[e];
        const nid = (v * C + nc) * S + k;
        const nd = d + edgeMin[e];
        if (nd < dist[nid]) {
          dist[nid] = nd;
          push(nd, nid);
        }
      }
    }
  }

  if (bestMinutes === Infinity) {
    return null;
  }
  return [bestMinutes, bestSwaps];
}

from collections import deque


def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    if n == 0:
        return 0

    NEG_INF = -10**18
    dp = [[NEG_INF] * (budget + 1) for _ in range(n)]
    dp_start = [NEG_INF] * (budget + 1)
    dp_start[0] = 0

    deques = [deque() for _ in range(budget + 1)]

    def push_row(j):
        row = dp_start if j == -1 else dp[j]
        for w in range(budget + 1):
            val = row[w]
            if val > NEG_INF:
                dq = deques[w]
                while dq and dq[-1][1] <= val:
                    dq.pop()
                dq.append((j, val))

    last_pin = -1
    for i in range(n):
        length_i, value_i, pinned_i = messages[i]
        L = last_pin if last_pin > i - max_gap - 1 else i - max_gap - 1

        if i > 0:
            push_row(i - 2)
            prev_row = dp[i - 1]
            if length_i <= budget:
                cur_row = dp[i]
                for w in range(budget - length_i + 1):
                    dq = deques[w]
                    while dq and dq[0][0] < L:
                        dq.popleft()
                    best_prev = dq[0][1] if dq else NEG_INF
                    adj = prev_row[w]
                    if adj > NEG_INF:
                        adj_with_bonus = adj + bonus
                        if adj_with_bonus > best_prev:
                            best_prev = adj_with_bonus
                    if best_prev > NEG_INF:
                        cur_row[w + length_i] = best_prev + value_i
        else:
            if length_i <= budget:
                dp[0][length_i] = value_i

        if pinned_i:
            last_pin = i

    L_end = last_pin if last_pin > n - max_gap - 1 else n - max_gap - 1
    push_row(n - 2)
    push_row(n - 1)

    ans = NEG_INF
    for w in range(budget + 1):
        dq = deques[w]
        while dq and dq[0][0] < L_end:
            dq.popleft()
        if dq and dq[0][1] > ans:
            ans = dq[0][1]

    return None if ans == NEG_INF else ans

package main

import "errors"

type Tuple1 struct {
	F0 int
	F1 int
	F2 bool
}

func BestContext(messages []Tuple1, budget int, max_gap int, bonus int) (*int, error) {
	if budget < 0 || max_gap < 0 {
		return nil, errors.New("budget and max_gap must be non-negative")
	}

	n := len(messages)
	const negInf = -1 << 60

	dp := make([][]int, n)
	for i := 0; i < n; i++ {
		dp[i] = make([]int, budget+1)
		for w := 0; w <= budget; w++ {
			dp[i][w] = negInf
		}
	}

	lastPinned := -1
	for i := 0; i < n; i++ {
		length := messages[i].F0
		val := messages[i].F1
		if length <= budget {
			if i <= max_gap && lastPinned == -1 {
				if val > dp[i][length] {
					dp[i][length] = val
				}
			}

			minJ := i - 1 - max_gap
			if minJ < 0 {
				minJ = 0
			}
			if lastPinned > minJ {
				minJ = lastPinned
			}

			pi := dp[i]
			for j := minJ; j < i; j++ {
				add := val
				if j == i-1 {
					add += bonus
				}
				pj := dp[j]
				for w := length; w <= budget; w++ {
					prev := pj[w-length]
					if prev != negInf {
						cand := prev + add
						if cand > pi[w] {
							pi[w] = cand
						}
					}
				}
			}
		}
		if messages[i].F2 {
			lastPinned = i
		}
	}

	hasAns := false
	best := 0

	if n <= max_gap && lastPinned == -1 {
		hasAns = true
		best = 0
	}

	minLast := n - 1 - max_gap
	if minLast < 0 {
		minLast = 0
	}
	if lastPinned > minLast {
		minLast = lastPinned
	}

	for i := minLast; i < n; i++ {
		for w := 0; w <= budget; w++ {
			if dp[i][w] != negInf {
				if !hasAns || dp[i][w] > best {
					best = dp[i][w]
					hasAns = true
				}
			}
		}
	}

	if !hasAns {
		return nil, nil
	}
	res := best
	return &res, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, boolean f2) {}

    public static Long bestContext(List<Tuple1> messages, long budget, long max_gap, long bonus) {
        if (budget < 0 || max_gap < 0) {
            throw new IllegalArgumentException("budget and max_gap must be non-negative");
        }
        int n = messages.size();
        if (n == 0) {
            return 0L;
        }

        long sumLen = 0;
        for (Tuple1 m : messages) {
            if (m.f0() <= budget) {
                sumLen += m.f0();
            }
        }
        int B = (int) Math.min(budget, sumLen);
        int G = (int) Math.min(max_gap, (long) n);

        long[] len = new long[n];
        long[] val = new long[n];
        boolean[] pinned = new boolean[n];
        int lastPinned = -1;
        for (int i = 0; i < n; i++) {
            Tuple1 m = messages.get(i);
            len[i] = m.f0();
            val[i] = m.f1();
            pinned[i] = m.f2();
            if (pinned[i]) {
                lastPinned = i;
            }
        }

        final long NEG_INF = Long.MIN_VALUE / 4;
        long[][] dp = new long[n][B + 1];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], NEG_INF);
        }

        int prevPinned = -1;
        for (int i = 0; i < n; i++) {
            if (len[i] <= B) {
                int li = (int) len[i];
                long vi = val[i];

                if (i <= G && prevPinned == -1) {
                    dp[i][li] = Math.max(dp[i][li], vi);
                }

                int minJ = Math.max(0, i - G - 1);
                if (prevPinned != -1) {
                    minJ = Math.max(minJ, prevPinned);
                }
                for (int j = minJ; j < i; j++) {
                    long add = vi + (j == i - 1 ? bonus : 0L);
                    long[] dpJ = dp[j];
                    long[] dpI = dp[i];
                    for (int w = 0; w <= B - li; w++) {
                        if (dpJ[w] != NEG_INF) {
                            long cand = dpJ[w] + add;
                            if (cand > dpI[w + li]) {
                                dpI[w + li] = cand;
                            }
                        }
                    }
                }
            }
            if (pinned[i]) {
                prevPinned = i;
            }
        }

        long ans = NEG_INF;
        if (lastPinned == -1 && n <= G) {
            ans = 0L;
        }

        int minLast = Math.max(0, n - 1 - G);
        if (lastPinned != -1) {
            minLast = Math.max(minLast, lastPinned);
        }
        for (int i = minLast; i < n; i++) {
            for (int w = 0; w <= B; w++) {
                if (dp[i][w] > ans) {
                    ans = dp[i][w];
                }
            }
        }

        return ans == NEG_INF ? null : ans;
    }
}

#include <algorithm>
#include <limits>
#include <optional>
#include <stdexcept>
#include <tuple>
#include <vector>

std::optional<long long> best_context(
    const std::vector<std::tuple<long long, long long, bool>>& messages,
    long long budget,
    long long max_gap,
    long long bonus) {
    if (budget < 0 || max_gap < 0) {
        throw std::invalid_argument("budget and max_gap must be non-negative");
    }

    long long n = static_cast<long long>(messages.size());
    if (n == 0) {
        return 0LL;
    }

    bool any_pinned = false;
    for (long long i = 0; i < n; ++i) {
        if (std::get<2>(messages[i])) {
            any_pinned = true;
            break;
        }
    }

    const long long NEG_INF = std::numeric_limits<long long>::min() / 4;
    std::vector<std::vector<long long>> dp(
        static_cast<std::size_t>(n),
        std::vector<long long>(static_cast<std::size_t>(budget + 1), NEG_INF));

    bool seen_pinned_before = false;
    for (long long i = 0; i < n; ++i) {
        auto [len_i, val_i, pin_i] = messages[static_cast<std::size_t>(i)];
        if (len_i <= budget) {
            if (!seen_pinned_before && i <= max_gap) {
                long long& cur = dp[static_cast<std::size_t>(i)][static_cast<std::size_t>(len_i)];
                cur = std::max(cur, val_i);
            }

            long long min_j = std::max(0LL, i - max_gap - 1);
            for (long long j = i - 1; j >= min_j; --j) {
                long long add = val_i + (j == i - 1 ? bonus : 0LL);
                for (long long w = 0; w + len_i <= budget; ++w) {
                    long long prev = dp[static_cast<std::size_t>(j)][static_cast<std::size_t>(w)];
                    if (prev != NEG_INF) {
                        long long& cur =
                            dp[static_cast<std::size_t>(i)][static_cast<std::size_t>(w + len_i)];
                        if (prev + add > cur) {
                            cur = prev + add;
                        }
                    }
                }
                if (std::get<2>(messages[static_cast<std::size_t>(j)])) {
                    break;
                }
            }
        }
        if (pin_i) {
            seen_pinned_before = true;
        }
    }

    std::optional<long long> ans = std::nullopt;
    if (!any_pinned && n <= max_gap) {
        ans = 0LL;
    }

    for (long long i = n - 1; i >= 0 && (n - 1 - i) <= max_gap; --i) {
        for (long long w = 0; w <= budget; ++w) {
            long long val = dp[static_cast<std::size_t>(i)][static_cast<std::size_t>(w)];
            if (val != NEG_INF) {
                if (!ans.has_value() || val > *ans) {
                    ans = val;
                }
            }
        }
        if (std::get<2>(messages[static_cast<std::size_t>(i)])) {
            break;
        }
    }

    return ans;
}

export function bestContext(
  messages: [number, number, boolean][],
  budget: number,
  max_gap: number,
  bonus: number,
): number | null {
  if (budget < 0 || max_gap < 0) {
    throw new Error("budget and max_gap must be non-negative");
  }

  const n = messages.length;
  const dp: Float64Array[] = new Array(n);
  for (let i = 0; i < n; i++) {
    dp[i] = new Float64Array(budget + 1).fill(-Infinity);
  }

  let lastPinned = -1;
  for (let i = 0; i < n; i++) {
    const [len, val, pinned] = messages[i];
    const row = dp[i];

    if (len <= budget) {
      if (i <= max_gap && lastPinned === -1) {
        if (val > row[len]) {
          row[len] = val;
        }
      }

      const minJ = Math.max(0, lastPinned, i - max_gap - 1);
      for (let j = minJ; j < i; j++) {
        const prevRow = dp[j];
        const addVal = val + (j === i - 1 ? bonus : 0);
        for (let w = len; w <= budget; w++) {
          const prev = prevRow[w - len];
          if (prev !== -Infinity) {
            const cand = prev + addVal;
            if (cand > row[w]) {
              row[w] = cand;
            }
          }
        }
      }
    }

    if (pinned) {
      lastPinned = i;
    }
  }

  let ans = -Infinity;

  if (lastPinned === -1 && n <= max_gap) {
    ans = 0;
  }

  const minEnd = Math.max(0, lastPinned, n - 1 - max_gap);
  for (let i = minEnd; i < n; i++) {
    const row = dp[i];
    for (let w = 0; w <= budget; w++) {
      if (row[w] > ans) {
        ans = row[w];
      }
    }
  }

  if (ans === -Infinity) {
    return null;
  }
  return ans === 0 ? 0 : ans;
}

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Compute post-order traversal iteratively (children before parent)
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(u)
        for c in children[u]:
            stack.append(c)
    order.reverse()

    INF = 10**18
    sub_dem = [0] * n
    has_crit = [False] * n
    dp = [None] * n

    for v in order:
        sd = demand[v]
        hc = critical[v]
        for c in children[v]:
            sd += sub_dem[c]
            if has_crit[c]:
                hc = True
        sub_dem[v] = sd
        has_crit[v] = hc

        cap_v = root_cap if v == 0 else cap[v]
        if cap_v > sd:
            cap_v = sd

        if demand[v] > cap_v:
            if v == 0 or hc:
                return None
            dp[v] = []
            continue

        cur = [(demand[v], 0)]
        for c in children[v]:
            dp_c = dp[c]
            dp[c] = None  # free child DP once consumed

            if not dp_c:
                # Child c cannot be retained; must cut line c (hc[c] is False)
                cut_c = cut_cost[c] + penalty * sub_dem[c]
                cur = [(x, cx + cut_c) for x, cx in cur]
                continue

            new_max = cur[-1][0] + dp_c[-1][0]
            if new_max > cap_v:
                new_max = cap_v
            new_dp = [INF] * (new_max + 1)

            # Option A: cut line c (only if no critical node in c's subtree)
            if not has_crit[c]:
                cut_c = cut_cost[c] + penalty * sub_dem[c]
                for x, cx in cur:
                    new_dp[x] = cx + cut_c

            # Option B: retain node c
            if len(cur) >= len(dp_c):
                min_x = cur[0][0]
                for y, cy in dp_c:
                    max_x = cap_v - y
                    if max_x < min_x:
                        break
                    for x, cx in cur:
                        if x > max_x:
                            break
                        s = x + y
                        nv = cx + cy
                        if nv < new_dp[s]:
                            new_dp[s] = nv
            else:
                min_y = dp_c[0][0]
                for x, cx in cur:
                    max_y = cap_v - x
                    if max_y < min_y:
                        break
                    for y, cy in dp_c:
                        if y > max_y:
                            break
                        s = x + y
                        nv = cx + cy
                        if nv < new_dp[s]:
                            new_dp[s] = nv

            cur = [(s, cval) for s, cval in enumerate(new_dp) if cval < INF]
            if not cur:
                break

        if not cur:
            if v == 0 or hc:
                return None
            dp[v] = []
        else:
            dp[v] = cur

    return min(cost for _, cost in dp[0])

package main

func MinPruningCost(parent []int, demand []int, cap []int, cut_cost []int, critical []bool, root_cap int, penalty int) *int {
	n := len(parent)
	children := make([][]int, n)
	for v := 1; v < n; v++ {
		p := parent[v]
		children[p] = append(children[p], v)
	}

	order := make([]int, 0, n)
	order = append(order, 0)
	for i := 0; i < len(order); i++ {
		u := order[i]
		for _, c := range children[u] {
			order = append(order, c)
		}
	}

	const inf = 1 << 60
	subDemand := make([]int, n)
	hasCrit := make([]bool, n)
	dp := make([][]int, n)

	for i := n - 1; i >= 0; i-- {
		v := order[i]
		sd := demand[v]
		hc := critical[v]
		for _, c := range children[v] {
			sd += subDemand[c]
			if hasCrit[c] {
				hc = true
			}
		}
		subDemand[v] = sd
		hasCrit[v] = hc

		effCap := root_cap
		if v != 0 {
			effCap = cap[v]
		}
		if demand[v] > effCap {
			continue
		}

		limitV := effCap
		if sd < limitV {
			limitV = sd
		}

		cur := make([]int, demand[v]+1)
		for w := 0; w < demand[v]; w++ {
			cur[w] = inf
		}
		cur[demand[v]] = 0

		possible := true
		for _, c := range children[v] {
			cutAllowed := !hasCrit[c]
			cutTotal := cut_cost[c] + penalty*subDemand[c]
			dpC := dp[c]

			if !cutAllowed && dpC == nil {
				possible = false
				break
			}

			curMax := len(cur) - 1
			newMax := curMax
			if dpC != nil {
				cMax := len(dpC) - 1
				if curMax+cMax > newMax {
					newMax = curMax + cMax
				}
				if newMax > limitV {
					newMax = limitV
				}
			}

			next := make([]int, newMax+1)
			for w := range next {
				next[w] = inf
			}

			if cutAllowed {
				for w := demand[v]; w <= curMax; w++ {
					if cur[w] == inf {
						continue
					}
					cost := cur[w] + cutTotal
					if cost < next[w] {
						next[w] = cost
					}
				}
			}

			if dpC != nil {
				cMax := len(dpC) - 1
				for w := demand[v]; w <= curMax; w++ {
					cw := cur[w]
					if cw == inf {
						continue
					}
					maxWc := limitV - w
					if cMax < maxWc {
						maxWc = cMax
					}
					for wc := demand[c]; wc <= maxWc; wc++ {
						if dpC[wc] == inf {
							continue
						}
						nw := w + wc
						cost := cw + dpC[wc]
						if cost < next[nw] {
							next[nw] = cost
						}
					}
				}
			}

			lastValid := -1
			for w := newMax; w >= demand[v]; w-- {
				if next[w] != inf {
					lastValid = w
					break
				}
			}
			if lastValid == -1 {
				possible = false
				break
			}
			cur = next[:lastValid+1]
		}

		if possible {
			dp[v] = cur
		}
	}

	if dp[0] == nil {
		return nil
	}
	best := inf
	for _, cost := range dp[0] {
		if cost < best {
			best = cost
		}
	}
	if best == inf {
		return nil
	}
	return &best
}

import java.util.*;

public final class Solution {
    private static final long INF = Long.MAX_VALUE / 4;

    public static Long minPruningCost(
            List<Long> parent,
            List<Long> demand,
            List<Long> cap,
            List<Long> cut_cost,
            List<Boolean> critical,
            long root_cap,
            long penalty) {
        int n = parent.size();
        @SuppressWarnings("unchecked")
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }
        for (int v = 1; v < n; v++) {
            int p = parent.get(v).intValue();
            children[p].add(v);
        }

        int[] order = new int[n];
        int head = 0;
        int tail = 0;
        order[tail++] = 0;
        while (head < tail) {
            int u = order[head++];
            for (int c : children[u]) {
                order[tail++] = c;
            }
        }

        long[] subDem = new long[n];
        boolean[] hasCrit = new boolean[n];
        long[][] dp = new long[n][];

        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            long demV = demand.get(v);
            long capV = (v == 0) ? root_cap : cap.get(v);

            long sDem = demV;
            boolean hCrit = critical.get(v);
            for (int u : children[v]) {
                sDem += subDem[u];
                hCrit |= hasCrit[u];
            }
            subDem[v] = sDem;
            hasCrit[v] = hCrit;

            if (demV > capV) {
                dp[v] = null;
                continue;
            }

            int maxCap = (int) Math.min(capV, sDem);
            int curMax = (int) demV;
            long[] cur = new long[curMax + 1];
            Arrays.fill(cur, INF);
            cur[curMax] = 0L;

            boolean possible = true;
            for (int u : children[v]) {
                long[] uDp = dp[u];
                boolean canCut = !hasCrit[u];
                if (uDp == null && !canCut) {
                    possible = false;
                    break;
                }

                int uMax = (uDp == null) ? 0 : uDp.length - 1;
                int nextMax = (uDp == null) ? curMax : Math.min(maxCap, curMax + uMax);
                long[] next = new long[nextMax + 1];
                Arrays.fill(next, INF);

                if (canCut) {
                    long cutCostTotal = cut_cost.get(u) + penalty * subDem[u];
                    for (int l = 0; l <= curMax; l++) {
                        if (cur[l] != INF) {
                            long val = cur[l] + cutCostTotal;
                            if (val < next[l]) {
                                next[l] = val;
                            }
                        }
                    }
                }

                if (uDp != null) {
                    for (int l = 0; l <= curMax; l++) {
                        long c = cur[l];
                        if (c == INF) {
                            continue;
                        }
                        int limitLu = Math.min(uMax, nextMax - l);
                        for (int lu = 0; lu <= limitLu; lu++) {
                            if (uDp[lu] != INF) {
                                long val = c + uDp[lu];
                                if (val < next[l + lu]) {
                                    next[l + lu] = val;
                                }
                            }
                        }
                    }
                }

                int tightMax = -1;
                for (int l = nextMax; l >= 0; l--) {
                    if (next[l] != INF) {
                        tightMax = l;
                        break;
                    }
                }
                if (tightMax == -1) {
                    possible = false;
                    break;
                }
                cur = next;
                curMax = tightMax;
            }

            if (possible) {
                dp[v] = Arrays.copyOf(cur, curMax + 1);
            } else {
                dp[v] = null;
            }
        }

        if (dp[0] == null) {
            return null;
        }
        long ans = INF;
        for (long val : dp[0]) {
            if (val < ans) {
                ans = val;
            }
        }
        return ans == INF ? null : ans;
    }
}

#include <algorithm>
#include <cstddef>
#include <optional>
#include <vector>

std::optional<long long> min_pruning_cost(
    const std::vector<long long>& parent,
    const std::vector<long long>& demand,
    const std::vector<long long>& cap,
    const std::vector<long long>& cut_cost,
    const std::vector<bool>& critical,
    long long root_cap,
    long long penalty) {
    const int n = static_cast<int>(parent.size());
    std::vector<std::vector<int>> children(n);
    for (int v = 1; v < n; ++v) {
        children[static_cast<int>(parent[v])].push_back(v);
    }

    constexpr long long INF = 4'000'000'000'000'000'000LL;

    std::vector<long long> subtree_demand(n, 0);
    std::vector<bool> has_crit(n, false);
    std::vector<std::vector<long long>> dp(n);

    auto dfs = [&](auto& self, int v) -> void {
        subtree_demand[v] = demand[v];
        has_crit[v] = critical[v];

        const long long limit_v = (v == 0) ? root_cap : cap[v];
        if (demand[v] <= limit_v) {
            dp[v].assign(static_cast<std::size_t>(demand[v]) + 1, INF);
            dp[v][static_cast<std::size_t>(demand[v])] = 0;
        }

        for (int c : children[v]) {
            self(self, c);
            subtree_demand[v] += subtree_demand[c];
            if (has_crit[c]) {
                has_crit[v] = true;
            }

            if (dp[v].empty()) {
                std::vector<long long>().swap(dp[c]);
                continue;
            }

            const std::size_t max_v = dp[v].size() - 1;
            const std::size_t max_c = dp[c].empty() ? 0 : (dp[c].size() - 1);
            const std::size_t new_max = static_cast<std::size_t>(
                std::min(limit_v, static_cast<long long>(max_v + max_c)));

            std::vector<long long> next_dp(new_max + 1, INF);

            if (!has_crit[c]) {
                const long long cut_total = cut_cost[c] + penalty * subtree_demand[c];
                for (std::size_t lv = 0; lv <= max_v; ++lv) {
                    if (dp[v][lv] < INF) {
                        next_dp[lv] = std::min(next_dp[lv], dp[v][lv] + cut_total);
                    }
                }
            }

            if (!dp[c].empty()) {
                for (std::size_t lv = 0; lv <= max_v; ++lv) {
                    if (dp[v][lv] >= INF) {
                        continue;
                    }
                    const std::size_t lc_limit = std::min(max_c, new_max - lv);
                    for (std::size_t lc = 0; lc <= lc_limit; ++lc) {
                        if (dp[c][lc] < INF) {
                            next_dp[lv + lc] = std::min(next_dp[lv + lc], dp[v][lv] + dp[c][lc]);
                        }
                    }
                }
            }

            std::vector<long long>().swap(dp[c]);

            bool any_valid = false;
            for (long long val : next_dp) {
                if (val < INF) {
                    any_valid = true;
                    break;
                }
            }
            if (any_valid) {
                dp[v].swap(next_dp);
            } else {
                dp[v].clear();
            }
        }
    };

    dfs(dfs, 0);

    if (dp[0].empty()) {
        return std::nullopt;
    }

    long long ans = INF;
    for (long long val : dp[0]) {
        ans = std::min(ans, val);
    }

    if (ans >= INF) {
        return std::nullopt;
    }
    return ans;
}

export function minPruningCost(
  parent: number[],
  demand: number[],
  cap: number[],
  cut_cost: number[],
  critical: boolean[],
  root_cap: number,
  penalty: number,
): number | null {
  const n = parent.length;
  const children: number[][] = Array.from({ length: n }, () => []);
  for (let v = 1; v < n; v++) {
    children[parent[v]].push(v);
  }

  const order: number[] = [0];
  for (let i = 0; i < order.length; i++) {
    const u = order[i];
    const ch = children[u];
    for (let j = 0; j < ch.length; j++) {
      order.push(ch[j]);
    }
  }

  const subDemand = new Int32Array(n);
  const hasCritical = new Uint8Array(n);
  const dp: (Float64Array | null)[] = new Array(n).fill(null);

  for (let idx = n - 1; idx >= 0; idx--) {
    const v = order[idx];
    let sd = demand[v];
    let hc = critical[v] ? 1 : 0;
    const ch = children[v];
    for (let j = 0; j < ch.length; j++) {
      const c = ch[j];
      sd += subDemand[c];
      if (hasCritical[c]) hc = 1;
    }
    subDemand[v] = sd;
    hasCritical[v] = hc;

    const maxCap = v === 0 ? root_cap : cap[v];
    if (demand[v] > maxCap) {
      dp[v] = null;
      continue;
    }

    let cur = new Float64Array(demand[v] + 1);
    cur.fill(Infinity);
    cur[demand[v]] = 0;
    let curMax = demand[v];
    let possible = true;

    for (let j = 0; j < ch.length; j++) {
      const c = ch[j];
      const childDp = dp[c];
      const cutCost = hasCritical[c] ? Infinity : cut_cost[c] + penalty * subDemand[c];

      if (childDp === null && cutCost === Infinity) {
        possible = false;
        break;
      }

      const childMax = childDp === null ? -1 : childDp.length - 1;
      const nextCap = Math.min(maxCap, curMax + Math.max(0, childMax));
      const next = new Float64Array(nextCap + 1);
      next.fill(Infinity);

      if (cutCost < Infinity) {
        for (let l = 0; l <= curMax; l++) {
          const val = cur[l];
          if (val < Infinity) {
            const cand = val + cutCost;
            if (cand < next[l]) next[l] = cand;
          }
        }
      }

      if (childDp !== null) {
        for (let l = 0; l <= curMax; l++) {
          const val = cur[l];
          if (val === Infinity) continue;
          const limit = Math.min(childMax, maxCap - l);
          for (let lc = 0; lc <= limit; lc++) {
            const cval = childDp[lc];
            if (cval === Infinity) continue;
            const nl = l + lc;
            const cand = val + cval;
            if (cand < next[nl]) next[nl] = cand;
          }
        }
      }

      let actualMax = -1;
      for (let l = nextCap; l >= 0; l--) {
        if (next[l] < Infinity) {
          actualMax = l;
          break;
        }
      }

      if (actualMax === -1) {
        possible = false;
        break;
      }

      cur = actualMax === nextCap ? next : next.subarray(0, actualMax + 1);
      curMax = actualMax;
    }

    dp[v] = possible ? cur : null;
  }

  const rootDp = dp[0];
  if (rootDp === null) return null;

  let ans = Infinity;
  for (let l = 0; l < rootDp.length; l++) {
    if (rootDp[l] < ans) ans = rootDp[l];
  }
  return ans === Infinity ? null : ans;
}

from collections import defaultdict


def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings == 0 or not connections:
        return None

    n = len(transfer)
    trips_raw = defaultdict(list)
    max_arr = 0
    for tid, u, v, dep, arr in connections:
        trips_raw[tid].append((dep, arr, u, v))
        if arr > max_arr:
            max_arr = arr

    inf = max(max_arr, start_time) + max(transfer) + 1

    out = [[] for _ in range(n)]
    trips = []
    trip_done = []
    for t_idx, conns in enumerate(trips_raw.values()):
        conns.sort()
        t_list = []
        for pos, (dep, arr, u, v) in enumerate(conns):
            out[u].append((dep, t_idx, pos))
            t_list.append((v, arr))
        trips.append(t_list)
        trip_done.append(len(t_list))

    for adj in out:
        adj.sort()

    ready = [inf] * n
    ready[source] = start_time
    in_round = [0] * n
    active = [source]
    ans = inf

    for round_id in range(1, max_boardings + 1):
        if not active:
            break
        next_active = []
        for u in active:
            r_u = ready[u]
            if r_u >= ans:
                continue
            adj_u = out[u]
            while adj_u and adj_u[-1][0] >= r_u:
                _, t_idx, pos = adj_u.pop()
                end = trip_done[t_idx]
                if pos < end:
                    trip_done[t_idx] = pos
                    t_conns = trips[t_idx]
                    for j in range(pos, end):
                        v, arr = t_conns[j]
                        if arr >= ans:
                            break
                        if v == target:
                            ans = arr
                            break
                        r_v = arr + transfer[v]
                        if r_v < ready[v]:
                            ready[v] = r_v
                            if in_round[v] != round_id:
                                in_round[v] = round_id
                                next_active.append(v)
        active = next_active

    return ans if ans < inf else None

package main

import "sort"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
	F4 int
}

type conn struct {
	tripID int
	from   int
	to     int
	dep    int
	arr    int
}

type outConn struct {
	dep     int
	tripIdx int
	pos     int
}

func EarliestArrival(connections []Tuple1, transfer []int, source int, target int, start_time int, max_boardings int) *int {
	if source == target {
		res := start_time
		return &res
	}
	n := len(transfer)
	if max_boardings <= 0 || len(connections) == 0 {
		return nil
	}

	conns := make([]conn, len(connections))
	deg := make([]int, n)
	for i, c := range connections {
		conns[i] = conn{
			tripID: c.F0,
			from:   c.F1,
			to:     c.F2,
			dep:    c.F3,
			arr:    c.F4,
		}
		deg[c.F1]++
	}

	sort.Slice(conns, func(i, j int) bool {
		if conns[i].tripID != conns[j].tripID {
			return conns[i].tripID < conns[j].tripID
		}
		return conns[i].dep < conns[j].dep
	})

	connsFrom := make([][]outConn, n)
	allOut := make([]outConn, len(conns))
	offset := 0
	for u := 0; u < n; u++ {
		connsFrom[u] = allOut[offset : offset : offset+deg[u]]
		offset += deg[u]
	}

	var trips [][]conn
	for i := 0; i < len(conns); {
		j := i + 1
		tid := conns[i].tripID
		for j < len(conns) && conns[j].tripID == tid {
			j++
		}
		tripIdx := len(trips)
		trips = append(trips, conns[i:j])
		for k := i; k < j; k++ {
			u := conns[k].from
			connsFrom[u] = append(connsFrom[u], outConn{
				dep:     conns[k].dep,
				tripIdx: tripIdx,
				pos:     k - i,
			})
		}
		i = j
	}

	ptr := make([]int, n)
	for u := 0; u < n; u++ {
		out := connsFrom[u]
		if len(out) > 1 {
			sort.Slice(out, func(i, j int) bool {
				return out[i].dep < out[j].dep
			})
		}
		ptr[u] = len(out)
	}

	const inf = int(1 << 60)
	ready := make([]int, n)
	nextReady := make([]int, n)
	lastMarked := make([]int, n)
	for i := 0; i < n; i++ {
		ready[i] = inf
		nextReady[i] = inf
	}
	ready[source] = start_time
	nextReady[source] = start_time

	earliestBoarded := make([]int, len(trips))
	for i, tr := range trips {
		earliestBoarded[i] = len(tr)
	}

	marked := make([]int, 1, n)
	marked[0] = source
	nextMarked := make([]int, 0, n)

	maxRounds := max_boardings
	if maxRounds > n-1 {
		maxRounds = n - 1
	}

	bestTarget := inf
	for round := 1; round <= maxRounds && len(marked) > 0; round++ {
		nextMarked = nextMarked[:0]
		for _, u := range marked {
			ru := ready[u]
			out := connsFrom[u]
			p := ptr[u]
			for p > 0 && out[p-1].dep >= ru {
				p--
				oc := out[p]
				t := oc.tripIdx
				idx := oc.pos
				eb := earliestBoarded[t]
				if idx < eb {
					tripConns := trips[t]
					for j := idx; j < eb; j++ {
						c := &tripConns[j]
						v := c.to
						arr := c.arr
						if v == target && arr < bestTarget {
							bestTarget = arr
						}
						r := arr + transfer[v]
						if r < nextReady[v] {
							if lastMarked[v] != round {
								lastMarked[v] = round
								nextMarked = append(nextMarked, v)
							}
							nextReady[v] = r
						}
					}
					earliestBoarded[t] = idx
				}
			}
			ptr[u] = p
		}
		for _, v := range nextMarked {
			ready[v] = nextReady[v]
		}
		marked, nextMarked = nextMarked, marked
	}

	if bestTarget == inf {
		return nil
	}
	res := bestTarget
	return &res
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3, long f4) {}

    private static void sortConns(int[] a, int l, int r, int[] tmp, long[] dep, boolean desc) {
        if (r - l <= 16) {
            for (int i = l + 1; i < r; i++) {
                int x = a[i];
                long dx = dep[x];
                int j = i - 1;
                if (desc) {
                    while (j >= l && dep[a[j]] < dx) {
                        a[j + 1] = a[j];
                        j--;
                    }
                } else {
                    while (j >= l && dep[a[j]] > dx) {
                        a[j + 1] = a[j];
                        j--;
                    }
                }
                a[j + 1] = x;
            }
            return;
        }
        int mid = (l + r) >>> 1;
        sortConns(a, l, mid, tmp, dep, desc);
        sortConns(a, mid, r, tmp, dep, desc);
        System.arraycopy(a, l, tmp, l, r - l);
        int i = l, j = mid, k = l;
        while (i < mid && j < r) {
            boolean takeLeft = desc ? (dep[tmp[i]] >= dep[tmp[j]]) : (dep[tmp[i]] <= dep[tmp[j]]);
            if (takeLeft) {
                a[k++] = tmp[i++];
            } else {
                a[k++] = tmp[j++];
            }
        }
        while (i < mid) {
            a[k++] = tmp[i++];
        }
        while (j < r) {
            a[k++] = tmp[j++];
        }
    }

    public static Long earliestArrival(List<Tuple1> connections, List<Long> transfer, long source, long target, long start_time, long max_boardings) {
        if (source == target) {
            return start_time;
        }
        if (max_boardings <= 0 || connections.isEmpty()) {
            return null;
        }

        int n = transfer.size();
        int m = connections.size();
        int src = (int) source;
        int tgt = (int) target;

        long[] trans = new long[n];
        for (int i = 0; i < n; i++) {
            trans[i] = transfer.get(i);
        }

        int[] from = new int[m];
        int[] to = new int[m];
        long[] dep = new long[m];
        long[] arr = new long[m];
        int[] tripIdx = new int[m];
        int[] stationCounts = new int[n];

        HashMap<Long, Integer> tripMap = new HashMap<>(Math.min(m, 16384));
        int numTrips = 0;
        for (int i = 0; i < m; i++) {
            Tuple1 c = connections.get(i);
            Integer tid = tripMap.get(c.f0());
            if (tid == null) {
                tid = numTrips++;
                tripMap.put(c.f0(), tid);
            }
            tripIdx[i] = tid;
            int u = (int) c.f1();
            from[i] = u;
            to[i] = (int) c.f2();
            dep[i] = c.f3();
            arr[i] = c.f4();
            stationCounts[u]++;
        }

        int[] tripCounts = new int[numTrips];
        for (int i = 0; i < m; i++) {
            tripCounts[tripIdx[i]]++;
        }

        int[] tripStart = new int[numTrips + 1];
        for (int t = 0; t < numTrips; t++) {
            tripStart[t + 1] = tripStart[t] + tripCounts[t];
        }
        int[] tripWrite = tripStart.clone();
        int[] tripConns = new int[m];
        for (int i = 0; i < m; i++) {
            tripConns[tripWrite[tripIdx[i]]++] = i;
        }

        int[] tmp = new int[m];
        int[] posInTrip = new int[m];
        int[] earliestBoarded = new int[numTrips];
        for (int t = 0; t < numTrips; t++) {
            int l = tripStart[t];
            int r = tripStart[t + 1];
            sortConns(tripConns, l, r, tmp, dep, false);
            int len = r - l;
            earliestBoarded[t] = len;
            for (int p = 0; p < len; p++) {
                posInTrip[tripConns[l + p]] = p;
            }
        }

        int[] stationStart = new int[n + 1];
        for (int u = 0; u < n; u++) {
            stationStart[u + 1] = stationStart[u] + stationCounts[u];
        }
        int[] stationWrite = stationStart.clone();
        int[] stationConns = new int[m];
        for (int i = 0; i < m; i++) {
            stationConns[stationWrite[from[i]]++] = i;
        }

        int[] nextConnPtr = new int[n];
        for (int u = 0; u < n; u++) {
            int l = stationStart[u];
            int r = stationStart[u + 1];
            sortConns(stationConns, l, r, tmp, dep, true);
            nextConnPtr[u] = l;
        }

        final long INF = Long.MAX_VALUE / 4;
        long[] currReady = new long[n];
        long[] nextReady = new long[n];
        Arrays.fill(currReady, INF);
        Arrays.fill(nextReady, INF);
        currReady[src] = start_time;
        nextReady[src] = start_time;

        int[] frontier = new int[n];
        int[] nextFrontier = new int[n];
        boolean[] inNext = new boolean[n];
        frontier[0] = src;
        int frontierSize = 1;

        long ans = INF;
        int maxRounds = (int) Math.min(max_boardings, (long) n - 1);

        for (int round = 0; round < maxRounds && frontierSize > 0; round++) {
            int nextFrontierSize = 0;

            for (int i = 0; i < frontierSize; i++) {
                int u = frontier[i];
                long r = currReady[u];
                if (r >= ans) {
                    continue;
                }
                int ptr = nextConnPtr[u];
                int end = stationStart[u + 1];
                while (ptr < end && dep[stationConns[ptr]] >= r) {
                    int c = stationConns[ptr++];
                    int t = tripIdx[c];
                    int pos = posInTrip[c];
                    int limit = earliestBoarded[t];
                    if (pos < limit) {
                        int base = tripStart[t];
                        for (int j = pos; j < limit; j++) {
                            int cj = tripConns[base + j];
                            int v = to[cj];
                            long a = arr[cj];
                            if (v == tgt && a < ans) {
                                ans = a;
                            }
                            long readyV = a + trans[v];
                            if (readyV < nextReady[v] && readyV < ans) {
                                nextReady[v] = readyV;
                                if (!inNext[v] && nextConnPtr[v] < stationStart[v + 1]) {
                                    inNext[v] = true;
                                    nextFrontier[nextFrontierSize++] = v;
                                }
                            }
                        }
                        earliestBoarded[t] = pos;
                    }
                }
                nextConnPtr[u] = ptr;
            }

            if (nextFrontierSize == 0) {
                break;
            }
            for (int i = 0; i < nextFrontierSize; i++) {
                int v = nextFrontier[i];
                currReady[v] = nextReady[v];
                inNext[v] = false;
            }
            int[] swap = frontier;
            frontier = nextFrontier;
            nextFrontier = swap;
            frontierSize = nextFrontierSize;
        }

        return ans == INF ? null : ans;
    }
}

#include <algorithm>
#include <limits>
#include <optional>
#include <tuple>
#include <utility>
#include <vector>

std::optional<long long> earliest_arrival(
    const std::vector<std::tuple<long long, long long, long long, long long, long long>>& connections,
    const std::vector<long long>& transfer,
    long long source,
    long long target,
    long long start_time,
    long long max_boardings) {
    if (source == target) {
        return start_time;
    }

    const long long n_ll = static_cast<long long>(transfer.size());
    if (max_boardings <= 0 || source < 0 || source >= n_ll || target < 0 || target >= n_ll) {
        return std::nullopt;
    }

    const int n = static_cast<int>(n_ll);
    const int src = static_cast<int>(source);
    const int dst = static_cast<int>(target);
    const int m = static_cast<int>(connections.size());
    if (m == 0) {
        return std::nullopt;
    }

    struct Conn {
        long long trip_id;
        long long dep;
        long long arr;
        int from;
        int to;
    };

    std::vector<Conn> conns;
    conns.reserve(m);
    for (const auto& c : connections) {
        conns.push_back({
            std::get<0>(c),
            std::get<3>(c),
            std::get<4>(c),
            static_cast<int>(std::get<1>(c)),
            static_cast<int>(std::get<2>(c))
        });
    }

    std::sort(conns.begin(), conns.end(), [](const Conn& a, const Conn& b) {
        if (a.trip_id != b.trip_id) {
            return a.trip_id < b.trip_id;
        }
        return a.dep < b.dep;
    });

    std::vector<int> conn_trip(m);
    std::vector<int> boarded_until;
    int num_trips = 0;
    for (int i = 0; i < m;) {
        int j = i + 1;
        while (j < m && conns[j].trip_id == conns[i].trip_id) {
            ++j;
        }
        for (int k = i; k < j; ++k) {
            conn_trip[k] = num_trips;
        }
        boarded_until.push_back(j);
        ++num_trips;
        i = j;
    }

    std::vector<std::vector<std::pair<long long, int>>> adj(n);
    for (int i = 0; i < m; ++i) {
        adj[conns[i].from].emplace_back(conns[i].dep, i);
    }

    std::vector<int> ptr(n);
    for (int s = 0; s < n; ++s) {
        std::sort(adj[s].begin(), adj[s].end(), [](const auto& a, const auto& b) {
            return a.first < b.first;
        });
        ptr[s] = static_cast<int>(adj[s].size());
    }

    constexpr long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> best_arr(n, INF);
    std::vector<long long> next_arr(n, INF);
    std::vector<long long> cur_ready(n, INF);
    std::vector<int> last_improved_round(n, 0);

    cur_ready[src] = start_time;
    std::vector<int> improved = {src};
    std::vector<int> next_improved;

    const int max_rounds = static_cast<int>(std::min<long long>(max_boardings, n - 1));

    for (int round = 1; round <= max_rounds && !improved.empty(); ++round) {
        next_improved.clear();
        for (int x : improved) {
            const long long r_time = cur_ready[x];
            if (r_time >= best_arr[dst]) {
                continue;
            }
            const auto& edges = adj[x];
            int p = ptr[x];
            while (p > 0 && edges[p - 1].first >= r_time) {
                --p;
                const int c_idx = edges[p].second;
                const int t = conn_trip[c_idx];
                const int limit = boarded_until[t];
                if (c_idx < limit) {
                    boarded_until[t] = c_idx;
                    for (int k = c_idx; k < limit; ++k) {
                        const int y = conns[k].to;
                        const long long arr = conns[k].arr;
                        if (arr < next_arr[y]) {
                            next_arr[y] = arr;
                            if (last_improved_round[y] != round) {
                                last_improved_round[y] = round;
                                next_improved.push_back(y);
                            }
                        }
                    }
                }
            }
            ptr[x] = p;
        }

        improved.clear();
        for (int y : next_improved) {
            best_arr[y] = next_arr[y];
        }
        const long long dst_bound = best_arr[dst];
        for (int y : next_improved) {
            if (y != src) {
                const long long new_ready = best_arr[y] + transfer[y];
                if (new_ready < cur_ready[y]) {
                    cur_ready[y] = new_ready;
                    if (new_ready < dst_bound) {
                        improved.push_back(y);
                    }
                }
            }
        }
    }

    if (best_arr[dst] == INF) {
        return std::nullopt;
    }
    return best_arr[dst];
}

export function earliestArrival(
  connections: [number, number, number, number, number][],
  transfer: number[],
  source: number,
  target: number,
  start_time: number,
  max_boardings: number
): number | null {
  if (source === target) {
    return start_time;
  }
  const m = connections.length;
  if (m === 0 || max_boardings <= 0) {
    return null;
  }

  const n = transfer.length;
  const order = new Int32Array(m);
  const tripIdx = new Int32Array(m);
  const tripMap = new Map<number, number>();
  let numTrips = 0;

  for (let i = 0; i < m; i++) {
    order[i] = i;
    const tid = connections[i][0];
    let id = tripMap.get(tid);
    if (id === undefined) {
      id = numTrips++;
      tripMap.set(tid, id);
    }
    tripIdx[i] = id;
  }

  order.sort((a, b) => connections[a][3] - connections[b][3]);

  const minBoardings = new Float64Array(n);
  minBoardings.fill(Infinity);
  const tripBoardings = new Float64Array(numTrips);
  tripBoardings.fill(Infinity);

  const maxHeap = m + 1;
  const heapTime = new Float64Array(maxHeap);
  const heapStation = new Int32Array(maxHeap);
  const heapBoardings = new Int32Array(maxHeap);
  let heapSize = 0;

  // Initial ready state at source with 0 boardings
  heapTime[0] = start_time;
  heapStation[0] = source;
  heapBoardings[0] = 0;
  heapSize = 1;

  let bestArr = Infinity;

  for (let k = 0; k < m; k++) {
    const idx = order[k];
    const conn = connections[idx];
    const dep = conn[3];
    if (dep >= bestArr) {
      break;
    }

    while (heapSize > 0 && heapTime[0] <= dep) {
      const st = heapStation[0];
      const b = heapBoardings[0];
      if (b < minBoardings[st]) {
        minBoardings[st] = b;
      }

      const last = --heapSize;
      if (last > 0) {
        const t = heapTime[last];
        const sLast = heapStation[last];
        const bLast = heapBoardings[last];
        let i = 0;
        const half = last >> 1;
        while (i < half) {
          let c = (i << 1) + 1;
          const r = c + 1;
          if (r < last && heapTime[r] < heapTime[c]) {
            c = r;
          }
          if (t <= heapTime[c]) {
            break;
          }
          heapTime[i] = heapTime[c];
          heapStation[i] = heapStation[c];
          heapBoardings[i] = heapBoardings[c];
          i = c;
        }
        heapTime[i] = t;
        heapStation[i] = sLast;
        heapBoardings[i] = bLast;
      }
    }

    const u = conn[1];
    const tid = tripIdx[idx];
    const bStay = tripBoardings[tid];
    const bBoard = minBoardings[u] + 1;
    const b = bStay < bBoard ? bStay : bBoard;

    if (b > max_boardings) {
      continue;
    }

    tripBoardings[tid] = b;

    const v = conn[2];
    const arr = conn[4];
    if (v === target && arr < bestArr) {
      bestArr = arr;
    }

    const readyTime = arr + transfer[v];
    if (b < minBoardings[v] && readyTime < bestArr) {
      let i = heapSize++;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (heapTime[p] <= readyTime) {
          break;
        }
        heapTime[i] = heapTime[p];
        heapStation[i] = heapStation[p];
        heapBoardings[i] = heapBoardings[p];
        i = p;
      }
      heapTime[i] = readyTime;
      heapStation[i] = v;
      heapBoardings[i] = b;
    }
  }

  return bestArr === Infinity ? null : bestArr;
}

from collections import deque


def run_kiosk(levels, threshold, patience, arrivals):
    n = len(arrivals)
    for i in range(1, n):
        if arrivals[i][0] < arrivals[i - 1][0]:
            raise ValueError("arrivals must have non-decreasing times")

    if n == 0:
        return []

    base = list(levels)  # uncapped charge at time t is t + base[k]
    queue = deque()      # stores (leave_t, drone, charge)
    out = []

    idx = 0
    t = arrivals[0][0]

    while idx < n or queue:
        # 1. Serve the queue
        while queue:
            cap = 100 - t
            best_b = threshold - t - 1
            best_k = -1
            for k, b in enumerate(base):
                if b > best_b:
                    if b >= cap:
                        best_k = k
                        break
                    best_b = b
                    best_k = k
            if best_k == -1:
                break
            _, drone, d_charge = queue.popleft()
            out.append((drone, "SWAP", t, best_k))
            base[best_k] = d_charge - t

        # 2. Handle arrivals at time t
        while idx < n and arrivals[idx][0] == t:
            arr_t, drone, d_charge = arrivals[idx]
            idx += 1
            if not queue:
                cap = 100 - t
                best_b = threshold - t - 1
                best_k = -1
                for k, b in enumerate(base):
                    if b > best_b:
                        if b >= cap:
                            best_k = k
                            break
                        best_b = b
                        best_k = k
                if best_k != -1:
                    out.append((drone, "SWAP", t, best_k))
                    base[best_k] = d_charge - t
                    continue
            queue.append((arr_t + patience, drone, d_charge))

        # 3. Give up
        while queue and queue[0][0] <= t:
            _, drone, _ = queue.popleft()
            out.append((drone, "LEFT", t))

        # Advance to the next event time
        if not queue:
            if idx == n:
                break
            t = arrivals[idx][0]
        else:
            t_next = threshold - max(base)
            if queue[0][0] < t_next:
                t_next = queue[0][0]
            if idx < n and arrivals[idx][0] < t_next:
                t_next = arrivals[idx][0]
            t = t_next

    return out

package main

import "errors"

type Tuple1 struct {
	F0 int
	F1 string
	F2 int
	F3 bool
}

type clientState struct {
	tokens      int
	lastSteps   int
	bannedUntil int
	strikes     []int
	head        int
}

func AdmitRequests(requests []Tuple1, config map[string]int) ([]string, error) {
	for i := 1; i < len(requests); i++ {
		if requests[i].F0 < requests[i-1].F0 {
			return nil, errors.New("request timestamps must be non-decreasing")
		}
	}

	capVal := config["cap"]
	period := config["period"]
	gcap := config["gcap"]
	gperiod := config["gperiod"]
	reserve := config["reserve"]
	strikesLimit := config["strikes"]
	window := config["window"]
	banLen := config["ban"]

	globalTokens := gcap
	globalLastSteps := 0

	clients := make(map[string]*clientState)
	res := make([]string, len(requests))

	for i, req := range requests {
		t := req.F0
		name := req.F1
		cost := req.F2
		vip := req.F3

		// Global refill up to time t
		gSteps := t / gperiod
		if gSteps > globalLastSteps {
			delta := gSteps - globalLastSteps
			if delta >= gcap-globalTokens {
				globalTokens = gcap
			} else {
				globalTokens += delta
			}
			globalLastSteps = gSteps
		}

		// Get or create client bucket and refill up to time t
		cl, exists := clients[name]
		if !exists {
			cl = &clientState{
				tokens:      capVal,
				lastSteps:   t / period,
				bannedUntil: -1,
			}
			clients[name] = cl
		} else {
			cSteps := t / period
			if cSteps > cl.lastSteps {
				delta := cSteps - cl.lastSteps
				if delta >= capVal-cl.tokens {
					cl.tokens = capVal
				} else {
					cl.tokens += delta
				}
				cl.lastSteps = cSteps
			}
		}

		// Rule 1: banned
		if t < cl.bannedUntil {
			res[i] = "BANNED"
			continue
		}

		// Rule 2: client bucket check
		if cl.tokens < cost {
			cutoff := t - window
			for cl.head < len(cl.strikes) && cl.strikes[cl.head] <= cutoff {
				cl.head++
			}
			if cl.head == len(cl.strikes) {
				cl.strikes = cl.strikes[:0]
				cl.head = 0
			} else if cl.head*2 >= len(cl.strikes) {
				n := copy(cl.strikes, cl.strikes[cl.head:])
				cl.strikes = cl.strikes[:n]
				cl.head = 0
			}

			cl.strikes = append(cl.strikes, t)
			if len(cl.strikes)-cl.head >= strikesLimit {
				cl.bannedUntil = t + banLen
				cl.strikes = cl.strikes[:0]
				cl.head = 0
				res[i] = "BAN"
			} else {
				res[i] = "DENY"
			}
			continue
		}

		// Rule 3: global bucket check
		var globalOK bool
		if vip {
			globalOK = globalTokens >= cost
		} else {
			globalOK = globalTokens >= reserve && globalTokens-reserve >= cost
		}
		if !globalOK {
			res[i] = "BUSY"
			continue
		}

		// Rule 4: admit
		cl.tokens -= cost
		globalTokens -= cost
		res[i] = "OK"
	}

	return res, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, String f1, long f2, boolean f3) {}

    private static final class ClientState {
        long tokens;
        long lastTime;
        long bannedUntil;
        final ArrayDeque<Long> strikes;

        ClientState(long cap, long firstTime) {
            this.tokens = cap;
            this.lastTime = firstTime;
            this.bannedUntil = -1L;
            this.strikes = new ArrayDeque<>();
        }
    }

    public static List<String> admitRequests(List<Tuple1> requests, Map<String, Long> config) {
        long prevT = 0L;
        boolean hasPrev = false;
        for (Tuple1 req : requests) {
            long t = req.f0();
            if (t < 0L) {
                throw new IllegalArgumentException("Timestamp must be non-negative");
            }
            if (hasPrev && t < prevT) {
                throw new IllegalArgumentException("Request timestamps must be non-decreasing");
            }
            prevT = t;
            hasPrev = true;
        }

        long cap = config.get("cap");
        long period = config.get("period");
        long gcap = config.get("gcap");
        long gperiod = config.get("gperiod");
        long reserve = config.get("reserve");
        long strikesLimit = config.get("strikes");
        long window = config.get("window");
        long banLength = config.get("ban");

        long globalTokens = gcap;
        long globalLastTime = 0L;

        Map<String, ClientState> clients = new HashMap<>();
        List<String> result = new ArrayList<>(requests.size());

        for (Tuple1 req : requests) {
            long t = req.f0();
            String client = req.f1();
            long cost = req.f2();
            boolean vip = req.f3();

            // Advance global bucket refills up to time t
            long globalRefills = t / gperiod - globalLastTime / gperiod;
            if (globalRefills > 0L) {
                globalTokens = Math.min(gcap, globalTokens + globalRefills);
            }
            globalLastTime = t;

            // Get or create client bucket and advance refills up to time t
            ClientState cs = clients.get(client);
            if (cs == null) {
                cs = new ClientState(cap, t);
                clients.put(client, cs);
            } else {
                long clientRefills = t / period - cs.lastTime / period;
                if (clientRefills > 0L) {
                    cs.tokens = Math.min(cap, cs.tokens + clientRefills);
                }
                cs.lastTime = t;
            }

            // Rule 1: Check ban
            if (t < cs.bannedUntil) {
                result.add("BANNED");
                continue;
            }

            // Rule 2: Check client bucket
            if (cs.tokens < cost) {
                long cutoff = t - window;
                while (!cs.strikes.isEmpty() && cs.strikes.peekFirst() <= cutoff) {
                    cs.strikes.pollFirst();
                }
                cs.strikes.addLast(t);
                if (cs.strikes.size() >= strikesLimit) {
                    cs.strikes.clear();
                    cs.bannedUntil = t + banLength;
                    result.add("BAN");
                } else {
                    result.add("DENY");
                }
                continue;
            }

            // Rule 3: Check global bucket
            boolean globalOk = globalTokens >= cost && (vip || globalTokens - cost >= reserve);
            if (!globalOk) {
                result.add("BUSY");
                continue;
            }

            // Rule 4: Admit request
            cs.tokens -= cost;
            globalTokens -= cost;
            result.add("OK");
        }

        return result;
    }
}

#include <algorithm>
#include <cstddef>
#include <deque>
#include <map>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> admit_requests(
    const std::vector<std::tuple<long long, std::string, long long, bool>>& requests,
    const std::map<std::string, long long>& config) {
    for (std::size_t i = 0; i < requests.size(); ++i) {
        long long t = std::get<0>(requests[i]);
        if (t < 0 || (i > 0 && t < std::get<0>(requests[i - 1]))) {
            throw std::invalid_argument("Request timestamps must be non-negative and non-decreasing.");
        }
    }

    const long long cap = config.at("cap");
    const long long period = config.at("period");
    const long long gcap = config.at("gcap");
    const long long gperiod = config.at("gperiod");
    const long long reserve = config.at("reserve");
    const long long strikes = config.at("strikes");
    const long long window = config.at("window");
    const long long ban = config.at("ban");

    struct ClientState {
        long long tokens;
        long long last_t;
        long long ban_until = -1;
        std::deque<long long> strike_times;
    };

    std::unordered_map<std::string, ClientState> clients;
    long long global_tokens = gcap;
    long long global_last_t = 0;

    std::vector<std::string> results;
    results.reserve(requests.size());

    for (const auto& [t, client_name, cost, vip] : requests) {
        global_tokens = std::min(gcap, global_tokens + (t / gperiod - global_last_t / gperiod));
        global_last_t = t;

        auto [it, inserted] = clients.try_emplace(client_name, ClientState{cap, t, -1, {}});
        ClientState& client = it->second;
        if (!inserted) {
            client.tokens = std::min(cap, client.tokens + (t / period - client.last_t / period));
            client.last_t = t;
        }

        if (t < client.ban_until) {
            results.emplace_back("BANNED");
            continue;
        }

        if (client.tokens < cost) {
            long long cutoff = t - window;
            while (!client.strike_times.empty() && client.strike_times.front() <= cutoff) {
                client.strike_times.pop_front();
            }
            client.strike_times.push_back(t);
            if (static_cast<long long>(client.strike_times.size()) >= strikes) {
                client.ban_until = t + ban;
                client.strike_times.clear();
                results.emplace_back("BAN");
            } else {
                results.emplace_back("DENY");
            }
            continue;
        }

        bool global_ok = vip ? (global_tokens >= cost)
                             : (global_tokens >= cost && global_tokens - cost >= reserve);
        if (!global_ok) {
            results.emplace_back("BUSY");
            continue;
        }

        client.tokens -= cost;
        global_tokens -= cost;
        results.emplace_back("OK");
    }

    return results;
}

type ClientState = {
  tokens: number;
  lastStep: number;
  bannedUntil: number;
  strikes: number[];
  strikeHead: number;
};

function divFloor(a: number, b: number): number {
  return (a - (a % b)) / b;
}

export function admitRequests(
  requests: [number, string, number, boolean][],
  config: Record<string, number>,
): string[] {
  const n = requests.length;
  for (let i = 1; i < n; i++) {
    if (requests[i][0] < requests[i - 1][0]) {
      throw new Error("Request timestamps must be non-decreasing");
    }
  }

  const cap = config.cap;
  const period = config.period;
  const gcap = config.gcap;
  const gperiod = config.gperiod;
  const reserve = config.reserve;
  const strikeLimit = config.strikes;
  const window = config.window;
  const ban = config.ban;

  let globalTokens = gcap;
  let lastGlobalStep = 0;

  const clients = new Map<string, ClientState>();
  const result = new Array<string>(n);

  for (let i = 0; i < n; i++) {
    const req = requests[i];
    const t = req[0];
    const clientName = req[1];
    const cost = req[2];
    const vip = req[3];

    const curGlobalStep = divFloor(t, gperiod);
    if (curGlobalStep > lastGlobalStep) {
      globalTokens = Math.min(gcap, globalTokens + (curGlobalStep - lastGlobalStep));
      lastGlobalStep = curGlobalStep;
    }

    const curClientStep = divFloor(t, period);
    let client = clients.get(clientName);
    if (client === undefined) {
      client = {
        tokens: cap,
        lastStep: curClientStep,
        bannedUntil: 0,
        strikes: [],
        strikeHead: 0,
      };
      clients.set(clientName, client);
    } else if (curClientStep > client.lastStep) {
      client.tokens = Math.min(cap, client.tokens + (curClientStep - client.lastStep));
      client.lastStep = curClientStep;
    }

    if (t < client.bannedUntil) {
      result[i] = "BANNED";
      continue;
    }

    if (client.tokens < cost) {
      client.strikes.push(t);
      const cutoff = t - window;
      while (
        client.strikeHead < client.strikes.length &&
        client.strikes[client.strikeHead] <= cutoff
      ) {
        client.strikeHead++;
      }

      if (client.strikes.length - client.strikeHead >= strikeLimit) {
        client.strikes = [];
        client.strikeHead = 0;
        client.bannedUntil = t + ban;
        result[i] = "BAN";
      } else {
        result[i] = "DENY";
      }
      continue;
    }

    const globalOk = vip
      ? globalTokens >= cost
      : globalTokens - cost >= reserve;

    if (!globalOk) {
      result[i] = "BUSY";
      continue;
    }

    client.tokens -= cost;
    globalTokens -= cost;
    result[i] = "OK";
  }

  return result;
}

def simulate_vending(prices, stock, bank, events, timeout):
    prev_t = None
    for event in events:
        t = event[0]
        if prev_t is not None and t < prev_t:
            raise ValueError("Event timestamps must be non-decreasing")
        prev_t = t

    cur_stock = dict(stock)
    b5 = bank.get(5, 0)
    b10 = bank.get(10, 0)
    b25 = bank.get(25, 0)
    b100 = bank.get(100, 0)

    escrow = []
    last = 0
    log = []

    for t, kind, arg in events:
        if escrow and t >= last + timeout:
            log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))
            escrow.clear()

        if kind == "coin":
            if arg not in (5, 10, 25, 100) or len(escrow) >= 10:
                log.append(("REJECT", t, arg))
            else:
                escrow.append(arg)
                last = t
        elif kind == "select":
            last = t
            if arg not in prices:
                log.append(("UNKNOWN", t, arg))
            elif cur_stock[arg] == 0:
                log.append(("SOLD_OUT", t, arg))
            else:
                price = prices[arg]
                total = sum(escrow)
                if total < price:
                    log.append(("NEED", t, price - total))
                else:
                    nb5, nb10, nb25, nb100 = b5, b10, b25, b100
                    for c in escrow:
                        if c == 5:
                            nb5 += 1
                        elif c == 10:
                            nb10 += 1
                        elif c == 25:
                            nb25 += 1
                        else:
                            nb100 += 1

                    rem = total - price
                    change = []

                    if rem >= 100 and nb100 > 0:
                        k = min(nb100, rem // 100)
                        nb100 -= k
                        rem -= k * 100
                        change.extend([100] * k)
                    if rem >= 25 and nb25 > 0:
                        k = min(nb25, rem // 25)
                        nb25 -= k
                        rem -= k * 25
                        change.extend([25] * k)
                    if rem >= 10 and nb10 > 0:
                        k = min(nb10, rem // 10)
                        nb10 -= k
                        rem -= k * 10
                        change.extend([10] * k)
                    if rem >= 5 and nb5 > 0:
                        k = min(nb5, rem // 5)
                        nb5 -= k
                        rem -= k * 5
                        change.extend([5] * k)

                    if rem == 0:
                        b5, b10, b25, b100 = nb5, nb10, nb25, nb100
                        cur_stock[arg] -= 1
                        escrow.clear()
                        log.append(("VEND", t, arg, tuple(change)))
                    else:
                        log.append(("EXACT_ONLY", t, arg))
        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow.clear()

    if escrow:
        log.append(("TIMEOUT", last + timeout, tuple(sorted(escrow, reverse=True))))

    return log, (b5, b10, b25, b100)

import re

_NAME_RE = re.compile(r"[a-z0-9_]+", re.ASCII)
_ACTION_WORD_RE = re.compile(r"[a-z]+", re.ASCII)
_ACTION_LIST_RE = re.compile(r"[a-z]+(?:,[a-z]+)*", re.ASCII)
_RES_SEG_RE = re.compile(r"\*\*|\*|[a-z0-9._-]+", re.ASCII)
_PATH_SEG_RE = re.compile(r"[a-z0-9._-]+", re.ASCII)


def _match_at(chunk: tuple[str, ...], path_segs: tuple[str, ...], pos: int) -> bool:
    for i, pat in enumerate(chunk):
        if pat != "*" and pat != path_segs[pos + i]:
            return False
    return True


def _match_resource(
    has_double_star: bool,
    chunks: list[tuple[str, ...]],
    min_len: int,
    req_lits: frozenset[str],
    mid_chunks: list[tuple[tuple[str, ...], int, int, str | None, int]],
    path_segs: tuple[str, ...],
    path_set: set[str],
) -> bool:
    n = len(path_segs)
    if not has_double_star:
        c0 = chunks[0]
        return n == len(c0) and req_lits.issubset(path_set) and _match_at(c0, path_segs, 0)

    if n < min_len or not req_lits.issubset(path_set):
        return False

    c0 = chunks[0]
    if c0 and not _match_at(c0, path_segs, 0):
        return False

    ck = chunks[-1]
    end_limit = n - len(ck)
    if ck and not _match_at(ck, path_segs, end_limit):
        return False

    cur = len(c0)
    for ct, m, lit_offset, lit_val, rem_after in mid_chunks:
        if lit_val is None:
            cur += m
        else:
            max_pos = end_limit - rem_after - m
            search_start = cur + lit_offset
            search_end = max_pos + lit_offset + 1
            matched = False
            while search_start < search_end:
                try:
                    found = path_segs.index(lit_val, search_start, search_end)
                except ValueError:
                    break
                pos = found - lit_offset
                if _match_at(ct, path_segs, pos):
                    cur = pos + m
                    matched = True
                    break
                search_start = found + 1
            if not matched:
                return False

    return True


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    compiled_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")

        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")

        effect, principal, action, resource = fields

        if effect != "ALLOW" and effect != "DENY":
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        if principal == "*":
            p_type = 0
            p_val = None
        elif principal.startswith("user:") and _NAME_RE.fullmatch(principal[5:]):
            p_type = 2
            p_val = principal[5:]
        elif principal.startswith("group:") and _NAME_RE.fullmatch(principal[6:]):
            p_type = 1
            p_val = principal[6:]
        else:
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        if action == "*":
            action_set = None
            a_spec = 0
        elif _ACTION_LIST_RE.fullmatch(action):
            action_set = frozenset(action.split(","))
            a_spec = 1
        else:
            raise ValueError(f"rule {i}: bad action {action!r}")

        if not resource.startswith("/"):
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        if resource == "/":
            segs = ()
        else:
            raw_segs = resource[1:].split("/")
            for seg in raw_segs:
                if not _RES_SEG_RE.fullmatch(seg):
                    raise ValueError(f"rule {i}: bad resource {resource!r}")
            segs = tuple(raw_segs)

        l_spec = 0
        req_lits = []
        chunks = []
        cur_chunk = []
        saw_double_star = False
        has_double_star = False

        for seg in segs:
            if seg == "**":
                has_double_star = True
                if not saw_double_star:
                    chunks.append(tuple(cur_chunk))
                    cur_chunk = []
                    saw_double_star = True
            else:
                saw_double_star = False
                cur_chunk.append(seg)
                if seg != "*":
                    l_spec += 1
                    req_lits.append(seg)
        chunks.append(tuple(cur_chunk))

        min_len = sum(len(c) for c in chunks)
        mid_chunks = []
        if len(chunks) > 2:
            rem = 0
            for t in range(len(chunks) - 2, 0, -1):
                ct = chunks[t]
                lit_offset = -1
                lit_val = None
                for idx, s in enumerate(ct):
                    if s != "*":
                        lit_offset = idx
                        lit_val = s
                        break
                mid_chunks.append((ct, len(ct), lit_offset, lit_val, rem))
                rem += len(ct)
            mid_chunks.reverse()

        sort_key = (-l_spec, -p_type, -a_spec, 0 if effect == "DENY" else 1, i)
        compiled_rules.append((
            sort_key,
            p_type,
            p_val,
            action_set,
            has_double_star,
            chunks,
            min_len,
            frozenset(req_lits),
            mid_chunks,
            f"{effect} by rule {i}",
        ))

    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")

        user, groups, action, path = req

        if not isinstance(user, str) or not _NAME_RE.fullmatch(user):
            raise ValueError(f"request {j}: bad user {user!r}")

        if not isinstance(groups, list):
            raise ValueError(f"request {j}: bad groups")
        for g in groups:
            if not isinstance(g, str) or not _NAME_RE.fullmatch(g):
                raise ValueError(f"request {j}: bad groups")

        if not isinstance(action, str) or not _ACTION_WORD_RE.fullmatch(action):
            raise ValueError(f"request {j}: bad action {action!r}")

        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError(f"request {j}: bad path {path!r}")
        if path == "/":
            path_segs = ()
        else:
            raw_p_segs = path[1:].split("/")
            for seg in raw_p_segs:
                if not _PATH_SEG_RE.fullmatch(seg):
                    raise ValueError(f"request {j}: bad path {path!r}")
            path_segs = tuple(raw_p_segs)

        parsed_requests.append((user, set(groups), action, path_segs, set(path_segs)))

    compiled_rules.sort(key=lambda r: r[0])

    decisions = []
    for user, group_set, action, path_segs, path_set in parsed_requests:
        for (
            _,
            p_type,
            p_val,
            action_set,
            has_double_star,
            chunks,
            min_len,
            req_lits,
            mid_chunks,
            decision,
        ) in compiled_rules:
            if p_type == 2:
                if p_val != user:
                    continue
            elif p_type == 1:
                if p_val not in group_set:
                    continue

            if action_set is not None and action not in action_set:
                continue

            if _match_resource(
                has_double_star, chunks, min_len, req_lits, mid_chunks, path_segs, path_set
            ):
                decisions.append(decision)
                break
        else:
            decisions.append("DENY by default")

    return decisions

package main

import (
	"fmt"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 []string
	F2 string
	F3 string
}

type parsedRule struct {
	deny      bool
	pKind     int // 0: "*", 1: "group:...", 2: "user:..."
	pName     string
	anyAction bool
	actionMap map[string]struct{}
	resSegs   []string
	specL     int
	specP     int
	specA     int
}

func isName(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func isActionWord(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') {
			return false
		}
	}
	return true
}

func isPathSeg(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-') {
			return false
		}
	}
	return true
}

func isResourceSeg(s string) bool {
	if s == "*" || s == "**" {
		return true
	}
	return isPathSeg(s)
}

func parseResource(s string) ([]string, int, bool) {
	if len(s) == 0 || s[0] != '/' {
		return nil, 0, false
	}
	if s == "/" {
		return nil, 0, true
	}
	segs := strings.Split(s[1:], "/")
	litCount := 0
	for _, seg := range segs {
		if !isResourceSeg(seg) {
			return nil, 0, false
		}
		if seg != "*" && seg != "**" {
			litCount++
		}
	}
	return segs, litCount, true
}

func parsePath(s string) ([]string, bool) {
	if len(s) == 0 || s[0] != '/' {
		return nil, false
	}
	if s == "/" {
		return nil, true
	}
	segs := strings.Split(s[1:], "/")
	for _, seg := range segs {
		if !isPathSeg(seg) {
			return nil, false
		}
	}
	return segs, true
}

func matchSegments(pat, path []string) bool {
	pi, si := 0, 0
	starPat, starPath := -1, 0
	for si < len(path) {
		if pi < len(pat) && (pat[pi] == "*" || pat[pi] == path[si]) {
			pi++
			si++
		} else if pi < len(pat) && pat[pi] == "**" {
			starPat = pi
			starPath = si
			pi++
		} else if starPat != -1 {
			pi = starPat + 1
			starPath++
			si = starPath
		} else {
			return false
		}
	}
	for pi < len(pat) && pat[pi] == "**" {
		pi++
	}
	return pi == len(pat)
}

func cmpSpec(l1, p1, a1, l2, p2, a2 int) int {
	if l1 != l2 {
		if l1 > l2 {
			return 1
		}
		return -1
	}
	if p1 != p2 {
		if p1 > p2 {
			return 1
		}
		return -1
	}
	if a1 != a2 {
		if a1 > a2 {
			return 1
		}
		return -1
	}
	return 0
}

func EvaluateAccess(rules []string, requests []Tuple1) ([]string, error) {
	parsedRules := make([]parsedRule, len(rules))
	for i, rule := range rules {
		fields := strings.Fields(rule)
		if len(fields) != 4 {
			return nil, fmt.Errorf("rule %d: expected 4 fields, got %d", i, len(fields))
		}
		effect, principal, action, resource := fields[0], fields[1], fields[2], fields[3]

		var pr parsedRule
		switch effect {
		case "ALLOW":
			pr.deny = false
		case "DENY":
			pr.deny = true
		default:
			return nil, fmt.Errorf("rule %d: bad effect %q", i, effect)
		}

		if principal == "*" {
			pr.pKind = 0
			pr.specP = 0
		} else if strings.HasPrefix(principal, "user:") && isName(principal[5:]) {
			pr.pKind = 2
			pr.pName = principal[5:]
			pr.specP = 2
		} else if strings.HasPrefix(principal, "group:") && isName(principal[6:]) {
			pr.pKind = 1
			pr.pName = principal[6:]
			pr.specP = 1
		} else {
			return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
		}

		if action == "*" {
			pr.anyAction = true
			pr.specA = 0
		} else {
			parts := strings.Split(action, ",")
			pr.actionMap = make(map[string]struct{}, len(parts))
			for _, part := range parts {
				if !isActionWord(part) {
					return nil, fmt.Errorf("rule %d: bad action %q", i, action)
				}
				pr.actionMap[part] = struct{}{}
			}
			pr.specA = 1
		}

		resSegs, specL, ok := parseResource(resource)
		if !ok {
			return nil, fmt.Errorf("rule %d: bad resource %q", i, resource)
		}
		pr.resSegs = resSegs
		pr.specL = specL

		parsedRules[i] = pr
	}

	reqPaths := make([][]string, len(requests))
	for j, req := range requests {
		if !isName(req.F0) {
			return nil, fmt.Errorf("request %d: bad user %q", j, req.F0)
		}
		for _, g := range req.F1 {
			if !isName(g) {
				return nil, fmt.Errorf("request %d: bad groups", j)
			}
		}
		if !isActionWord(req.F2) {
			return nil, fmt.Errorf("request %d: bad action %q", j, req.F2)
		}
		pathSegs, ok := parsePath(req.F3)
		if !ok {
			return nil, fmt.Errorf("request %d: bad path %q", j, req.F3)
		}
		reqPaths[j] = pathSegs
	}

	decisions := make([]string, len(requests))
	for j, req := range requests {
		user := req.F0
		groups := req.F1
		action := req.F2
		pathSegs := reqPaths[j]

		var groupSet map[string]struct{}
		if len(groups) > 4 {
			groupSet = make(map[string]struct{}, len(groups))
			for _, g := range groups {
				groupSet[g] = struct{}{}
			}
		}

		hasMatch := false
		bestL, bestP, bestA := -1, -1, -1
		bestDenyIdx, bestAllowIdx := -1, -1

		for i := range parsedRules {
			r := &parsedRules[i]
			if hasMatch && cmpSpec(r.specL, r.specP, r.specA, bestL, bestP, bestA) < 0 {
				continue
			}

			switch r.pKind {
			case 2:
				if r.pName != user {
					continue
				}
			case 1:
				matchedGroup := false
				if groupSet != nil {
					_, matchedGroup = groupSet[r.pName]
				} else {
					for _, g := range groups {
						if g == r.pName {
							matchedGroup = true
							break
						}
					}
				}
				if !matchedGroup {
					continue
				}
			}

			if !r.anyAction {
				if _, ok := r.actionMap[action]; !ok {
					continue
				}
			}

			if !matchSegments(r.resSegs, pathSegs) {
				continue
			}

			if !hasMatch {
				hasMatch = true
				bestL, bestP, bestA = r.specL, r.specP, r.specA
				if r.deny {
					bestDenyIdx = i
				} else {
					bestAllowIdx = i
				}
			} else {
				c := cmpSpec(r.specL, r.specP, r.specA, bestL, bestP, bestA)
				if c > 0 {
					bestL, bestP, bestA = r.specL, r.specP, r.specA
					bestDenyIdx, bestAllowIdx = -1, -1
					if r.deny {
						bestDenyIdx = i
					} else {
						bestAllowIdx = i
					}
				} else if c == 0 {
					if r.deny {
						if bestDenyIdx == -1 {
							bestDenyIdx = i
						}
					} else {
						if bestAllowIdx == -1 {
							bestAllowIdx = i
						}
					}
				}
			}
		}

		if !hasMatch {
			decisions[j] = "DENY by default"
		} else if bestDenyIdx != -1 {
			decisions[j] = fmt.Sprintf("DENY by rule %d", bestDenyIdx)
		} else {
			decisions[j] = fmt.Sprintf("ALLOW by rule %d", bestAllowIdx)
		}
	}

	return decisions, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, List<String> f1, String f2, String f3) {}

    private static final class ParsedRule {
        final int index;
        final boolean deny;
        final int principalType; // 0 = *, 1 = group, 2 = user
        final String principalName;
        final Set<String> actions; // null means *
        final String[] resourceSegments;
        final int literalCount; // L
        final int actionSpec;   // A: 1 for list, 0 for *

        ParsedRule(int index, boolean deny, int principalType, String principalName,
                   Set<String> actions, String[] resourceSegments, int literalCount) {
            this.index = index;
            this.deny = deny;
            this.principalType = principalType;
            this.principalName = principalName;
            this.actions = actions;
            this.resourceSegments = resourceSegments;
            this.literalCount = literalCount;
            this.actionSpec = (actions == null) ? 0 : 1;
        }
    }

    private static final class ParsedRequest {
        final String user;
        final List<String> groupList;
        final Set<String> groupSet;
        final String action;
        final String[] pathSegments;

        ParsedRequest(String user, List<String> groups, String action, String[] pathSegments) {
            this.user = user;
            if (groups.size() <= 8) {
                this.groupList = groups;
                this.groupSet = null;
            } else {
                this.groupList = null;
                this.groupSet = new HashSet<>(groups);
            }
            this.action = action;
            this.pathSegments = pathSegments;
        }

        boolean hasGroup(String g) {
            if (groupSet != null) {
                return groupSet.contains(g);
            }
            for (int i = 0; i < groupList.size(); i++) {
                if (groupList.get(i).equals(g)) {
                    return true;
                }
            }
            return false;
        }
    }

    public static List<String> evaluateAccess(List<String> rules, List<Tuple1> requests) {
        if (rules == null) {
            throw new IllegalArgumentException("rules must be a list");
        }
        if (requests == null) {
            throw new IllegalArgumentException("requests must be a list");
        }

        List<ParsedRule> parsedRules = new ArrayList<>(rules.size());
        for (int i = 0; i < rules.size(); i++) {
            String rule = rules.get(i);
            if (rule == null) {
                throw new IllegalArgumentException("rule " + i + ": not a str");
            }
            List<String> fields = splitWhitespace(rule);
            if (fields.size() != 4) {
                throw new IllegalArgumentException("rule " + i + ": expected 4 fields, got " + fields.size());
            }

            String effect = fields.get(0);
            boolean deny;
            if (effect.equals("ALLOW")) {
                deny = false;
            } else if (effect.equals("DENY")) {
                deny = true;
            } else {
                throw new IllegalArgumentException("rule " + i + ": bad effect '" + effect + "'");
            }

            String principal = fields.get(1);
            int principalType;
            String principalName;
            if (principal.equals("*")) {
                principalType = 0;
                principalName = null;
            } else if (principal.startsWith("user:") && isName(principal.substring(5))) {
                principalType = 2;
                principalName = principal.substring(5);
            } else if (principal.startsWith("group:") && isName(principal.substring(6))) {
                principalType = 1;
                principalName = principal.substring(6);
            } else {
                throw new IllegalArgumentException("rule " + i + ": bad principal '" + principal + "'");
            }

            String actionStr = fields.get(2);
            Set<String> actions;
            if (actionStr.equals("*")) {
                actions = null;
            } else {
                String[] parts = actionStr.split(",", -1);
                if (parts.length == 0) {
                    throw new IllegalArgumentException("rule " + i + ": bad action '" + actionStr + "'");
                }
                actions = new HashSet<>(parts.length * 2);
                for (String part : parts) {
                    if (!isActionWord(part)) {
                        throw new IllegalArgumentException("rule " + i + ": bad action '" + actionStr + "'");
                    }
                    actions.add(part);
                }
            }

            String resourceStr = fields.get(3);
            String[] resourceSegments = parseResource(resourceStr);
            if (resourceSegments == null) {
                throw new IllegalArgumentException("rule " + i + ": bad resource '" + resourceStr + "'");
            }
            int literalCount = 0;
            for (String seg : resourceSegments) {
                if (!seg.equals("*") && !seg.equals("**")) {
                    literalCount++;
                }
            }

            parsedRules.add(new ParsedRule(i, deny, principalType, principalName, actions, resourceSegments, literalCount));
        }

        List<ParsedRequest> parsedRequests = new ArrayList<>(requests.size());
        for (int j = 0; j < requests.size(); j++) {
            Tuple1 req = requests.get(j);
            if (req == null) {
                throw new IllegalArgumentException("request " + j + ": expected 4-tuple");
            }
            String user = req.f0();
            if (user == null || !isName(user)) {
                throw new IllegalArgumentException("request " + j + ": bad user '" + user + "'");
            }
            List<String> groups = req.f1();
            if (groups == null) {
                throw new IllegalArgumentException("request " + j + ": bad groups");
            }
            for (String g : groups) {
                if (g == null || !isName(g)) {
                    throw new IllegalArgumentException("request " + j + ": bad groups");
                }
            }
            String action = req.f2();
            if (action == null || !isActionWord(action)) {
                throw new IllegalArgumentException("request " + j + ": bad action '" + action + "'");
            }
            String path = req.f3();
            String[] pathSegments = (path == null) ? null : parsePath(path);
            if (pathSegments == null) {
                throw new IllegalArgumentException("request " + j + ": bad path '" + path + "'");
            }

            parsedRequests.add(new ParsedRequest(user, groups, action, pathSegments));
        }

        // Order by specificity (L, P, A) descending, then DENY before ALLOW, then rule index ascending.
        // The first matching rule in this order is guaranteed to be the winning decision.
        parsedRules.sort((a, b) -> {
            int cmp = Integer.compare(b.literalCount, a.literalCount);
            if (cmp != 0) return cmp;
            cmp = Integer.compare(b.principalType, a.principalType);
            if (cmp != 0) return cmp;
            cmp = Integer.compare(b.actionSpec, a.actionSpec);
            if (cmp != 0) return cmp;
            if (a.deny != b.deny) return a.deny ? -1 : 1;
            return Integer.compare(a.index, b.index);
        });

        List<String> decisions = new ArrayList<>(parsedRequests.size());
        for (ParsedRequest req : parsedRequests) {
            String decision = "DENY by default";
            for (ParsedRule rule : parsedRules) {
                if (rule.principalType == 2 && !rule.principalName.equals(req.user)) {
                    continue;
                }
                if (rule.principalType == 1 && !req.hasGroup(rule.principalName)) {
                    continue;
                }
                if (rule.actions != null && !rule.actions.contains(req.action)) {
                    continue;
                }
                if (matchPath(rule.resourceSegments, req.pathSegments)) {
                    decision = (rule.deny ? "DENY by rule " : "ALLOW by rule ") + rule.index;
                    break;
                }
            }
            decisions.add(decision);
        }

        return decisions;
    }

    private static boolean isPythonWhitespace(char c) {
        return Character.isWhitespace(c) || c == '\u0085' || c == '\u00A0' || c == '\u2007' || c == '\u202F';
    }

    private static List<String> splitWhitespace(String s) {
        List<String> parts = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            while (i < n && isPythonWhitespace(s.charAt(i))) {
                i++;
            }
            if (i >= n) break;
            int start = i;
            while (i < n && !isPythonWhitespace(s.charAt(i))) {
                i++;
            }
            parts.add(s.substring(start, i));
        }
        return parts;
    }

    private static boolean isName(String s) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
                return false;
            }
        }
        return true;
    }

    private static boolean isActionWord(String s) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < 'a' || c > 'z') {
                return false;
            }
        }
        return true;
    }

    private static boolean isPathSegment(String s) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) {
                return false;
            }
        }
        return true;
    }

    private static String[] parseResource(String resource) {
        if (resource.equals("/")) {
            return new String[0];
        }
        if (!resource.startsWith("/")) {
            return null;
        }
        String[] segments = resource.substring(1).split("/", -1);
        for (String seg : segments) {
            if (!seg.equals("*") && !seg.equals("**") && !isPathSegment(seg)) {
                return null;
            }
        }
        return segments;
    }

    private static String[] parsePath(String path) {
        if (path.equals("/")) {
            return new String[0];
        }
        if (!path.startsWith("/")) {
            return null;
        }
        String[] segments = path.substring(1).split("/", -1);
        for (String seg : segments) {
            if (!isPathSegment(seg)) {
                return null;
            }
        }
        return segments;
    }

    private static boolean matchPath(String[] pat, String[] path) {
        int pi = 0;
        int si = 0;
        int starPi = -1;
        int starSi = -1;
        int m = pat.length;
        int n = path.length;

        while (si < n) {
            if (pi < m && (pat[pi].equals("*") || pat[pi].equals(path[si]))) {
                pi++;
                si++;
            } else if (pi < m && pat[pi].equals("**")) {
                starPi = pi;
                starSi = si;
                pi++;
            } else if (starPi != -1) {
                pi = starPi + 1;
                starSi++;
                si = starSi;
            } else {
                return false;
            }
        }

        while (pi < m && pat[pi].equals("**")) {
            pi++;
        }
        return pi == m;
    }
}

#include <algorithm>
#include <compare>
#include <cstddef>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <vector>

namespace {

bool is_ws(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

bool is_name(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
            return false;
        }
    }
    return true;
}

bool is_action_word(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (char c : s) {
        if (c < 'a' || c > 'z') {
            return false;
        }
    }
    return true;
}

bool is_path_segment_literal(std::string_view s) {
    if (s.empty()) {
        return false;
    }
    for (char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) {
            return false;
        }
    }
    return true;
}

std::vector<std::string_view> split_ws(std::string_view s) {
    std::vector<std::string_view> fields;
    std::size_t i = 0;
    const std::size_t n = s.size();
    while (i < n) {
        while (i < n && is_ws(s[i])) {
            ++i;
        }
        if (i >= n) {
            break;
        }
        std::size_t start = i;
        while (i < n && !is_ws(s[i])) {
            ++i;
        }
        fields.push_back(s.substr(start, i - start));
    }
    return fields;
}

enum class SegType {
    LITERAL,
    STAR,
    DOUBLE_STAR
};

struct ResourceSeg {
    SegType type;
    std::string_view lit;
};

bool parse_resource(std::string_view s, std::vector<ResourceSeg>& out, int& literal_count) {
    out.clear();
    literal_count = 0;
    if (s.empty() || s[0] != '/') {
        return false;
    }
    if (s.size() == 1) {
        return true;
    }
    if (s.back() == '/') {
        return false;
    }
    std::size_t pos = 1;
    while (true) {
        std::size_t next = s.find('/', pos);
        std::string_view seg = (next == std::string_view::npos)
                                   ? s.substr(pos)
                                   : s.substr(pos, next - pos);
        if (seg.empty()) {
            return false;
        }
        if (seg == "*") {
            out.push_back({SegType::STAR, seg});
        } else if (seg == "**") {
            if (out.empty() || out.back().type != SegType::DOUBLE_STAR) {
                out.push_back({SegType::DOUBLE_STAR, seg});
            }
        } else if (is_path_segment_literal(seg)) {
            out.push_back({SegType::LITERAL, seg});
            ++literal_count;
        } else {
            return false;
        }
        if (next == std::string_view::npos) {
            break;
        }
        pos = next + 1;
    }
    return true;
}

bool parse_path(std::string_view s, std::vector<std::string_view>& out) {
    out.clear();
    if (s.empty() || s[0] != '/') {
        return false;
    }
    if (s.size() == 1) {
        return true;
    }
    if (s.back() == '/') {
        return false;
    }
    std::size_t pos = 1;
    while (true) {
        std::size_t next = s.find('/', pos);
        std::string_view seg = (next == std::string_view::npos)
                                   ? s.substr(pos)
                                   : s.substr(pos, next - pos);
        if (!is_path_segment_literal(seg)) {
            return false;
        }
        out.push_back(seg);
        if (next == std::string_view::npos) {
            break;
        }
        pos = next + 1;
    }
    return true;
}

enum class Effect {
    ALLOW,
    DENY
};

enum class PrincipalType {
    ANY,
    GROUP,
    USER
};

struct Spec {
    int L;
    int P;
    int A;
    auto operator<=>(const Spec&) const = default;
};

struct ParsedRule {
    Effect effect;
    PrincipalType principal_type;
    std::string_view principal_name;
    bool any_action;
    std::vector<std::string_view> actions;
    std::vector<ResourceSeg> resource;
    Spec spec;
};

struct ParsedRequest {
    std::string_view user;
    std::vector<std::string_view> groups;
    std::string_view action;
    std::vector<std::string_view> path;
};

bool match_resource(const std::vector<ResourceSeg>& pattern, const std::vector<std::string_view>& path) {
    const std::size_t rlen = pattern.size();
    const std::size_t plen = path.size();
    std::size_t ri = 0;
    std::size_t pi = 0;
    std::size_t star_ri = std::string_view::npos;
    std::size_t star_pi = 0;

    while (pi < plen) {
        if (ri < rlen && (pattern[ri].type == SegType::LITERAL
                              ? pattern[ri].lit == path[pi]
                              : pattern[ri].type == SegType::STAR)) {
            ++ri;
            ++pi;
        } else if (ri < rlen && pattern[ri].type == SegType::DOUBLE_STAR) {
            star_ri = ri;
            star_pi = pi;
            ++ri;
        } else if (star_ri != std::string_view::npos) {
            ri = star_ri + 1;
            ++star_pi;
            pi = star_pi;
        } else {
            return false;
        }
    }

    while (ri < rlen && pattern[ri].type == SegType::DOUBLE_STAR) {
        ++ri;
    }
    return ri == rlen;
}

bool match_rule(const ParsedRule& rule, const ParsedRequest& req) {
    if (rule.principal_type == PrincipalType::USER) {
        if (rule.principal_name != req.user) {
            return false;
        }
    } else if (rule.principal_type == PrincipalType::GROUP) {
        if (!std::binary_search(req.groups.begin(), req.groups.end(), rule.principal_name)) {
            return false;
        }
    }

    if (!rule.any_action) {
        if (!std::binary_search(rule.actions.begin(), rule.actions.end(), req.action)) {
            return false;
        }
    }

    return match_resource(rule.resource, req.path);
}

}  // namespace

std::vector<std::string> evaluate_access(
    const std::vector<std::string>& rules,
    const std::vector<std::tuple<std::string, std::vector<std::string>, std::string, std::string>>& requests) {
    std::vector<ParsedRule> parsed_rules;
    parsed_rules.reserve(rules.size());

    for (std::size_t i = 0; i < rules.size(); ++i) {
        std::vector<std::string_view> fields = split_ws(rules[i]);
        if (fields.size() != 4) {
            throw std::invalid_argument("rule " + std::to_string(i) + ": expected 4 fields, got " +
                                        std::to_string(fields.size()));
        }

        ParsedRule pr;
        std::string_view eff_sv = fields[0];
        if (eff_sv == "ALLOW") {
            pr.effect = Effect::ALLOW;
        } else if (eff_sv == "DENY") {
            pr.effect = Effect::DENY;
        } else {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad effect '" + std::string(eff_sv) + "'");
        }

        std::string_view prin_sv = fields[1];
        int p_spec = 0;
        if (prin_sv == "*") {
            pr.principal_type = PrincipalType::ANY;
            p_spec = 0;
        } else if (prin_sv.starts_with("user:")) {
            std::string_view name = prin_sv.substr(5);
            if (!is_name(name)) {
                throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal '" +
                                            std::string(prin_sv) + "'");
            }
            pr.principal_type = PrincipalType::USER;
            pr.principal_name = name;
            p_spec = 2;
        } else if (prin_sv.starts_with("group:")) {
            std::string_view name = prin_sv.substr(6);
            if (!is_name(name)) {
                throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal '" +
                                            std::string(prin_sv) + "'");
            }
            pr.principal_type = PrincipalType::GROUP;
            pr.principal_name = name;
            p_spec = 1;
        } else {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal '" +
                                        std::string(prin_sv) + "'");
        }

        std::string_view act_sv = fields[2];
        int a_spec = 0;
        if (act_sv == "*") {
            pr.any_action = true;
            a_spec = 0;
        } else {
            pr.any_action = false;
            a_spec = 1;
            std::size_t pos = 0;
            while (true) {
                std::size_t next = act_sv.find(',', pos);
                std::string_view word = (next == std::string_view::npos)
                                            ? act_sv.substr(pos)
                                            : act_sv.substr(pos, next - pos);
                if (!is_action_word(word)) {
                    throw std::invalid_argument("rule " + std::to_string(i) + ": bad action '" +
                                                std::string(act_sv) + "'");
                }
                pr.actions.push_back(word);
                if (next == std::string_view::npos) {
                    break;
                }
                pos = next + 1;
            }
            std::sort(pr.actions.begin(), pr.actions.end());
            pr.actions.erase(std::unique(pr.actions.begin(), pr.actions.end()), pr.actions.end());
        }

        std::string_view res_sv = fields[3];
        int l_spec = 0;
        if (!parse_resource(res_sv, pr.resource, l_spec)) {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad resource '" +
                                        std::string(res_sv) + "'");
        }

        pr.spec = Spec{l_spec, p_spec, a_spec};
        parsed_rules.push_back(std::move(pr));
    }

    std::vector<ParsedRequest> parsed_requests;
    parsed_requests.reserve(requests.size());

    for (std::size_t j = 0; j < requests.size(); ++j) {
        const auto& [user, groups, action, path] = requests[j];
        if (!is_name(user)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad user '" + user + "'");
        }

        ParsedRequest preq;
        preq.user = user;
        preq.groups.reserve(groups.size());
        for (const auto& g : groups) {
            if (!is_name(g)) {
                throw std::invalid_argument("request " + std::to_string(j) + ": bad groups");
            }
            preq.groups.push_back(g);
        }
        std::sort(preq.groups.begin(), preq.groups.end());
        preq.groups.erase(std::unique(preq.groups.begin(), preq.groups.end()), preq.groups.end());

        if (!is_action_word(action)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad action '" + action + "'");
        }
        preq.action = action;

        if (!parse_path(path, preq.path)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad path '" + path + "'");
        }

        parsed_requests.push_back(std::move(preq));
    }

    std::vector<std::string> decisions;
    decisions.reserve(parsed_requests.size());

    for (const auto& req : parsed_requests) {
        Spec best_spec{-1, -1, -1};
        bool best_deny = false;
        std::size_t best_idx = 0;
        bool matched = false;

        for (std::size_t i = 0; i < parsed_rules.size(); ++i) {
            const auto& rule = parsed_rules[i];
            if (matched) {
                if (rule.spec < best_spec) {
                    continue;
                }
                if (rule.spec == best_spec) {
                    if (best_deny || rule.effect == Effect::ALLOW) {
                        continue;
                    }
                }
            }

            if (match_rule(rule, req)) {
                best_spec = rule.spec;
                best_deny = (rule.effect == Effect::DENY);
                best_idx = i;
                matched = true;
            }
        }

        if (!matched) {
            decisions.emplace_back("DENY by default");
        } else if (best_deny) {
            decisions.emplace_back("DENY by rule " + std::to_string(best_idx));
        } else {
            decisions.emplace_back("ALLOW by rule " + std::to_string(best_idx));
        }
    }

    return decisions;
}

const NAME_RE = /^[a-z0-9_]+$/;
const ACTION_WORD_RE = /^[a-z]+$/;
const ACTION_LIST_RE = /^[a-z]+(,[a-z]+)*$/;
const RESOURCE_SEG_RE = /^(\*|\*\*|[a-z0-9._-]+)$/;
const PATH_SEG_RE = /^[a-z0-9._-]+$/;

type ParsedRule = {
  index: number;
  effect: "ALLOW" | "DENY";
  principalType: 0 | 1 | 2; // 0: "*", 1: "group", 2: "user"
  principalName: string;
  actions: Set<string> | null; // null means "*"
  resourceSegs: string[];
  specL: number;
  specP: 0 | 1 | 2;
  specA: 0 | 1;
};

type ParsedRequest = {
  user: string;
  groups: Set<string>;
  action: string;
  pathSegs: string[];
};

function matchResource(pat: string[], path: string[]): boolean {
  let pi = 0;
  let si = 0;
  let starPi = -1;
  let starSi = -1;
  const pLen = pat.length;
  const sLen = path.length;

  while (si < sLen) {
    if (pi < pLen && (pat[pi] === "*" || pat[pi] === path[si])) {
      pi++;
      si++;
    } else if (pi < pLen && pat[pi] === "**") {
      starPi = pi;
      starSi = si;
      pi++;
    } else if (starPi !== -1) {
      pi = starPi + 1;
      starSi++;
      si = starSi;
    } else {
      return false;
    }
  }

  while (pi < pLen && pat[pi] === "**") {
    pi++;
  }
  return pi === pLen;
}

export function evaluateAccess(
  rules: string[],
  requests: [string, string[], string, string][],
): string[] {
  if (!Array.isArray(rules)) {
    throw new Error("rules must be a list");
  }
  if (!Array.isArray(requests)) {
    throw new Error("requests must be a list");
  }

  const parsedRules: ParsedRule[] = new Array(rules.length);

  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (typeof rule !== "string") {
      throw new Error(`rule ${i}: not a str`);
    }

    const trimmed = rule.trim();
    const fields = trimmed === "" ? [] : trimmed.split(/\s+/);
    if (fields.length !== 4) {
      throw new Error(`rule ${i}: expected 4 fields, got ${fields.length}`);
    }

    const [effect, principal, action, resource] = fields;

    if (effect !== "ALLOW" && effect !== "DENY") {
      throw new Error(`rule ${i}: bad effect ${JSON.stringify(effect)}`);
    }

    let principalType: 0 | 1 | 2;
    let principalName = "";
    if (principal === "*") {
      principalType = 0;
    } else if (principal.startsWith("user:") && NAME_RE.test(principal.slice(5))) {
      principalType = 2;
      principalName = principal.slice(5);
    } else if (principal.startsWith("group:") && NAME_RE.test(principal.slice(6))) {
      principalType = 1;
      principalName = principal.slice(6);
    } else {
      throw new Error(`rule ${i}: bad principal ${JSON.stringify(principal)}`);
    }

    let actions: Set<string> | null;
    let specA: 0 | 1;
    if (action === "*") {
      actions = null;
      specA = 0;
    } else if (ACTION_LIST_RE.test(action)) {
      actions = new Set(action.split(","));
      specA = 1;
    } else {
      throw new Error(`rule ${i}: bad action ${JSON.stringify(action)}`);
    }

    let resourceSegs: string[];
    let specL = 0;
    if (resource === "/") {
      resourceSegs = [];
    } else if (resource.startsWith("/")) {
      resourceSegs = resource.slice(1).split("/");
      for (let k = 0; k < resourceSegs.length; k++) {
        const seg = resourceSegs[k];
        if (!RESOURCE_SEG_RE.test(seg)) {
          throw new Error(`rule ${i}: bad resource ${JSON.stringify(resource)}`);
        }
        if (seg !== "*" && seg !== "**") {
          specL++;
        }
      }
    } else {
      throw new Error(`rule ${i}: bad resource ${JSON.stringify(resource)}`);
    }

    parsedRules[i] = {
      index: i,
      effect,
      principalType,
      principalName,
      actions,
      resourceSegs,
      specL,
      specP: principalType,
      specA,
    };
  }

  const parsedRequests: ParsedRequest[] = new Array(requests.length);

  for (let j = 0; j < requests.length; j++) {
    const req = requests[j];
    if (!Array.isArray(req) || req.length !== 4) {
      throw new Error(`request ${j}: expected 4-tuple`);
    }

    const [user, groups, action, path] = req;

    if (typeof user !== "string" || !NAME_RE.test(user)) {
      throw new Error(`request ${j}: bad user ${JSON.stringify(user)}`);
    }

    if (!Array.isArray(groups)) {
      throw new Error(`request ${j}: bad groups`);
    }
    const groupSet = new Set<string>();
    for (let k = 0; k < groups.length; k++) {
      const g = groups[k];
      if (typeof g !== "string" || !NAME_RE.test(g)) {
        throw new Error(`request ${j}: bad groups`);
      }
      groupSet.add(g);
    }

    if (typeof action !== "string" || !ACTION_WORD_RE.test(action)) {
      throw new Error(`request ${j}: bad action ${JSON.stringify(action)}`);
    }

    let pathSegs: string[];
    if (typeof path !== "string") {
      throw new Error(`request ${j}: bad path ${JSON.stringify(path)}`);
    }
    if (path === "/") {
      pathSegs = [];
    } else if (path.startsWith("/")) {
      pathSegs = path.slice(1).split("/");
      for (let k = 0; k < pathSegs.length; k++) {
        if (!PATH_SEG_RE.test(pathSegs[k])) {
          throw new Error(`request ${j}: bad path ${JSON.stringify(path)}`);
        }
      }
    } else {
      throw new Error(`request ${j}: bad path ${JSON.stringify(path)}`);
    }

    parsedRequests[j] = {
      user,
      groups: groupSet,
      action,
      pathSegs,
    };
  }

  // Sort rules by specificity descending, then DENY before ALLOW, then index ascending.
  // The first matching rule in this order is the decision.
  parsedRules.sort((a, b) => {
    if (a.specL !== b.specL) return b.specL - a.specL;
    if (a.specP !== b.specP) return b.specP - a.specP;
    if (a.specA !== b.specA) return b.specA - a.specA;
    if (a.effect !== b.effect) return a.effect === "DENY" ? -1 : 1;
    return a.index - b.index;
  });

  const decisions: string[] = new Array(parsedRequests.length);

  for (let j = 0; j < parsedRequests.length; j++) {
    const req = parsedRequests[j];
    let decision = "DENY by default";

    for (let i = 0; i < parsedRules.length; i++) {
      const rule = parsedRules[i];

      if (rule.principalType === 2) {
        if (rule.principalName !== req.user) continue;
      } else if (rule.principalType === 1) {
        if (!req.groups.has(rule.principalName)) continue;
      }

      if (rule.actions !== null && !rule.actions.has(req.action)) {
        continue;
      }

      if (matchResource(rule.resourceSegs, req.pathSegs)) {
        decision = `${rule.effect} by rule ${rule.index}`;
        break;
      }
    }

    decisions[j] = decision;
  }

  return decisions;
}

import copy
import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _type_name(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, int):
        return "int"
    if isinstance(value, float):
        return "float"
    if isinstance(value, str):
        return "str"
    if isinstance(value, list):
        return "list"
    if isinstance(value, dict):
        return "dict"
    return type(value).__name__


def _format_path(parent_path: str, name: str) -> str:
    if _IDENT_RE.fullmatch(name):
        return f"{parent_path}.{name}"
    return f"{parent_path}[{json.dumps(name, ensure_ascii=False)}]"


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result: dict = {}
    warnings: list[str] = []

    def merge_into(overlay: dict, target: dict, path: str, layer_idx: int) -> None:
        for key, value in overlay.items():
            if not isinstance(key, str):
                raise TypeError(f"layer {layer_idx}: non-string key at {path}")

            if key.startswith("-"):
                directive = "delete"
                name = key[1:]
            elif key.endswith("+"):
                directive = "append"
                name = key[:-1]
            else:
                directive = "set"
                name = key

            if name == "":
                raise ValueError(f"layer {layer_idx}: empty key name at {path}")

            child_path = _format_path(path, name)

            if directive == "delete":
                if value is not None:
                    raise ValueError(
                        f"layer {layer_idx}: delete directive needs null at {child_path}"
                    )
                if name in target:
                    del target[name]
                else:
                    warnings.append(
                        f"layer {layer_idx}: delete of missing key at {child_path}"
                    )

            elif directive == "append":
                if not isinstance(value, list):
                    raise ValueError(
                        f"layer {layer_idx}: append directive needs a list at {child_path}"
                    )
                if name not in target:
                    target[name] = copy.deepcopy(value)
                elif isinstance(target[name], list):
                    target[name].extend(copy.deepcopy(value))
                else:
                    raise ValueError(
                        f"layer {layer_idx}: cannot append to {_type_name(target[name])} at {child_path}"
                    )

            else:  # directive == "set"
                if name in target:
                    old_type = _type_name(target[name])
                    new_type = _type_name(value)
                    if old_type != new_type:
                        warnings.append(
                            f"layer {layer_idx}: type change at {child_path}: {old_type} -> {new_type}"
                        )

                if isinstance(value, dict):
                    if name not in target or not isinstance(target[name], dict):
                        target[name] = {}
                    merge_into(value, target[name], child_path, layer_idx)
                else:
                    target[name] = copy.deepcopy(value)

    for layer_idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {layer_idx} is not a dict")
        merge_into(layer, result, "$", layer_idx)

    return result, warnings

package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
	F3 string
}

var (
	openingRe = regexp.MustCompile(`\A-?(0|[1-9][0-9]{0,8})\.[0-9]{2}\z`)
	amountRe  = regexp.MustCompile(`\A(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?\z`)
)

func parseCents(s string) int64 {
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	intPart, fracPart, hasDot := strings.Cut(s, ".")
	dollars, _ := strconv.ParseInt(intPart, 10, 64)
	var cents int64
	if hasDot {
		if len(fracPart) == 1 {
			cents = int64(fracPart[0]-'0') * 10
		} else {
			cents = int64(fracPart[0]-'0')*10 + int64(fracPart[1]-'0')
		}
	}
	total := dollars*100 + cents
	if neg {
		total = -total
	}
	return total
}

func isValidDate(s string) bool {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return false
	}
	for i := 0; i < 10; i++ {
		if i == 4 || i == 7 {
			continue
		}
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	y, _ := strconv.Atoi(s[0:4])
	m, _ := strconv.Atoi(s[5:7])
	d, _ := strconv.Atoi(s[8:10])
	if y < 1900 || y > 2999 || m < 1 || m > 12 || d < 1 {
		return false
	}
	t := time.Date(y, time.Month(m), d, 0, 0, 0, 0, time.UTC)
	return t.Year() == y && int(t.Month()) == m && t.Day() == d
}

func formatMoney(cents int64) string {
	neg := cents < 0
	var abs uint64
	if neg {
		abs = uint64(-cents)
	} else {
		abs = uint64(cents)
	}
	dollars := abs / 100
	rem := abs % 100

	raw := strconv.FormatUint(dollars, 10)
	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	n := len(raw)
	for i := 0; i < n; i++ {
		if i > 0 && (n-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(raw[i])
	}
	fmt.Fprintf(&b, ".%02d", rem)
	return b.String()
}

func formatMemo(memo string) string {
	norm := strings.Join(strings.Fields(memo), " ")
	runes := []rune(norm)
	if len(runes) > 20 {
		norm = string(runes[:19]) + "~"
	}
	return fmt.Sprintf("%-20s", norm)
}

func formatEntryLine(date, memo string, sign string, amountCents, balanceCents int64) string {
	m := formatMemo(memo)
	amt := fmt.Sprintf("%14s", sign+formatMoney(amountCents))
	bal := fmt.Sprintf("%15s", formatMoney(balanceCents))
	flag := ""
	if balanceCents < 0 {
		flag = " OD"
	}
	return fmt.Sprintf("%s  %s  %s  %s%s", date, m, amt, bal, flag)
}

func RenderStatement(opening string, entries []Tuple1) ([]string, error) {
	if !openingRe.MatchString(opening) {
		return nil, fmt.Errorf("opening: bad amount %q", opening)
	}
	openingCents := parseCents(opening)

	parsedAmounts := make([]int64, len(entries))
	prevDate := ""
	for i, e := range entries {
		if !isValidDate(e.F0) {
			return nil, fmt.Errorf("entry %d: bad date %q", i, e.F0)
		}
		if i > 0 && e.F0 < prevDate {
			return nil, fmt.Errorf("entry %d: date out of order", i)
		}
		prevDate = e.F0

		if e.F1 != "credit" && e.F1 != "debit" && e.F1 != "fee" {
			return nil, fmt.Errorf("entry %d: bad kind %q", i, e.F1)
		}

		if !amountRe.MatchString(e.F2) {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, e.F2)
		}
		amt := parseCents(e.F2)
		if amt == 0 {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, e.F2)
		}
		parsedAmounts[i] = amt

		for _, r := range e.F3 {
			if r < 32 || r == 127 {
				return nil, fmt.Errorf("entry %d: bad memo", i)
			}
		}
		if len(strings.Fields(e.F3)) == 0 {
			return nil, fmt.Errorf("entry %d: bad memo", i)
		}
	}

	lines := make([]string, 0, len(entries)+3)
	lines = append(lines, "Opening balance: "+formatMoney(openingCents))

	balance := openingCents
	odFeeDates := make(map[string]bool)
	var credits, debits, fees int

	for i, e := range entries {
		amt := parsedAmounts[i]
		switch e.F1 {
		case "credit":
			balance += amt
			credits++
			lines = append(lines, formatEntryLine(e.F0, e.F3, "+", amt, balance))
		case "debit":
			balance -= amt
			debits++
			lines = append(lines, formatEntryLine(e.F0, e.F3, "-", amt, balance))
			if balance < 0 && !odFeeDates[e.F0] {
				odFeeDates[e.F0] = true
				const odFeeCents = 2500
				balance -= odFeeCents
				fees++
				lines = append(lines, formatEntryLine(e.F0, "OVERDRAFT FEE", "-", odFeeCents, balance))
			}
		case "fee":
			balance -= amt
			fees++
			lines = append(lines, formatEntryLine(e.F0, e.F3, "-", amt, balance))
		}
	}

	lines = append(lines, "Closing balance: "+formatMoney(balance))
	lines = append(lines, fmt.Sprintf("Credits: %d  Debits: %d  Fees: %d", credits, debits, fees))
	return lines, nil
}

import java.time.DateTimeException;
import java.time.LocalDate;
import java.util.*;
import java.util.regex.Pattern;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2, String f3) {}

    private static final Pattern OPENING_PATTERN =
            Pattern.compile("-?(0|[1-9][0-9]{0,8})\\.[0-9]{2}");
    private static final Pattern DATE_PATTERN =
            Pattern.compile("[0-9]{4}-[0-9]{2}-[0-9]{2}");
    private static final Pattern AMOUNT_PATTERN =
            Pattern.compile("(0|[1-9][0-9]{0,8})(\\.[0-9]{1,2})?");
    private static final long OVERDRAFT_FEE_CENTS = 2500L;

    private record ParsedEntry(String date, String kind, long amountCents, String normalizedMemo) {}

    public static List<String> renderStatement(String opening, List<Tuple1> entries) {
        if (opening == null) {
            throw new IllegalArgumentException("opening must be a str");
        }
        if (!OPENING_PATTERN.matcher(opening).matches()) {
            throw new IllegalArgumentException("opening: bad amount " + opening);
        }
        if (entries == null) {
            throw new IllegalArgumentException("entries must be a list");
        }

        long openingCents = parseOpeningCents(opening);
        List<ParsedEntry> parsed = new ArrayList<>(entries.size());
        String prevDate = null;

        for (int i = 0; i < entries.size(); i++) {
            Tuple1 entry = entries.get(i);
            if (entry == null) {
                throw new IllegalArgumentException("entry " + i + ": expected 4-tuple");
            }

            String date = entry.f0();
            if (!isValidDate(date)) {
                throw new IllegalArgumentException("entry " + i + ": bad date " + date);
            }
            if (prevDate != null && date.compareTo(prevDate) < 0) {
                throw new IllegalArgumentException("entry " + i + ": date out of order");
            }
            prevDate = date;

            String kind = entry.f1();
            if (!"credit".equals(kind) && !"debit".equals(kind) && !"fee".equals(kind)) {
                throw new IllegalArgumentException("entry " + i + ": bad kind " + kind);
            }

            String amount = entry.f2();
            if (amount == null || !AMOUNT_PATTERN.matcher(amount).matches()) {
                throw new IllegalArgumentException("entry " + i + ": bad amount " + amount);
            }
            long amountCents = parseAmountCents(amount);
            if (amountCents == 0L) {
                throw new IllegalArgumentException("entry " + i + ": bad amount " + amount);
            }

            String memo = entry.f3();
            String normalizedMemo = validateAndNormalizeMemo(memo, i);

            parsed.add(new ParsedEntry(date, kind, amountCents, normalizedMemo));
        }

        List<String> lines = new ArrayList<>();
        long balance = openingCents;
        lines.add("Opening balance: " + formatMoney(balance));

        long credits = 0;
        long debits = 0;
        long fees = 0;
        String lastAutoFeeDate = null;

        for (ParsedEntry entry : parsed) {
            switch (entry.kind()) {
                case "credit" -> {
                    balance += entry.amountCents();
                    credits++;
                    lines.add(formatLine(entry.date(), entry.normalizedMemo(), "+", entry.amountCents(), balance));
                }
                case "debit" -> {
                    balance -= entry.amountCents();
                    debits++;
                    lines.add(formatLine(entry.date(), entry.normalizedMemo(), "-", entry.amountCents(), balance));
                    if (balance < 0 && !entry.date().equals(lastAutoFeeDate)) {
                        lastAutoFeeDate = entry.date();
                        balance -= OVERDRAFT_FEE_CENTS;
                        fees++;
                        lines.add(formatLine(entry.date(), "OVERDRAFT FEE", "-", OVERDRAFT_FEE_CENTS, balance));
                    }
                }
                case "fee" -> {
                    balance -= entry.amountCents();
                    fees++;
                    lines.add(formatLine(entry.date(), entry.normalizedMemo(), "-", entry.amountCents(), balance));
                }
                default -> throw new IllegalStateException("Unexpected kind: " + entry.kind());
            }
        }

        lines.add("Closing balance: " + formatMoney(balance));
        lines.add("Credits: " + credits + "  Debits: " + debits + "  Fees: " + fees);
        return lines;
    }

    private static boolean isValidDate(String date) {
        if (date == null || !DATE_PATTERN.matcher(date).matches()) {
            return false;
        }
        int year = Integer.parseInt(date.substring(0, 4));
        if (year < 1900 || year > 2999) {
            return false;
        }
        int month = Integer.parseInt(date.substring(5, 7));
        int day = Integer.parseInt(date.substring(8, 10));
        try {
            LocalDate.of(year, month, day);
            return true;
        } catch (DateTimeException e) {
            return false;
        }
    }

    private static long parseOpeningCents(String s) {
        boolean negative = s.startsWith("-");
        String unsigned = negative ? s.substring(1) : s;
        int dot = unsigned.indexOf('.');
        long dollars = Long.parseLong(unsigned.substring(0, dot));
        long cents = Long.parseLong(unsigned.substring(dot + 1));
        long total = dollars * 100L + cents;
        return negative ? -total : total;
    }

    private static long parseAmountCents(String s) {
        int dot = s.indexOf('.');
        if (dot < 0) {
            return Long.parseLong(s) * 100L;
        }
        long dollars = Long.parseLong(s.substring(0, dot));
        String frac = s.substring(dot + 1);
        long cents = frac.length() == 1 ? Long.parseLong(frac) * 10L : Long.parseLong(frac);
        return dollars * 100L + cents;
    }

    private static boolean isPythonWhitespace(int cp) {
        return Character.isWhitespace(cp) || Character.isSpaceChar(cp) || cp == 0x85;
    }

    private static String validateAndNormalizeMemo(String memo, int index) {
        if (memo == null) {
            throw new IllegalArgumentException("entry " + index + ": bad memo");
        }
        StringBuilder sb = new StringBuilder();
        boolean inToken = false;
        boolean hasToken = false;
        int i = 0;
        while (i < memo.length()) {
            int cp = memo.codePointAt(i);
            i += Character.charCount(cp);
            if (cp < 32 || cp == 127) {
                throw new IllegalArgumentException("entry " + index + ": bad memo");
            }
            if (isPythonWhitespace(cp)) {
                inToken = false;
            } else {
                if (!inToken && hasToken) {
                    sb.append(' ');
                }
                sb.appendCodePoint(cp);
                inToken = true;
                hasToken = true;
            }
        }
        if (!hasToken) {
            throw new IllegalArgumentException("entry " + index + ": bad memo");
        }
        return sb.toString();
    }

    private static String formatMemoColumn(String normalizedMemo) {
        int cpCount = normalizedMemo.codePointCount(0, normalizedMemo.length());
        String display;
        int displayLen;
        if (cpCount > 20) {
            int endIdx = normalizedMemo.offsetByCodePoints(0, 19);
            display = normalizedMemo.substring(0, endIdx) + "~";
            displayLen = 20;
        } else {
            display = normalizedMemo;
            displayLen = cpCount;
        }
        if (displayLen < 20) {
            return display + " ".repeat(20 - displayLen);
        }
        return display;
    }

    private static String formatLine(String date, String normalizedMemo, String sign, long amountCents, long balanceCents) {
        String memoCol = formatMemoColumn(normalizedMemo);
        String amtCol = padLeft(sign + formatMoney(amountCents), 14);
        String balCol = padLeft(formatMoney(balanceCents), 15);
        String flag = balanceCents < 0 ? " OD" : "";
        return date + "  " + memoCol + "  " + amtCol + "  " + balCol + flag;
    }

    private static String padLeft(String s, int width) {
        if (s.length() >= width) {
            return s;
        }
        return " ".repeat(width - s.length()) + s;
    }

    private static String formatMoney(long cents) {
        boolean negative = cents < 0;
        long abs = negative ? -cents : cents;
        long dollars = abs / 100L;
        long rem = abs % 100L;

        String dStr = Long.toString(dollars);
        StringBuilder sb = new StringBuilder(dStr.length() + dStr.length() / 3 + 4);
        if (negative) {
            sb.append('-');
        }
        int len = dStr.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                sb.append(',');
            }
            sb.append(dStr.charAt(i));
        }
        sb.append('.');
        sb.append((char) ('0' + rem / 10));
        sb.append((char) ('0' + rem % 10));
        return sb.toString();
    }
}

#include <stdexcept>
#include <string>
#include <tuple>
#include <vector>

namespace {

bool is_ascii_digit(char c) {
    return c >= '0' && c <= '9';
}

bool is_ascii_whitespace(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

long long parse_opening_cents(const std::string& s) {
    if (s.empty()) {
        throw std::invalid_argument("opening: bad amount");
    }
    std::size_t pos = 0;
    bool neg = false;
    if (s[pos] == '-') {
        neg = true;
        ++pos;
    }
    std::size_t dot = s.find('.', pos);
    if (dot == std::string::npos) {
        throw std::invalid_argument("opening: bad amount");
    }
    std::size_t int_len = dot - pos;
    if (int_len == 0 || int_len > 9) {
        throw std::invalid_argument("opening: bad amount");
    }
    if (int_len == 1) {
        if (!is_ascii_digit(s[pos])) {
            throw std::invalid_argument("opening: bad amount");
        }
    } else {
        if (s[pos] < '1' || s[pos] > '9') {
            throw std::invalid_argument("opening: bad amount");
        }
        for (std::size_t k = 1; k < int_len; ++k) {
            if (!is_ascii_digit(s[pos + k])) {
                throw std::invalid_argument("opening: bad amount");
            }
        }
    }
    if (s.size() - dot != 3) {
        throw std::invalid_argument("opening: bad amount");
    }
    if (!is_ascii_digit(s[dot + 1]) || !is_ascii_digit(s[dot + 2])) {
        throw std::invalid_argument("opening: bad amount");
    }

    long long dollars = 0;
    for (std::size_t k = 0; k < int_len; ++k) {
        dollars = dollars * 10 + (s[pos + k] - '0');
    }
    long long cents = (s[dot + 1] - '0') * 10 + (s[dot + 2] - '0');
    long long total = dollars * 100 + cents;
    return neg ? -total : total;
}

bool is_valid_date(const std::string& d) {
    if (d.size() != 10) {
        return false;
    }
    for (std::size_t k = 0; k < 10; ++k) {
        if (k == 4 || k == 7) {
            if (d[k] != '-') {
                return false;
            }
        } else {
            if (!is_ascii_digit(d[k])) {
                return false;
            }
        }
    }
    int year = (d[0] - '0') * 1000 + (d[1] - '0') * 100 + (d[2] - '0') * 10 + (d[3] - '0');
    int month = (d[5] - '0') * 10 + (d[6] - '0');
    int day = (d[8] - '0') * 10 + (d[9] - '0');

    if (year < 1900 || year > 2999 || month < 1 || month > 12 || day < 1) {
        return false;
    }
    static const int days_in_month[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int max_day = days_in_month[month - 1];
    if (month == 2 && (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0))) {
        max_day = 29;
    }
    return day <= max_day;
}

long long parse_entry_amount_cents(const std::string& s) {
    if (s.empty()) {
        throw std::invalid_argument("bad amount");
    }
    std::size_t dot = s.find('.');
    std::size_t int_end = (dot == std::string::npos) ? s.size() : dot;

    if (int_end == 0 || int_end > 9) {
        throw std::invalid_argument("bad amount");
    }
    if (int_end == 1) {
        if (!is_ascii_digit(s[0])) {
            throw std::invalid_argument("bad amount");
        }
    } else {
        if (s[0] < '1' || s[0] > '9') {
            throw std::invalid_argument("bad amount");
        }
        for (std::size_t k = 1; k < int_end; ++k) {
            if (!is_ascii_digit(s[k])) {
                throw std::invalid_argument("bad amount");
            }
        }
    }

    long long dollars = 0;
    for (std::size_t k = 0; k < int_end; ++k) {
        dollars = dollars * 10 + (s[k] - '0');
    }

    long long cents = 0;
    if (dot != std::string::npos) {
        std::size_t frac_len = s.size() - dot - 1;
        if (frac_len < 1 || frac_len > 2) {
            throw std::invalid_argument("bad amount");
        }
        for (std::size_t k = 0; k < frac_len; ++k) {
            if (!is_ascii_digit(s[dot + 1 + k])) {
                throw std::invalid_argument("bad amount");
            }
        }
        if (frac_len == 1) {
            cents = (s[dot + 1] - '0') * 10;
        } else {
            cents = (s[dot + 1] - '0') * 10 + (s[dot + 2] - '0');
        }
    }

    long long total = dollars * 100 + cents;
    if (total == 0) {
        throw std::invalid_argument("bad amount");
    }
    return total;
}

std::string normalize_and_validate_memo(const std::string& memo) {
    for (unsigned char uc : memo) {
        if (uc < 32 || uc == 127) {
            throw std::invalid_argument("bad memo");
        }
    }
    std::string normalized;
    std::size_t i = 0;
    const std::size_t n = memo.size();
    while (i < n) {
        while (i < n && is_ascii_whitespace(memo[i])) {
            ++i;
        }
        if (i >= n) {
            break;
        }
        if (!normalized.empty()) {
            normalized.push_back(' ');
        }
        while (i < n && !is_ascii_whitespace(memo[i])) {
            normalized.push_back(memo[i]);
            ++i;
        }
    }
    if (normalized.empty()) {
        throw std::invalid_argument("bad memo");
    }
    return normalized;
}

std::string format_money(long long x) {
    bool neg = x < 0;
    unsigned long long abs_x = neg ? static_cast<unsigned long long>(-(x + 1)) + 1ULL
                                   : static_cast<unsigned long long>(x);
    unsigned long long dollars = abs_x / 100ULL;
    unsigned long long cents = abs_x % 100ULL;

    std::string d_str = std::to_string(dollars);
    std::string with_commas;
    with_commas.reserve(d_str.size() + d_str.size() / 3);
    for (std::size_t i = 0; i < d_str.size(); ++i) {
        if (i > 0 && (d_str.size() - i) % 3 == 0) {
            with_commas.push_back(',');
        }
        with_commas.push_back(d_str[i]);
    }

    std::string res;
    if (neg) {
        res.push_back('-');
    }
    res += with_commas;
    res.push_back('.');
    res.push_back(static_cast<char>('0' + (cents / 10ULL)));
    res.push_back(static_cast<char>('0' + (cents % 10ULL)));
    return res;
}

std::string pad_right(const std::string& s, std::size_t width) {
    if (s.size() >= width) {
        return s;
    }
    return s + std::string(width - s.size(), ' ');
}

std::string pad_left(const std::string& s, std::size_t width) {
    if (s.size() >= width) {
        return s;
    }
    return std::string(width - s.size(), ' ') + s;
}

std::string format_entry_line(const std::string& date,
                              const std::string& norm_memo,
                              const std::string& kind,
                              long long amount_cents,
                              long long balance_after) {
    std::string memo_col = norm_memo;
    if (memo_col.size() > 20) {
        memo_col = memo_col.substr(0, 19) + "~";
    }
    memo_col = pad_right(memo_col, 20);

    std::string amt_col = (kind == "credit" ? "+" : "-") + format_money(amount_cents);
    amt_col = pad_left(amt_col, 14);

    std::string bal_col = pad_left(format_money(balance_after), 15);
    std::string flag = (balance_after < 0) ? " OD" : "";

    return date + "  " + memo_col + "  " + amt_col + "  " + bal_col + flag;
}

struct ParsedEntry {
    std::string date;
    std::string kind;
    long long amount_cents;
    std::string norm_memo;
};

}  // namespace

std::vector<std::string> render_statement(
    const std::string& opening,
    const std::vector<std::tuple<std::string, std::string, std::string, std::string>>& entries) {

    long long opening_cents = parse_opening_cents(opening);

    std::vector<ParsedEntry> parsed;
    parsed.reserve(entries.size());

    for (std::size_t i = 0; i < entries.size(); ++i) {
        const auto& [date, kind, amount, memo] = entries[i];

        if (!is_valid_date(date)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad date");
        }
        if (i > 0 && date < parsed[i - 1].date) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": date out of order");
        }
        if (kind != "credit" && kind != "debit" && kind != "fee") {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad kind");
        }
        long long amount_cents = parse_entry_amount_cents(amount);
        std::string norm_memo = normalize_and_validate_memo(memo);

        parsed.push_back(ParsedEntry{date, kind, amount_cents, norm_memo});
    }

    std::vector<std::string> out;
    out.push_back("Opening balance: " + format_money(opening_cents));

    long long balance = opening_cents;
    std::string last_auto_od_date;
    long long credit_count = 0;
    long long debit_count = 0;
    long long fee_count = 0;

    for (const auto& entry : parsed) {
        if (entry.kind == "credit") {
            balance += entry.amount_cents;
            ++credit_count;
            out.push_back(format_entry_line(entry.date, entry.norm_memo, entry.kind, entry.amount_cents, balance));
        } else if (entry.kind == "debit") {
            balance -= entry.amount_cents;
            ++debit_count;
            out.push_back(format_entry_line(entry.date, entry.norm_memo, entry.kind, entry.amount_cents, balance));

            if (balance < 0 && entry.date != last_auto_od_date) {
                last_auto_od_date = entry.date;
                constexpr long long od_fee = 2500;
                balance -= od_fee;
                ++fee_count;
                out.push_back(format_entry_line(entry.date, "OVERDRAFT FEE", "fee", od_fee, balance));
            }
        } else {
            balance -= entry.amount_cents;
            ++fee_count;
            out.push_back(format_entry_line(entry.date, entry.norm_memo, entry.kind, entry.amount_cents, balance));
        }
    }

    out.push_back("Closing balance: " + format_money(balance));
    out.push_back("Credits: " + std::to_string(credit_count) +
                  "  Debits: " + std::to_string(debit_count) +
                  "  Fees: " + std::to_string(fee_count));

    return out;
}

type EntryKind = "credit" | "debit" | "fee";

interface ParsedEntry {
  date: string;
  kind: EntryKind;
  amountCents: number;
  memo: string;
}

const OPENING_RE = /^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$/;
const DATE_RE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
const AMOUNT_RE = /^(0|[1-9][0-9]{0,8})(?:\.([0-9]{1,2}))?$/;

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  switch (month) {
    case 2:
      return isLeapYear(year) ? 29 : 28;
    case 4:
    case 6:
    case 9:
    case 11:
      return 30;
    default:
      return 31;
  }
}

function isValidDate(value: unknown): value is string {
  if (typeof value !== "string") {
    return false;
  }
  const match = DATE_RE.exec(value);
  if (match === null) {
    return false;
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (year < 1900 || year > 2999) {
    return false;
  }
  if (month < 1 || month > 12) {
    return false;
  }
  if (day < 1 || day > daysInMonth(year, month)) {
    return false;
  }
  return true;
}

function parseOpeningCents(opening: string): number {
  const negative = opening.startsWith("-");
  const unsigned = negative ? opening.slice(1) : opening;
  const dotIdx = unsigned.indexOf(".");
  const intPart = Number(unsigned.slice(0, dotIdx));
  const fracPart = Number(unsigned.slice(dotIdx + 1));
  const total = intPart * 100 + fracPart;
  if (total === 0) {
    return 0;
  }
  return negative ? -total : total;
}

function parseAmountCents(value: unknown): number | null {
  if (typeof value !== "string") {
    return null;
  }
  const match = AMOUNT_RE.exec(value);
  if (match === null) {
    return null;
  }
  const intPart = Number(match[1]);
  const fracStr = (match[2] ?? "").padEnd(2, "0");
  const fracPart = Number(fracStr);
  const total = intPart * 100 + fracPart;
  return total === 0 ? null : total;
}

function isValidMemo(value: unknown): value is string {
  if (typeof value !== "string") {
    return false;
  }
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code < 32 || code === 127) {
      return false;
    }
  }
  const trimmed = value.replace(/^[\s\u0085]+|[\s\u0085]+$/g, "");
  return trimmed.length > 0;
}

function formatMoney(cents: number): string {
  const negative = cents < 0;
  const abs = Math.abs(cents);
  const intPart = Math.floor(abs / 100);
  const fracPart = String(abs % 100).padStart(2, "0");
  const intStr = String(intPart).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return `${negative ? "-" : ""}${intStr}.${fracPart}`;
}

function formatMemo(memo: string): string {
  const normalized = memo
    .replace(/^[\s\u0085]+|[\s\u0085]+$/g, "")
    .split(/[\s\u0085]+/)
    .join(" ");
  const chars = [...normalized];
  if (chars.length > 20) {
    return chars.slice(0, 19).join("") + "~";
  }
  return normalized + " ".repeat(20 - chars.length);
}

function formatLine(
  date: string,
  memo: string,
  kind: EntryKind,
  amountCents: number,
  balanceCents: number
): string {
  const memoCol = formatMemo(memo);
  const sign = kind === "credit" ? "+" : "-";
  const amtCol = `${sign}${formatMoney(amountCents)}`.padStart(14, " ");
  const balCol = formatMoney(balanceCents).padStart(15, " ");
  const flag = balanceCents < 0 ? " OD" : "";
  return `${date}  ${memoCol}  ${amtCol}  ${balCol}${flag}`;
}

export function renderStatement(
  opening: string,
  entries: [string, string, string, string][]
): string[] {
  if (typeof opening !== "string") {
    throw new Error("opening must be a str");
  }
  if (!OPENING_RE.test(opening)) {
    throw new Error(`opening: bad amount ${JSON.stringify(opening)}`);
  }
  if (!Array.isArray(entries)) {
    throw new Error("entries must be a list");
  }

  const parsedEntries: ParsedEntry[] = [];
  let prevDate: string | null = null;

  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];
    if (!Array.isArray(entry) || entry.length !== 4) {
      throw new Error(`entry ${i}: expected 4-tuple`);
    }

    const [date, kind, amount, memo] = entry;

    if (!isValidDate(date)) {
      throw new Error(`entry ${i}: bad date ${JSON.stringify(date)}`);
    }
    if (prevDate !== null && date < prevDate) {
      throw new Error(`entry ${i}: date out of order`);
    }
    if (kind !== "credit" && kind !== "debit" && kind !== "fee") {
      throw new Error(`entry ${i}: bad kind ${JSON.stringify(kind)}`);
    }
    const amountCents = parseAmountCents(amount);
    if (amountCents === null) {
      throw new Error(`entry ${i}: bad amount ${JSON.stringify(amount)}`);
    }
    if (!isValidMemo(memo)) {
      throw new Error(`entry ${i}: bad memo`);
    }

    parsedEntries.push({ date, kind, amountCents, memo });
    prevDate = date;
  }

  let balanceCents = parseOpeningCents(opening);
  const lines: string[] = [`Opening balance: ${formatMoney(balanceCents)}`];
  const overdraftFeeDates = new Set<string>();

  let creditCount = 0;
  let debitCount = 0;
  let feeCount = 0;

  for (const entry of parsedEntries) {
    if (entry.kind === "credit") {
      balanceCents += entry.amountCents;
      creditCount++;
    } else if (entry.kind === "debit") {
      balanceCents -= entry.amountCents;
      debitCount++;
    } else {
      balanceCents -= entry.amountCents;
      feeCount++;
    }

    lines.push(
      formatLine(entry.date, entry.memo, entry.kind, entry.amountCents, balanceCents)
    );

    if (
      entry.kind === "debit" &&
      balanceCents < 0 &&
      !overdraftFeeDates.has(entry.date)
    ) {
      overdraftFeeDates.add(entry.date);
      const feeCents = 2500;
      balanceCents -= feeCents;
      feeCount++;
      lines.push(
        formatLine(entry.date, "OVERDRAFT FEE", "fee", feeCents, balanceCents)
      );
    }
  }

  lines.push(`Closing balance: ${formatMoney(balanceCents)}`);
  lines.push(`Credits: ${creditCount}  Debits: ${debitCount}  Fees: ${feeCount}`);

  return lines;
}

import re

_PART = r"(?:0|[1-9][0-9]*)"
_VERSION_RE = re.compile(rf"({_PART})\.({_PART})\.({_PART})(?:~rc([1-9][0-9]*))?")
_MAJOR_STAR_RE = re.compile(rf"({_PART})\.\*")
_MINOR_STAR_RE = re.compile(rf"({_PART})\.({_PART})\.\*")
_AT_RE = re.compile(rf"@({_PART})\.({_PART})")


def _parse_version(s: str):
    m = _VERSION_RE.fullmatch(s)
    if m is None:
        return None
    x, y, z, rc = m.groups()
    if rc is None:
        return (int(x), int(y), int(z), 1, 0)
    return (int(x), int(y), int(z), 0, int(rc))


def _parse_clause(clause: str):
    if clause == "*":
        return lambda v: True

    m = _MAJOR_STAR_RE.fullmatch(clause)
    if m is not None:
        x = int(m.group(1))
        return lambda v, x=x: v[0] == x

    m = _MINOR_STAR_RE.fullmatch(clause)
    if m is not None:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v, x=x, y=y: v[0] == x and v[1] == y

    m = _AT_RE.fullmatch(clause)
    if m is not None:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v, x=x, y=y: v[0] == x and v[1] >= y

    if clause.startswith(">="):
        target = _parse_version(clause[2:])
        return None if target is None else (lambda v, t=target: v >= t)
    if clause.startswith("<="):
        target = _parse_version(clause[2:])
        return None if target is None else (lambda v, t=target: v <= t)
    if clause.startswith("!="):
        target = _parse_version(clause[2:])
        return None if target is None else (lambda v, t=target: v != t)
    if clause.startswith("="):
        target = _parse_version(clause[1:])
        return None if target is None else (lambda v, t=target: v == t)
    if clause.startswith(">"):
        target = _parse_version(clause[1:])
        return None if target is None else (lambda v, t=target: v > t)
    if clause.startswith("<"):
        target = _parse_version(clause[1:])
        return None if target is None else (lambda v, t=target: v < t)

    target = _parse_version(clause)
    return None if target is None else (lambda v, t=target: v == t)


def pick_version(available, constraint) -> str | None:
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    parsed_available = []
    for i, element in enumerate(available):
        if not isinstance(element, str):
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed = _parse_version(element)
        if parsed is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((parsed, element))

    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = []
    for a, raw_alt in enumerate(constraint.split("|"), 1):
        alt = raw_alt.strip(" ")
        allow_rc = alt.startswith("?")
        if allow_rc:
            alt = alt[1:].strip(" ")
        if not alt:
            raise ValueError(f"alternative {a} is empty")

        predicates = []
        for c, raw_clause in enumerate(alt.split(","), 1):
            clause = raw_clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            predicates.append(pred)
        alternatives.append((allow_rc, predicates))

    best_ver = None
    best_str = None
    for ver, ver_str in parsed_available:
        is_rc = ver[3] == 0
        for allow_rc, predicates in alternatives:
            if is_rc and not allow_rc:
                continue
            if all(pred(ver) for pred in predicates):
                if best_ver is None or ver > best_ver:
                    best_ver = ver
                    best_str = ver_str
                break

    return best_str

package main

import (
	"errors"
	"fmt"
	"strings"
)

type version struct {
	raw  string
	x    string
	y    string
	z    string
	isRC bool
	rc   string
}

func isValidNum(s string) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func cmpNum(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func cmpVersion(a, b version) int {
	if c := cmpNum(a.x, b.x); c != 0 {
		return c
	}
	if c := cmpNum(a.y, b.y); c != 0 {
		return c
	}
	if c := cmpNum(a.z, b.z); c != 0 {
		return c
	}
	if a.isRC != b.isRC {
		if a.isRC {
			return -1
		}
		return 1
	}
	if !a.isRC {
		return 0
	}
	return cmpNum(a.rc, b.rc)
}

func parseVersion(s string) (version, bool) {
	var v version
	v.raw = s
	xyz := s
	if idx := strings.IndexByte(s, '~'); idx != -1 {
		suffix := s[idx:]
		if !strings.HasPrefix(suffix, "~rc") {
			return version{}, false
		}
		rc := suffix[3:]
		if !isValidNum(rc) || rc == "0" {
			return version{}, false
		}
		v.isRC = true
		v.rc = rc
		xyz = s[:idx]
	}
	parts := strings.Split(xyz, ".")
	if len(parts) != 3 {
		return version{}, false
	}
	if !isValidNum(parts[0]) || !isValidNum(parts[1]) || !isValidNum(parts[2]) {
		return version{}, false
	}
	v.x = parts[0]
	v.y = parts[1]
	v.z = parts[2]
	return v, true
}

type clauseKind int

const (
	clauseAny clauseKind = iota
	clauseEq
	clauseNeq
	clauseGt
	clauseGte
	clauseLt
	clauseLte
	clauseMajorWild
	clauseMinorWild
	clauseAtMinor
)

type clause struct {
	kind clauseKind
	ver  version
	x    string
	y    string
}

func parseClause(s string) (clause, bool) {
	if s == "" {
		return clause{}, false
	}
	if s == "*" {
		return clause{kind: clauseAny}, true
	}
	if strings.HasPrefix(s, "!=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return clause{}, false
		}
		return clause{kind: clauseNeq, ver: v}, true
	}
	if strings.HasPrefix(s, ">=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return clause{}, false
		}
		return clause{kind: clauseGte, ver: v}, true
	}
	if strings.HasPrefix(s, "<=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return clause{}, false
		}
		return clause{kind: clauseLte, ver: v}, true
	}
	if strings.HasPrefix(s, ">") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return clause{}, false
		}
		return clause{kind: clauseGt, ver: v}, true
	}
	if strings.HasPrefix(s, "<") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return clause{}, false
		}
		return clause{kind: clauseLt, ver: v}, true
	}
	if strings.HasPrefix(s, "=") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return clause{}, false
		}
		return clause{kind: clauseEq, ver: v}, true
	}
	if strings.HasPrefix(s, "@") {
		parts := strings.Split(s[1:], ".")
		if len(parts) != 2 || !isValidNum(parts[0]) || !isValidNum(parts[1]) {
			return clause{}, false
		}
		return clause{kind: clauseAtMinor, x: parts[0], y: parts[1]}, true
	}
	if strings.HasSuffix(s, ".*") {
		prefix := s[:len(s)-2]
		parts := strings.Split(prefix, ".")
		if len(parts) == 1 && isValidNum(parts[0]) {
			return clause{kind: clauseMajorWild, x: parts[0]}, true
		}
		if len(parts) == 2 && isValidNum(parts[0]) && isValidNum(parts[1]) {
			return clause{kind: clauseMinorWild, x: parts[0], y: parts[1]}, true
		}
		return clause{}, false
	}
	v, ok := parseVersion(s)
	if !ok {
		return clause{}, false
	}
	return clause{kind: clauseEq, ver: v}, true
}

func (c clause) matches(v version) bool {
	switch c.kind {
	case clauseAny:
		return true
	case clauseEq:
		return cmpVersion(v, c.ver) == 0
	case clauseNeq:
		return cmpVersion(v, c.ver) != 0
	case clauseGt:
		return cmpVersion(v, c.ver) > 0
	case clauseGte:
		return cmpVersion(v, c.ver) >= 0
	case clauseLt:
		return cmpVersion(v, c.ver) < 0
	case clauseLte:
		return cmpVersion(v, c.ver) <= 0
	case clauseMajorWild:
		return v.x == c.x
	case clauseMinorWild:
		return v.x == c.x && v.y == c.y
	case clauseAtMinor:
		return v.x == c.x && cmpNum(v.y, c.y) >= 0
	default:
		return false
	}
}

type alternative struct {
	allowRC bool
	clauses []clause
}

func PickVersion(available []string, constraint string) (*string, error) {
	versions := make([]version, len(available))
	for i, s := range available {
		v, ok := parseVersion(s)
		if !ok {
			return nil, fmt.Errorf("invalid version at index %d: %q", i, s)
		}
		versions[i] = v
	}

	if strings.Trim(constraint, " ") == "" {
		return nil, errors.New("empty constraint")
	}

	rawAlts := strings.Split(constraint, "|")
	alts := make([]alternative, 0, len(rawAlts))
	for aIdx, rawAlt := range rawAlts {
		altStr := strings.Trim(rawAlt, " ")
		allowRC := false
		if strings.HasPrefix(altStr, "?") {
			allowRC = true
			altStr = strings.Trim(altStr[1:], " ")
		}
		if altStr == "" {
			return nil, fmt.Errorf("alternative %d is empty", aIdx+1)
		}
		rawClauses := strings.Split(altStr, ",")
		clauses := make([]clause, 0, len(rawClauses))
		for cIdx, rawCl := range rawClauses {
			clStr := strings.Trim(rawCl, " ")
			cl, ok := parseClause(clStr)
			if !ok {
				return nil, fmt.Errorf("alternative %d, clause %d: invalid clause %q", aIdx+1, cIdx+1, clStr)
			}
			clauses = append(clauses, cl)
		}
		alts = append(alts, alternative{allowRC: allowRC, clauses: clauses})
	}

	var best *version
	for _, v := range versions {
		matched := false
		for _, alt := range alts {
			if v.isRC && !alt.allowRC {
				continue
			}
			allMatch := true
			for _, cl := range alt.clauses {
				if !cl.matches(v) {
					allMatch = false
					break
				}
			}
			if allMatch {
				matched = true
				break
			}
		}
		if matched {
			if best == nil || cmpVersion(v, *best) > 0 {
				vCopy := v
				best = &vCopy
			}
		}
	}

	if best == nil {
		return nil, nil
	}
	res := best.raw
	return &res, nil
}

import java.util.*;

public final class Solution {

    private enum ClauseKind {
        ANY,
        EQ,
        NE,
        GT,
        GE,
        LT,
        LE,
        MAJOR_WILDCARD,
        MINOR_WILDCARD,
        AT_LEAST_MINOR
    }

    private record Version(String raw, String major, String minor, String patch, String rc)
            implements Comparable<Version> {
        @Override
        public int compareTo(Version other) {
            int cmp = compareNum(this.major, other.major);
            if (cmp != 0) return cmp;
            cmp = compareNum(this.minor, other.minor);
            if (cmp != 0) return cmp;
            cmp = compareNum(this.patch, other.patch);
            if (cmp != 0) return cmp;
            if (this.rc == null && other.rc == null) return 0;
            if (this.rc == null) return 1;
            if (other.rc == null) return -1;
            return compareNum(this.rc, other.rc);
        }
    }

    private record Clause(ClauseKind kind, Version target, String major, String minor) {
        boolean matches(Version v) {
            return switch (kind) {
                case ANY -> true;
                case EQ -> v.compareTo(target) == 0;
                case NE -> v.compareTo(target) != 0;
                case GT -> v.compareTo(target) > 0;
                case GE -> v.compareTo(target) >= 0;
                case LT -> v.compareTo(target) < 0;
                case LE -> v.compareTo(target) <= 0;
                case MAJOR_WILDCARD -> v.major().equals(major);
                case MINOR_WILDCARD -> v.major().equals(major) && v.minor().equals(minor);
                case AT_LEAST_MINOR -> v.major().equals(major) && compareNum(v.minor(), minor) >= 0;
            };
        }
    }

    private record Alternative(boolean allowRc, List<Clause> clauses) {
        boolean matches(Version v) {
            if (v.rc() != null && !allowRc) {
                return false;
            }
            for (Clause c : clauses) {
                if (!c.matches(v)) {
                    return false;
                }
            }
            return true;
        }
    }

    public static String pickVersion(List<String> available, String constraint) {
        if (available == null) {
            throw new IllegalArgumentException("available must be a list");
        }
        List<Version> versions = new ArrayList<>(available.size());
        for (int i = 0; i < available.size(); i++) {
            String raw = available.get(i);
            if (raw == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": null");
            }
            Version v = parseVersion(raw);
            if (v == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": " + raw);
            }
            versions.add(v);
        }

        if (constraint == null) {
            throw new IllegalArgumentException("constraint must be a str");
        }
        if (stripSpaces(constraint).isEmpty()) {
            throw new IllegalArgumentException("empty constraint");
        }

        String[] rawAlts = constraint.split("\\|", -1);
        List<Alternative> alternatives = new ArrayList<>(rawAlts.length);
        for (int a = 0; a < rawAlts.length; a++) {
            String altText = stripSpaces(rawAlts[a]);
            boolean allowRc = false;
            if (altText.startsWith("?")) {
                allowRc = true;
                altText = stripSpaces(altText.substring(1));
            }
            if (altText.isEmpty()) {
                throw new IllegalArgumentException("alternative " + (a + 1) + " is empty");
            }

            String[] rawClauses = altText.split(",", -1);
            List<Clause> clauses = new ArrayList<>(rawClauses.length);
            for (int c = 0; c < rawClauses.length; c++) {
                String clauseText = stripSpaces(rawClauses[c]);
                Clause parsed = parseClause(clauseText);
                if (parsed == null) {
                    throw new IllegalArgumentException(
                            "alternative " + (a + 1) + ", clause " + (c + 1) + ": invalid clause '" + clauseText + "'"
                    );
                }
                clauses.add(parsed);
            }
            alternatives.add(new Alternative(allowRc, clauses));
        }

        Version best = null;
        for (Version v : versions) {
            boolean ok = false;
            for (Alternative alt : alternatives) {
                if (alt.matches(v)) {
                    ok = true;
                    break;
                }
            }
            if (ok && (best == null || v.compareTo(best) > 0)) {
                best = v;
            }
        }
        return best == null ? null : best.raw();
    }

    private static int compareNum(String a, String b) {
        int lenCmp = Integer.compare(a.length(), b.length());
        if (lenCmp != 0) {
            return lenCmp;
        }
        return a.compareTo(b);
    }

    private static String stripSpaces(String s) {
        int start = 0;
        int end = s.length();
        while (start < end && s.charAt(start) == ' ') {
            start++;
        }
        while (end > start && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(start, end);
    }

    private static boolean isValidPart(String s) {
        int len = s.length();
        if (len == 0) {
            return false;
        }
        if (len > 1 && s.charAt(0) == '0') {
            return false;
        }
        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);
            if (ch < '0' || ch > '9') {
                return false;
            }
        }
        return true;
    }

    private static Version parseVersion(String s) {
        int tilde = s.indexOf('~');
        String base;
        String rc = null;
        if (tilde != -1) {
            if (!s.startsWith("~rc", tilde)) {
                return null;
            }
            rc = s.substring(tilde + 3);
            if (!isValidPart(rc) || rc.equals("0")) {
                return null;
            }
            base = s.substring(0, tilde);
        } else {
            base = s;
        }

        int d1 = base.indexOf('.');
        if (d1 <= 0) {
            return null;
        }
        int d2 = base.indexOf('.', d1 + 1);
        if (d2 <= d1 + 1) {
            return null;
        }
        if (base.indexOf('.', d2 + 1) != -1) {
            return null;
        }

        String major = base.substring(0, d1);
        String minor = base.substring(d1 + 1, d2);
        String patch = base.substring(d2 + 1);
        if (!isValidPart(major) || !isValidPart(minor) || !isValidPart(patch)) {
            return null;
        }
        return new Version(s, major, minor, patch, rc);
    }

    private static Clause parseClause(String clause) {
        if (clause.equals("*")) {
            return new Clause(ClauseKind.ANY, null, null, null);
        }
        if (clause.startsWith("@")) {
            String rest = clause.substring(1);
            int dot = rest.indexOf('.');
            if (dot <= 0 || rest.indexOf('.', dot + 1) != -1) {
                return null;
            }
            String major = rest.substring(0, dot);
            String minor = rest.substring(dot + 1);
            if (!isValidPart(major) || !isValidPart(minor)) {
                return null;
            }
            return new Clause(ClauseKind.AT_LEAST_MINOR, null, major, minor);
        }
        if (clause.startsWith("!=")) {
            Version v = parseVersion(clause.substring(2));
            return v == null ? null : new Clause(ClauseKind.NE, v, null, null);
        }
        if (clause.startsWith(">=")) {
            Version v = parseVersion(clause.substring(2));
            return v == null ? null : new Clause(ClauseKind.GE, v, null, null);
        }
        if (clause.startsWith("<=")) {
            Version v = parseVersion(clause.substring(2));
            return v == null ? null : new Clause(ClauseKind.LE, v, null, null);
        }
        if (clause.startsWith(">")) {
            Version v = parseVersion(clause.substring(1));
            return v == null ? null : new Clause(ClauseKind.GT, v, null, null);
        }
        if (clause.startsWith("<")) {
            Version v = parseVersion(clause.substring(1));
            return v == null ? null : new Clause(ClauseKind.LT, v, null, null);
        }
        if (clause.startsWith("=")) {
            Version v = parseVersion(clause.substring(1));
            return v == null ? null : new Clause(ClauseKind.EQ, v, null, null);
        }
        if (clause.endsWith(".*")) {
            String prefix = clause.substring(0, clause.length() - 2);
            int dot = prefix.indexOf('.');
            if (dot == -1) {
                if (!isValidPart(prefix)) {
                    return null;
                }
                return new Clause(ClauseKind.MAJOR_WILDCARD, null, prefix, null);
            }
            if (prefix.indexOf('.', dot + 1) != -1) {
                return null;
            }
            String major = prefix.substring(0, dot);
            String minor = prefix.substring(dot + 1);
            if (!isValidPart(major) || !isValidPart(minor)) {
                return null;
            }
            return new Clause(ClauseKind.MINOR_WILDCARD, null, major, minor);
        }
        Version v = parseVersion(clause);
        return v == null ? null : new Clause(ClauseKind.EQ, v, null, null);
    }
}

#include <compare>
#include <cstddef>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

namespace {

struct NumPart {
    std::string digits;

    std::strong_ordering operator<=>(const NumPart& other) const {
        if (digits.size() != other.digits.size()) {
            return digits.size() <=> other.digits.size();
        }
        return digits <=> other.digits;
    }

    bool operator==(const NumPart& other) const = default;
};

struct Version {
    NumPart major;
    NumPart minor;
    NumPart patch;
    bool has_rc = false;
    NumPart rc;

    std::strong_ordering operator<=>(const Version& other) const {
        if (auto cmp = major <=> other.major; cmp != 0) return cmp;
        if (auto cmp = minor <=> other.minor; cmp != 0) return cmp;
        if (auto cmp = patch <=> other.patch; cmp != 0) return cmp;
        if (has_rc != other.has_rc) {
            return has_rc ? std::strong_ordering::less : std::strong_ordering::greater;
        }
        if (has_rc) {
            return rc <=> other.rc;
        }
        return std::strong_ordering::equal;
    }

    bool operator==(const Version& other) const = default;
};

bool is_valid_part(std::string_view sv) {
    if (sv.empty()) return false;
    for (char ch : sv) {
        if (ch < '0' || ch > '9') return false;
    }
    if (sv.size() > 1 && sv[0] == '0') return false;
    return true;
}

std::optional<Version> parse_version(std::string_view sv) {
    Version v;
    std::string_view base = sv;

    if (std::size_t tilde = sv.find('~'); tilde != std::string_view::npos) {
        std::string_view suffix = sv.substr(tilde);
        if (!suffix.starts_with("~rc")) return std::nullopt;
        std::string_view rc_str = suffix.substr(3);
        if (!is_valid_part(rc_str) || rc_str == "0") return std::nullopt;
        v.has_rc = true;
        v.rc = NumPart{std::string(rc_str)};
        base = sv.substr(0, tilde);
    }

    std::size_t d1 = base.find('.');
    if (d1 == std::string_view::npos) return std::nullopt;
    std::size_t d2 = base.find('.', d1 + 1);
    if (d2 == std::string_view::npos) return std::nullopt;
    if (base.find('.', d2 + 1) != std::string_view::npos) return std::nullopt;

    std::string_view x = base.substr(0, d1);
    std::string_view y = base.substr(d1 + 1, d2 - d1 - 1);
    std::string_view z = base.substr(d2 + 1);
    if (!is_valid_part(x) || !is_valid_part(y) || !is_valid_part(z)) {
        return std::nullopt;
    }

    v.major = NumPart{std::string(x)};
    v.minor = NumPart{std::string(y)};
    v.patch = NumPart{std::string(z)};
    return v;
}

std::string_view trim_spaces(std::string_view sv) {
    while (!sv.empty() && sv.front() == ' ') sv.remove_prefix(1);
    while (!sv.empty() && sv.back() == ' ') sv.remove_suffix(1);
    return sv;
}

std::vector<std::string_view> split_char(std::string_view sv, char delim) {
    std::vector<std::string_view> parts;
    std::size_t start = 0;
    while (true) {
        std::size_t pos = sv.find(delim, start);
        if (pos == std::string_view::npos) {
            parts.push_back(sv.substr(start));
            break;
        }
        parts.push_back(sv.substr(start, pos - start));
        start = pos + 1;
    }
    return parts;
}

struct Clause {
    enum class Kind {
        Any,
        Eq,
        Ne,
        Gt,
        Ge,
        Lt,
        Le,
        MajorWild,
        MinorWild,
        AtMinor
    };

    Kind kind = Kind::Any;
    Version ver;
    NumPart major;
    NumPart minor;

    bool matches(const Version& v) const {
        switch (kind) {
            case Kind::Any: return true;
            case Kind::Eq: return v == ver;
            case Kind::Ne: return v != ver;
            case Kind::Gt: return v > ver;
            case Kind::Ge: return v >= ver;
            case Kind::Lt: return v < ver;
            case Kind::Le: return v <= ver;
            case Kind::MajorWild: return v.major == major;
            case Kind::MinorWild: return v.major == major && v.minor == minor;
            case Kind::AtMinor: return v.major == major && v.minor >= minor;
        }
        return false;
    }
};

std::optional<Clause> parse_clause(std::string_view sv) {
    if (sv.empty()) return std::nullopt;

    if (sv == "*") {
        return Clause{Clause::Kind::Any, {}, {}, {}};
    }

    auto make_cmp = [](Clause::Kind k, std::string_view rest) -> std::optional<Clause> {
        auto v = parse_version(rest);
        if (!v) return std::nullopt;
        return Clause{k, *v, {}, {}};
    };

    if (sv.starts_with("!=")) return make_cmp(Clause::Kind::Ne, sv.substr(2));
    if (sv.starts_with(">=")) return make_cmp(Clause::Kind::Ge, sv.substr(2));
    if (sv.starts_with("<=")) return make_cmp(Clause::Kind::Le, sv.substr(2));
    if (sv.starts_with('=')) return make_cmp(Clause::Kind::Eq, sv.substr(1));
    if (sv.starts_with('>')) return make_cmp(Clause::Kind::Gt, sv.substr(1));
    if (sv.starts_with('<')) return make_cmp(Clause::Kind::Lt, sv.substr(1));

    if (sv.starts_with('@')) {
        std::string_view rest = sv.substr(1);
        std::size_t dot = rest.find('.');
        if (dot == std::string_view::npos) return std::nullopt;
        if (rest.find('.', dot + 1) != std::string_view::npos) return std::nullopt;
        std::string_view x = rest.substr(0, dot);
        std::string_view y = rest.substr(dot + 1);
        if (!is_valid_part(x) || !is_valid_part(y)) return std::nullopt;
        return Clause{Clause::Kind::AtMinor, {}, NumPart{std::string(x)}, NumPart{std::string(y)}};
    }

    if (sv.ends_with(".*")) {
        std::string_view prefix = sv.substr(0, sv.size() - 2);
        std::size_t dot = prefix.find('.');
        if (dot == std::string_view::npos) {
            if (!is_valid_part(prefix)) return std::nullopt;
            return Clause{Clause::Kind::MajorWild, {}, NumPart{std::string(prefix)}, {}};
        }
        if (prefix.find('.', dot + 1) != std::string_view::npos) return std::nullopt;
        std::string_view x = prefix.substr(0, dot);
        std::string_view y = prefix.substr(dot + 1);
        if (!is_valid_part(x) || !is_valid_part(y)) return std::nullopt;
        return Clause{Clause::Kind::MinorWild, {}, NumPart{std::string(x)}, NumPart{std::string(y)}};
    }

    return make_cmp(Clause::Kind::Eq, sv);
}

struct Alternative {
    bool allows_rc = false;
    std::vector<Clause> clauses;

    bool matches(const Version& v) const {
        if (v.has_rc && !allows_rc) return false;
        for (const auto& clause : clauses) {
            if (!clause.matches(v)) return false;
        }
        return true;
    }
};

}  // namespace

std::optional<std::string> pick_version(const std::vector<std::string>& available,
                                        const std::string& constraint) {
    std::vector<Version> parsed_available;
    parsed_available.reserve(available.size());
    for (std::size_t i = 0; i < available.size(); ++i) {
        auto v = parse_version(available[i]);
        if (!v) {
            throw std::invalid_argument("invalid version at index " + std::to_string(i) + ": '" +
                                        available[i] + "'");
        }
        parsed_available.push_back(std::move(*v));
    }

    if (trim_spaces(constraint).empty()) {
        throw std::invalid_argument("empty constraint");
    }

    std::vector<Alternative> alternatives;
    std::vector<std::string_view> raw_alts = split_char(constraint, '|');
    alternatives.reserve(raw_alts.size());

    for (std::size_t a_idx = 0; a_idx < raw_alts.size(); ++a_idx) {
        std::size_t a_num = a_idx + 1;
        std::string_view alt_sv = trim_spaces(raw_alts[a_idx]);
        Alternative alt;

        if (!alt_sv.empty() && alt_sv.front() == '?') {
            alt.allows_rc = true;
            alt_sv.remove_prefix(1);
            alt_sv = trim_spaces(alt_sv);
        }

        if (alt_sv.empty()) {
            throw std::invalid_argument("alternative " + std::to_string(a_num) + " is empty");
        }

        std::vector<std::string_view> raw_clauses = split_char(alt_sv, ',');
        alt.clauses.reserve(raw_clauses.size());
        for (std::size_t c_idx = 0; c_idx < raw_clauses.size(); ++c_idx) {
            std::size_t c_num = c_idx + 1;
            std::string_view clause_sv = trim_spaces(raw_clauses[c_idx]);
            auto parsed_clause = parse_clause(clause_sv);
            if (!parsed_clause) {
                throw std::invalid_argument("alternative " + std::to_string(a_num) + ", clause " +
                                            std::to_string(c_num) + ": invalid clause '" +
                                            std::string(clause_sv) + "'");
            }
            alt.clauses.push_back(std::move(*parsed_clause));
        }

        alternatives.push_back(std::move(alt));
    }

    std::optional<std::size_t> best_idx;
    for (std::size_t i = 0; i < parsed_available.size(); ++i) {
        const Version& v = parsed_available[i];
        bool ok = false;
        for (const auto& alt : alternatives) {
            if (alt.matches(v)) {
                ok = true;
                break;
            }
        }
        if (ok && (!best_idx || v > parsed_available[*best_idx])) {
            best_idx = i;
        }
    }

    if (!best_idx) {
        return std::nullopt;
    }
    return available[*best_idx];
}

type ParsedVersion = {
  raw: string;
  major: number;
  minor: number;
  patch: number;
  rc: number;
};

type Clause = (v: ParsedVersion) => boolean;

type Alternative = {
  allowsRc: boolean;
  clauses: Clause[];
};

const VERSION_RE =
  /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:~rc([1-9][0-9]*))?$/;
const MAJOR_WILDCARD_RE = /^(0|[1-9][0-9]*)\.\*$/;
const MINOR_WILDCARD_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.\*$/;
const AT_RE = /^@(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function trimSpaces(s: string): string {
  let start = 0;
  let end = s.length;
  while (start < end && s.charCodeAt(start) === 32) {
    start++;
  }
  while (end > start && s.charCodeAt(end - 1) === 32) {
    end--;
  }
  return s.slice(start, end);
}

function parseVersion(s: string): ParsedVersion | null {
  const m = VERSION_RE.exec(s);
  if (!m) return null;
  return {
    raw: s,
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    rc: m[4] !== undefined ? Number(m[4]) : Infinity,
  };
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  if (a.patch !== b.patch) return a.patch - b.patch;
  if (a.rc === b.rc) return 0;
  return a.rc < b.rc ? -1 : 1;
}

function parseClause(clause: string): Clause | null {
  if (clause === "*") {
    return () => true;
  }

  let m = MAJOR_WILDCARD_RE.exec(clause);
  if (m) {
    const major = Number(m[1]);
    return (v) => v.major === major;
  }

  m = MINOR_WILDCARD_RE.exec(clause);
  if (m) {
    const major = Number(m[1]);
    const minor = Number(m[2]);
    return (v) => v.major === major && v.minor === minor;
  }

  m = AT_RE.exec(clause);
  if (m) {
    const major = Number(m[1]);
    const minor = Number(m[2]);
    return (v) => v.major === major && v.minor >= minor;
  }

  if (clause.startsWith("!=")) {
    const target = parseVersion(clause.slice(2));
    if (!target) return null;
    return (v) => compareVersions(v, target) !== 0;
  }
  if (clause.startsWith(">=")) {
    const target = parseVersion(clause.slice(2));
    if (!target) return null;
    return (v) => compareVersions(v, target) >= 0;
  }
  if (clause.startsWith("<=")) {
    const target = parseVersion(clause.slice(2));
    if (!target) return null;
    return (v) => compareVersions(v, target) <= 0;
  }
  if (clause.startsWith(">")) {
    const target = parseVersion(clause.slice(1));
    if (!target) return null;
    return (v) => compareVersions(v, target) > 0;
  }
  if (clause.startsWith("<")) {
    const target = parseVersion(clause.slice(1));
    if (!target) return null;
    return (v) => compareVersions(v, target) < 0;
  }
  if (clause.startsWith("=")) {
    const target = parseVersion(clause.slice(1));
    if (!target) return null;
    return (v) => compareVersions(v, target) === 0;
  }

  const target = parseVersion(clause);
  if (target) {
    return (v) => compareVersions(v, target) === 0;
  }

  return null;
}

export function pickVersion(
  available: string[],
  constraint: string
): string | null {
  if (!Array.isArray(available)) {
    throw new Error("available must be a list");
  }

  const parsedVersions: ParsedVersion[] = [];
  for (let i = 0; i < available.length; i++) {
    const element: unknown = available[i];
    if (typeof element !== "string") {
      throw new Error(`invalid version at index ${i}: ${String(element)}`);
    }
    const parsed = parseVersion(element);
    if (!parsed) {
      throw new Error(`invalid version at index ${i}: '${element}'`);
    }
    parsedVersions.push(parsed);
  }

  if (typeof constraint !== "string") {
    throw new Error("constraint must be a str");
  }

  if (trimSpaces(constraint) === "") {
    throw new Error("empty constraint");
  }

  const rawAlts = constraint.split("|");
  const alternatives: Alternative[] = [];

  for (let a = 1; a <= rawAlts.length; a++) {
    let altStr = trimSpaces(rawAlts[a - 1]);
    let allowsRc = false;
    if (altStr.startsWith("?")) {
      allowsRc = true;
      altStr = trimSpaces(altStr.slice(1));
    }
    if (altStr === "") {
      throw new Error(`alternative ${a} is empty`);
    }

    const rawClauses = altStr.split(",");
    const clauses: Clause[] = [];
    for (let c = 1; c <= rawClauses.length; c++) {
      const clauseStr = trimSpaces(rawClauses[c - 1]);
      const clauseFn = parseClause(clauseStr);
      if (!clauseFn) {
        throw new Error(
          `alternative ${a}, clause ${c}: invalid clause '${clauseStr}'`
        );
      }
      clauses.push(clauseFn);
    }

    alternatives.push({ allowsRc, clauses });
  }

  let best: ParsedVersion | null = null;
  for (const v of parsedVersions) {
    const isRc = v.rc !== Infinity;
    let matches = false;

    for (const alt of alternatives) {
      if (isRc && !alt.allowsRc) {
        continue;
      }
      let allMatch = true;
      for (const clause of alt.clauses) {
        if (!clause(v)) {
          allMatch = false;
          break;
        }
      }
      if (allMatch) {
        matches = true;
        break;
      }
    }

    if (matches && (best === null || compareVersions(v, best) > 0)) {
      best = v;
    }
  }

  return best !== null ? best.raw : null;
}

import re

_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_-]*\Z", re.ASCII)
_INT_RE = re.compile(r"-?(?:0|[1-9][0-9]*)\Z", re.ASCII)
_ESCAPES = {
    "\\": "\\",
    '"': '"',
    "n": "\n",
    "t": "\t",
}


def _parse_large_int(s: str) -> int:
    neg = s[0] == "-"
    if neg:
        s = s[1:]

    def _dc(lo: int, hi: int) -> int:
        if hi - lo <= 1000:
            return int(s[lo:hi])
        mid = (lo + hi) >> 1
        return _dc(lo, mid) * (10 ** (hi - mid)) + _dc(mid, hi)

    val = _dc(0, len(s))
    return -val if neg else val


def parse_outline(text: str) -> tuple:
    lines = text.split("\n")
    root = None
    stack = []  # [(indent, container), ...]
    pending_opener = None  # (container, key_or_index) or None

    key_re_match = _KEY_RE.match
    int_re_match = _INT_RE.match
    escapes = _ESCAPES

    for lineno, line in enumerate(lines, 1):
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue

        indent = len(line) - len(rest)
        if indent and line.find("\t", 0, indent) != -1:
            return ("error", lineno, "tab in indentation")

        # 1. Entry syntax
        if rest == "-" or rest.startswith("- "):
            is_key = False
            key = None
            scalar_text = rest[2:].strip(" ")
            is_opener = scalar_text == ""
        else:
            colon_idx = rest.find(":")
            if colon_idx == -1:
                return ("error", lineno, "invalid entry")
            key = rest[:colon_idx]
            if key_re_match(key) is None:
                return ("error", lineno, "invalid entry")
            after = rest[colon_idx + 1:]
            if after == "":
                is_opener = True
                scalar_text = ""
            elif after[0] != " ":
                return ("error", lineno, "invalid entry")
            else:
                scalar_text = after.strip(" ")
                is_opener = scalar_text == ""
            is_key = True

        # 2. Scalar conversion
        if not is_opener:
            c0 = scalar_text[0]
            if c0 == '"':
                n = len(scalar_text)
                if "\\" not in scalar_text:
                    if scalar_text.find('"', 1) != n - 1:
                        return ("error", lineno, "bad string")
                    value = scalar_text[1:-1]
                else:
                    out = []
                    i = 1
                    while i < n:
                        ch = scalar_text[i]
                        if ch == '"':
                            if i != n - 1:
                                return ("error", lineno, "bad string")
                            value = "".join(out)
                            break
                        if ch == "\\":
                            i += 1
                            if i >= n:
                                return ("error", lineno, "bad escape")
                            mapped = escapes.get(scalar_text[i])
                            if mapped is None:
                                return ("error", lineno, "bad escape")
                            out.append(mapped)
                        else:
                            out.append(ch)
                        i += 1
                    else:
                        return ("error", lineno, "bad string")
            elif scalar_text == "true":
                value = True
            elif scalar_text == "false":
                value = False
            elif scalar_text == "null":
                value = None
            elif ("0" <= c0 <= "9" or c0 == "-") and int_re_match(scalar_text) is not None:
                if len(scalar_text) <= 4000:
                    value = int(scalar_text)
                else:
                    value = _parse_large_int(scalar_text)
            else:
                value = scalar_text
        else:
            value = None

        # 3. Structure checks
        if not stack:
            if indent != 0:
                return ("error", lineno, "unexpected indent")
            root = {} if is_key else []
            stack.append((0, root))
        elif pending_opener is not None and indent > stack[-1][0]:
            new_block = {} if is_key else []
            parent_container, parent_slot = pending_opener
            parent_container[parent_slot] = new_block
            stack.append((indent, new_block))
            pending_opener = None
        else:
            pending_opener = None
            top_indent = stack[-1][0]
            if indent > top_indent:
                return ("error", lineno, "unexpected indent")
            if indent < top_indent:
                while stack and stack[-1][0] > indent:
                    stack.pop()
                if not stack or stack[-1][0] != indent:
                    return ("error", lineno, "inconsistent dedent")
            container = stack[-1][1]
            if is_key:
                if not isinstance(container, dict):
                    return ("error", lineno, "mixed block")
                if key in container:
                    return ("error", lineno, f"duplicate key '{key}'")
            else:
                if not isinstance(container, list):
                    return ("error", lineno, "mixed block")

        # 4. Insert entry into the active block
        container = stack[-1][1]
        if is_key:
            container[key] = value
            if is_opener:
                pending_opener = (container, key)
        else:
            container.append(value)
            if is_opener:
                pending_opener = (container, len(container) - 1)

    return ("ok", root)

import re

_TOKEN_RE = re.compile(r'\[|\]|[^ \t\n\r\[\]]+')
_INT_RE = re.compile(r'-?[0-9]+', re.ASCII)

_OP_INT = 0
_OP_QUOT = 1
_OP_WORD = 2
_OP_DUP = 3
_OP_DROP = 4
_OP_SWAP = 5
_OP_OVER = 6
_OP_ROT = 7
_OP_ADD = 8
_OP_SUB = 9
_OP_MUL = 10
_OP_DIV = 11
_OP_MOD = 12
_OP_LT = 13
_OP_EQ = 14
_OP_IF = 15
_OP_TIMES = 16
_OP_WHILE = 17
_OP_CALL = 18
_OP_DIP = 19
_OP_DEF = 20

_BUILTINS = {
    "dup": _OP_DUP,
    "drop": _OP_DROP,
    "swap": _OP_SWAP,
    "over": _OP_OVER,
    "rot": _OP_ROT,
    "+": _OP_ADD,
    "-": _OP_SUB,
    "*": _OP_MUL,
    "/": _OP_DIV,
    "%": _OP_MOD,
    "<": _OP_LT,
    "=": _OP_EQ,
    "if": _OP_IF,
    "times": _OP_TIMES,
    "while": _OP_WHILE,
    "call": _OP_CALL,
    "dip": _OP_DIP,
}

_BAD_NAMES = frozenset({"[", "]", ":", ";"} | _BUILTINS.keys())

_F_SEQ = 0
_F_DIP = 1
_F_TIMES = 2
_F_WHILE_C = 3
_F_WHILE_B = 4


class _Quot:
    __slots__ = ("code", "raw", "rendered")

    def __init__(self, code, raw):
        self.code = code
        self.raw = raw
        self.rendered = None


def _parse_int(tok: str) -> int:
    if len(tok) <= 4000:
        return int(tok)
    neg = tok[0] == "-"
    s = tok[1:] if neg else tok
    base = 10 ** 1000
    rem = len(s) % 1000
    val = int(s[:rem]) if rem else 0
    for pos in range(rem, len(s), 1000):
        val = val * base + int(s[pos:pos + 1000])
    return -val if neg else val


def _render_quot(root: _Quot) -> list:
    if root.rendered is not None:
        return root.rendered
    work = [(root, False)]
    while work:
        q, expanded = work.pop()
        if q.rendered is not None:
            continue
        if expanded:
            q.rendered = [x if type(x) is str else x.rendered for x in q.raw]
        else:
            work.append((q, True))
            for x in q.raw:
                if type(x) is not str and x.rendered is None:
                    work.append((x, False))
    return root.rendered


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOKEN_RE.findall(src)
    n_tokens = len(tokens)

    top_code = []
    open_stack = []
    int_fullmatch = _INT_RE.fullmatch
    builtins_get = _BUILTINS.get
    bad_names = _BAD_NAMES

    i = 0
    while i < n_tokens:
        tok = tokens[i]
        if tok == "[":
            open_stack.append(("[", i, [], []))
            i += 1
        elif tok == "]":
            if not open_stack or open_stack[-1][0] != "[":
                return ("error", i, "unmatched ]")
            _, start_idx, q_code, q_raw = open_stack.pop()
            q = _Quot(q_code, q_raw)
            if open_stack:
                parent = open_stack[-1]
                parent[2].append((_OP_QUOT, q, start_idx))
                if parent[0] == "[":
                    parent[3].append(q)
            else:
                top_code.append((_OP_QUOT, q, start_idx))
            i += 1
        elif tok == ":":
            if open_stack:
                return ("error", i, "misplaced :")
            if i + 1 >= n_tokens:
                return ("error", i, "unclosed :")
            name = tokens[i + 1]
            if name in bad_names or int_fullmatch(name):
                return ("error", i + 1, "bad name")
            open_stack.append((":", i, [], name))
            i += 2
        elif tok == ";":
            if not open_stack or open_stack[-1][0] != ":":
                return ("error", i, "unmatched ;")
            _, start_idx, def_code, name = open_stack.pop()
            top_code.append((_OP_DEF, (name, def_code), start_idx))
            i += 1
        else:
            if open_stack:
                parent = open_stack[-1]
                target = parent[2]
                if parent[0] == "[":
                    parent[3].append(tok)
            else:
                target = top_code

            if int_fullmatch(tok):
                target.append((_OP_INT, _parse_int(tok), i))
            else:
                b_op = builtins_get(tok)
                if b_op is not None:
                    target.append((b_op, None, i))
                else:
                    target.append((_OP_WORD, tok, i))
            i += 1

    if open_stack:
        kind, start_idx, _, _ = open_stack[0]
        return ("error", start_idx, "unclosed [" if kind == "[" else "unclosed :")

    del tokens

    stack = []
    defs = {}
    frames = []
    code = top_code
    ip = 0
    n_code = len(code)
    rem_steps = max_steps

    while True:
        while ip == n_code:
            if not frames:
                return (
                    "ok",
                    [x if type(x) is int else _render_quot(x) for x in stack],
                )
            top = frames[-1]
            kind = top[0]
            if kind == _F_SEQ:
                frames.pop()
                code = top[1]
                ip = top[2]
                n_code = len(code)
            elif kind == _F_DIP:
                frames.pop()
                stack.append(top[1])
            elif kind == _F_TIMES:
                rem = top[2]
                if rem > 1:
                    top[2] = rem - 1
                else:
                    frames.pop()
                code = top[1]
                ip = 0
                n_code = len(code)
            elif kind == _F_WHILE_C:
                if not stack:
                    return ("error", top[3], "stack underflow")
                v = stack.pop()
                if type(v) is not int:
                    return ("error", top[3], "type error")
                if v != 0:
                    b_code = top[2]
                    if b_code:
                        top[0] = _F_WHILE_B
                        code = b_code
                        ip = 0
                        n_code = len(b_code)
                    else:
                        code = top[1]
                        ip = 0
                        n_code = len(code)
                else:
                    frames.pop()
            else:  # _F_WHILE_B
                top[0] = _F_WHILE_C
                code = top[1]
                ip = 0
                n_code = len(code)

        op, arg, idx = code[ip]
        rem_steps -= 1
        if rem_steps < 0:
            return ("error", idx, "step limit exceeded")

        if op == _OP_INT:
            stack.append(arg)
        elif op == _OP_WORD:
            body = defs.get(arg)
            if body is None:
                return ("error", idx, f"unknown word '{arg}'")
            if body:
                if ip + 1 < n_code:
                    frames.append((_F_SEQ, code, ip + 1))
                code = body
                ip = 0
                n_code = len(code)
                continue
        elif op == _OP_QUOT:
            stack.append(arg)
        elif op == _OP_DUP:
            if not stack:
                return ("error", idx, "stack underflow")
            stack.append(stack[-1])
        elif op == _OP_DROP:
            if not stack:
                return ("error", idx, "stack underflow")
            stack.pop()
        elif op == _OP_SWAP:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            stack[-2], stack[-1] = stack[-1], stack[-2]
        elif op == _OP_OVER:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            stack.append(stack[-2])
        elif op == _OP_ROT:
            if len(stack) < 3:
                return ("error", idx, "stack underflow")
            a = stack[-3]
            stack[-3] = stack[-2]
            stack[-2] = stack[-1]
            stack[-1] = a
        elif op == _OP_ADD:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            stack.pop()
            stack[-1] = a + b
        elif op == _OP_SUB:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            stack.pop()
            stack[-1] = a - b
        elif op == _OP_MUL:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            stack.pop()
            stack[-1] = a * b
        elif op == _OP_DIV:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            if b == 0:
                return ("error", idx, "division by zero")
            stack.pop()
            stack[-1] = a // b
        elif op == _OP_MOD:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            if b == 0:
                return ("error", idx, "division by zero")
            stack.pop()
            stack[-1] = a % b
        elif op == _OP_LT:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            stack.pop()
            stack[-1] = 1 if a < b else 0
        elif op == _OP_EQ:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", idx, "type error")
            stack.pop()
            stack[-1] = 1 if a == b else 0
        elif op == _OP_IF:
            if len(stack) < 3:
                return ("error", idx, "stack underflow")
            f = stack[-1]
            t = stack[-2]
            c = stack[-3]
            if type(c) is not int or type(t) is not _Quot or type(f) is not _Quot:
                return ("error", idx, "type error")
            del stack[-3:]
            q_code = t.code if c != 0 else f.code
            if q_code:
                if ip + 1 < n_code:
                    frames.append((_F_SEQ, code, ip + 1))
                code = q_code
                ip = 0
                n_code = len(code)
                continue
        elif op == _OP_TIMES:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            n = stack[-1]
            q = stack[-2]
            if type(q) is not _Quot or type(n) is not int:
                return ("error", idx, "type error")
            if n < 0:
                return ("error", idx, "negative count")
            del stack[-2:]
            q_code = q.code
            if n > 0 and q_code:
                if ip + 1 < n_code:
                    frames.append((_F_SEQ, code, ip + 1))
                if n > 1:
                    frames.append([_F_TIMES, q_code, n - 1])
                code = q_code
                ip = 0
                n_code = len(code)
                continue
        elif op == _OP_WHILE:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            b = stack[-1]
            c = stack[-2]
            if type(c) is not _Quot or type(b) is not _Quot:
                return ("error", idx, "type error")
            del stack[-2:]
            if ip + 1 < n_code:
                frames.append((_F_SEQ, code, ip + 1))
            frames.append([_F_WHILE_C, c.code, b.code, idx])
            code = c.code
            ip = 0
            n_code = len(code)
            continue
        elif op == _OP_CALL:
            if not stack:
                return ("error", idx, "stack underflow")
            q = stack[-1]
            if type(q) is not _Quot:
                return ("error", idx, "type error")
            stack.pop()
            q_code = q.code
            if q_code:
                if ip + 1 < n_code:
                    frames.append((_F_SEQ, code, ip + 1))
                code = q_code
                ip = 0
                n_code = len(code)
                continue
        elif op == _OP_DIP:
            if len(stack) < 2:
                return ("error", idx, "stack underflow")
            q = stack[-1]
            if type(q) is not _Quot:
                return ("error", idx, "type error")
            stack.pop()
            a = stack.pop()
            q_code = q.code
            if q_code:
                if ip + 1 < n_code:
                    frames.append((_F_SEQ, code, ip + 1))
                frames.append((_F_DIP, a))
                code = q_code
                ip = 0
                n_code = len(code)
                continue
            else:
                stack.append(a)
        else:  # _OP_DEF
            defs[arg[0]] = arg[1]

        ip += 1

_TOK_EOF = 0
_TOK_LPAREN = 1
_TOK_RPAREN = 2
_TOK_LBRACK = 3
_TOK_RBRACK = 4
_TOK_COMMA = 5
_TOK_CMP = 6
_TOK_INT = 7
_TOK_STR = 8
_TOK_FIELD = 9
_TOK_AND = 10
_TOK_OR = 11
_TOK_NOT = 12
_TOK_IN = 13
_TOK_HAS = 14

_OP_EQ = 0
_OP_NE = 1
_OP_LT = 2
_OP_LE = 3
_OP_GT = 4
_OP_GE = 5
_OP_HAS = 6
_OP_IN = 7
_OP_NOT = 8
_OP_AND = 9
_OP_OR = 10
_OP_JIF = 11
_OP_JIT = 12

_KEYWORDS = {
    "and": _TOK_AND,
    "or": _TOK_OR,
    "not": _TOK_NOT,
    "in": _TOK_IN,
    "has": _TOK_HAS,
}

_MISSING = object()


def _parse_int(s: str) -> int:
    if len(s) <= 4000:
        return int(s)
    neg = s[0] == "-"
    if neg:
        s = s[1:]
        if len(s) <= 4000:
            return -int(s)
    chunks = [int(s[i : i + 2000]) for i in range(0, len(s), 2000)]
    lengths = [len(s[i : i + 2000]) for i in range(0, len(s), 2000)]
    while len(chunks) > 1:
        new_chunks = []
        new_lengths = []
        for idx in range(0, len(chunks), 2):
            if idx + 1 < len(chunks):
                l = lengths[idx + 1]
                new_chunks.append(chunks[idx] * (10**l) + chunks[idx + 1])
                new_lengths.append(lengths[idx] + l)
            else:
                new_chunks.append(chunks[idx])
                new_lengths.append(lengths[idx])
        chunks = new_chunks
        lengths = new_lengths
    val = chunks[0]
    return -val if neg else val


def filter_records(query: str, records: list[dict]) -> tuple:
    # STEP 1 — LEXING
    tokens = []
    n = len(query)
    i = 0
    while i < n:
        c = query[i]
        if c == " " or c == "\t" or c == "\n":
            i += 1
        elif c == "(":
            tokens.append((_TOK_LPAREN, None, i, i + 1))
            i += 1
        elif c == ")":
            tokens.append((_TOK_RPAREN, None, i, i + 1))
            i += 1
        elif c == "[":
            tokens.append((_TOK_LBRACK, None, i, i + 1))
            i += 1
        elif c == "]":
            tokens.append((_TOK_RBRACK, None, i, i + 1))
            i += 1
        elif c == ",":
            tokens.append((_TOK_COMMA, None, i, i + 1))
            i += 1
        elif c == "=":
            tokens.append((_TOK_CMP, _OP_EQ, i, i + 1))
            i += 1
        elif c == "<":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_TOK_CMP, _OP_LE, i, i + 2))
                i += 2
            else:
                tokens.append((_TOK_CMP, _OP_LT, i, i + 1))
                i += 1
        elif c == ">":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_TOK_CMP, _OP_GE, i, i + 2))
                i += 2
            else:
                tokens.append((_TOK_CMP, _OP_GT, i, i + 1))
                i += 1
        elif c == "!":
            if i + 1 < n and query[i + 1] == "=":
                tokens.append((_TOK_CMP, _OP_NE, i, i + 2))
                i += 2
            else:
                return ("error", i, "unexpected character '!'")
        elif c == "-":
            if i + 1 < n and "0" <= query[i + 1] <= "9":
                j = i + 2
                while j < n and "0" <= query[j] <= "9":
                    j += 1
                tokens.append((_TOK_INT, _parse_int(query[i:j]), i, j))
                i = j
            else:
                return ("error", i, "unexpected character '-'")
        elif "0" <= c <= "9":
            j = i + 1
            while j < n and "0" <= query[j] <= "9":
                j += 1
            tokens.append((_TOK_INT, _parse_int(query[i:j]), i, j))
            i = j
        elif c == '"':
            start = i
            i += 1
            parts = None
            chunk_start = i
            closed = False
            while i < n:
                ch = query[i]
                if ch == '"':
                    if parts is None:
                        val = query[chunk_start:i]
                    else:
                        parts.append(query[chunk_start:i])
                        val = "".join(parts)
                    i += 1
                    tokens.append((_TOK_STR, val, start, i))
                    closed = True
                    break
                elif ch == "\\":
                    if i + 1 >= n:
                        return ("error", i, "bad escape")
                    nxt = query[i + 1]
                    if nxt != '"' and nxt != "\\":
                        return ("error", i, "bad escape")
                    if parts is None:
                        parts = [query[chunk_start:i]]
                    else:
                        parts.append(query[chunk_start:i])
                    parts.append(nxt)
                    i += 2
                    chunk_start = i
                else:
                    i += 1
            if not closed:
                return ("error", start, "unterminated string")
        elif ("a" <= c <= "z") or ("A" <= c <= "Z") or c == "_":
            j = i + 1
            while j < n:
                ch = query[j]
                if (
                    ("a" <= ch <= "z")
                    or ("A" <= ch <= "Z")
                    or ("0" <= ch <= "9")
                    or ch == "_"
                    or ch == "."
                ):
                    j += 1
                else:
                    break
            word = query[i:j]
            kw = _KEYWORDS.get(word)
            if kw is not None:
                tokens.append((kw, None, i, j))
            else:
                tokens.append((_TOK_FIELD, word, i, j))
            i = j
        else:
            return ("error", i, f"unexpected character '{c}'")

    tokens.append((_TOK_EOF, None, n, n))

    # STEP 2 — PARSING (iterative LL(1))
    def syntax_error(tok):
        kind, _, start, end = tok
        if kind == _TOK_EOF:
            return ("error", start, "unexpected end of input")
        return ("error", start, f"unexpected token '{query[start:end]}'")

    pos = 0
    frames = []
    or_left = None
    and_left = None
    neg = False
    root = None
    done = False

    while not done:
        while tokens[pos][0] == _TOK_NOT:
            pos += 1
            neg = not neg

        tok = tokens[pos]
        kind = tok[0]
        if kind == _TOK_LPAREN:
            pos += 1
            frames.append((or_left, and_left, neg))
            or_left = None
            and_left = None
            neg = False
            continue
        elif kind == _TOK_HAS:
            pos += 1
            tok = tokens[pos]
            if tok[0] != _TOK_FIELD:
                return syntax_error(tok)
            pos += 1
            node = (_OP_HAS, tok[1])
        elif kind == _TOK_FIELD:
            field = tok[1]
            pos += 1
            tok = tokens[pos]
            tkind = tok[0]
            if tkind == _TOK_CMP:
                op_code = tok[1]
                pos += 1
                tok = tokens[pos]
                if tok[0] != _TOK_INT and tok[0] != _TOK_STR:
                    return syntax_error(tok)
                lit = tok[1]
                pos += 1
                node = (op_code, field, lit, type(lit))
            elif tkind == _TOK_IN:
                pos += 1
                tok = tokens[pos]
                if tok[0] != _TOK_LBRACK:
                    return syntax_error(tok)
                pos += 1
                tok = tokens[pos]
                if tok[0] != _TOK_INT and tok[0] != _TOK_STR:
                    return syntax_error(tok)
                lits = {tok[1]}
                pos += 1
                while tokens[pos][0] == _TOK_COMMA:
                    pos += 1
                    tok = tokens[pos]
                    if tok[0] != _TOK_INT and tok[0] != _TOK_STR:
                        return syntax_error(tok)
                    lits.add(tok[1])
                    pos += 1
                tok = tokens[pos]
                if tok[0] != _TOK_RBRACK:
                    return syntax_error(tok)
                pos += 1
                node = (_OP_IN, field, lits)
            else:
                return syntax_error(tok)
        else:
            return syntax_error(tok)

        while True:
            if neg:
                if node[0] == _OP_NOT:
                    node = node[1]
                else:
                    node = (_OP_NOT, node)
                neg = False

            if and_left is not None:
                node = (_OP_AND, and_left, node)
                and_left = None

            if tokens[pos][0] == _TOK_AND:
                pos += 1
                and_left = node
                break

            if or_left is not None:
                node = (_OP_OR, or_left, node)
                or_left = None

            if tokens[pos][0] == _TOK_OR:
                pos += 1
                or_left = node
                break

            if frames:
                tok = tokens[pos]
                if tok[0] != _TOK_RPAREN:
                    return syntax_error(tok)
                pos += 1
                or_left, and_left, neg = frames.pop()
            else:
                tok = tokens[pos]
                if tok[0] != _TOK_EOF:
                    return syntax_error(tok)
                root = node
                done = True
                break

    # Compile AST to flat bytecode iteratively (TRUE=1, UNKNOWN=0, FALSE=-1)
    code = []
    tasks = [(0, root)]
    while tasks:
        t = tasks.pop()
        tk = t[0]
        if tk == 0:
            node = t[1]
            op = node[0]
            if op == _OP_NOT:
                tasks.append((1, (_OP_NOT,)))
                tasks.append((0, node[1]))
            elif op == _OP_AND:
                holder = [0]
                tasks.append((3, holder, _OP_JIF))
                tasks.append((1, (_OP_AND,)))
                tasks.append((0, node[2]))
                tasks.append((2, holder))
                tasks.append((0, node[1]))
            elif op == _OP_OR:
                holder = [0]
                tasks.append((3, holder, _OP_JIT))
                tasks.append((1, (_OP_OR,)))
                tasks.append((0, node[2]))
                tasks.append((2, holder))
                tasks.append((0, node[1]))
            else:
                code.append(node)
        elif tk == 1:
            code.append(t[1])
        elif tk == 2:
            t[1][0] = len(code)
            code.append(None)
        else:
            code[t[1][0]] = (t[2], len(code))

    # STEP 3 — EVALUATION
    indices = []
    code_len = len(code)
    for rec_idx, rec in enumerate(records):
        stack = []
        pc = 0
        while pc < code_len:
            instr = code[pc]
            op = instr[0]
            if op <= _OP_GE:
                val = rec.get(instr[1], _MISSING)
                if val is _MISSING:
                    stack.append(0)
                else:
                    lit = instr[2]
                    if type(val) is not instr[3]:
                        if op == _OP_EQ:
                            stack.append(-1)
                        elif op == _OP_NE:
                            stack.append(1)
                        else:
                            stack.append(0)
                    else:
                        if op == _OP_EQ:
                            stack.append(1 if val == lit else -1)
                        elif op == _OP_NE:
                            stack.append(1 if val != lit else -1)
                        elif op == _OP_LT:
                            stack.append(1 if val < lit else -1)
                        elif op == _OP_LE:
                            stack.append(1 if val <= lit else -1)
                        elif op == _OP_GT:
                            stack.append(1 if val > lit else -1)
                        else:
                            stack.append(1 if val >= lit else -1)
                pc += 1
            elif op == _OP_HAS:
                stack.append(1 if instr[1] in rec else -1)
                pc += 1
            elif op == _OP_IN:
                val = rec.get(instr[1], _MISSING)
                if val is _MISSING:
                    stack.append(0)
                elif val in instr[2]:
                    stack.append(1)
                else:
                    stack.append(-1)
                pc += 1
            elif op == _OP_NOT:
                stack[-1] = -stack[-1]
                pc += 1
            elif op == _OP_AND:
                b = stack.pop()
                if b < stack[-1]:
                    stack[-1] = b
                pc += 1
            elif op == _OP_OR:
                b = stack.pop()
                if b > stack[-1]:
                    stack[-1] = b
                pc += 1
            elif op == _OP_JIF:
                if stack[-1] == -1:
                    pc = instr[1]
                else:
                    pc += 1
            else:  # _OP_JIT
                if stack[-1] == 1:
                    pc = instr[1]
                else:
                    pc += 1
        if stack[0] == 1:
            indices.append(rec_idx)

    return ("ok", indices)

package main

import "sort"

type Tuple1 struct {
	F0 string
	F1 int
}

func LeaderboardRanks(submissions []Tuple1) []int {
	n := len(submissions)
	if n == 0 {
		return []int{}
	}

	order := make([]int, n)
	for i := 0; i < n; i++ {
		order[i] = i
	}

	sort.Slice(order, func(a, b int) bool {
		ia, ib := order[a], order[b]
		sa, sb := submissions[ia].F1, submissions[ib].F1
		if sa != sb {
			return sa > sb
		}
		return ia < ib
	})

	comp := make([]int, n)
	for rank, idx := range order {
		comp[idx] = rank + 1
	}

	bit := make([]int, n+1)
	add := func(idx, delta int) {
		for ; idx <= n; idx += idx & -idx {
			bit[idx] += delta
		}
	}
	query := func(idx int) int {
		sum := 0
		for ; idx > 0; idx -= idx & -idx {
			sum += bit[idx]
		}
		return sum
	}

	type playerState struct {
		best int
		id   int
	}
	players := make(map[string]playerState, n)
	res := make([]int, n)

	for i, sub := range submissions {
		st, ok := players[sub.F0]
		if !ok {
			players[sub.F0] = playerState{best: sub.F1, id: i}
			add(comp[i], 1)
			res[i] = query(comp[i])
		} else if sub.F1 > st.best {
			add(comp[st.id], -1)
			players[sub.F0] = playerState{best: sub.F1, id: i}
			add(comp[i], 1)
			res[i] = query(comp[i])
		} else {
			res[i] = query(comp[st.id])
		}
	}

	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1) {}

    public static List<Long> leaderboardRanks(List<Tuple1> submissions) {
        if (submissions == null || submissions.isEmpty()) {
            return new ArrayList<>();
        }

        int n = submissions.size();
        String[] players = new String[n];
        long[] scores = new long[n];
        Integer[] order = new Integer[n];

        int idx = 0;
        for (Tuple1 sub : submissions) {
            players[idx] = sub.f0();
            scores[idx] = sub.f1();
            order[idx] = idx;
            idx++;
        }

        Arrays.sort(order, (a, b) -> {
            int cmp = Long.compare(scores[b], scores[a]);
            return cmp != 0 ? cmp : Integer.compare(a, b);
        });

        int[] rankId = new int[n];
        for (int r = 0; r < n; r++) {
            rankId[order[r]] = r + 1;
        }

        int[] bit = new int[n + 1];
        Map<String, Integer> playerBestIdx = HashMap.newHashMap(n);
        List<Long> result = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            String player = players[i];
            long score = scores[i];
            Integer prevIdxObj = playerBestIdx.get(player);
            int currIdx;

            if (prevIdxObj == null) {
                currIdx = i;
                playerBestIdx.put(player, i);
                add(bit, rankId[i], 1);
            } else {
                int prevIdx = prevIdxObj;
                if (score > scores[prevIdx]) {
                    add(bit, rankId[prevIdx], -1);
                    currIdx = i;
                    playerBestIdx.put(player, i);
                    add(bit, rankId[i], 1);
                } else {
                    currIdx = prevIdx;
                }
            }

            result.add(1L + query(bit, rankId[currIdx] - 1));
        }

        return result;
    }

    private static void add(int[] bit, int idx, int delta) {
        for (int i = idx; i < bit.length; i += i & -i) {
            bit[i] += delta;
        }
    }

    private static int query(int[] bit, int idx) {
        int sum = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            sum += bit[i];
        }
        return sum;
    }
}

#include <algorithm>
#include <cstddef>
#include <numeric>
#include <string>
#include <string_view>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<long long> leaderboard_ranks(const std::vector<std::tuple<std::string, long long>>& submissions) {
    const std::size_t n = submissions.size();
    std::vector<long long> result;
    if (n == 0) {
        return result;
    }
    result.resize(n);

    std::vector<std::size_t> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](std::size_t a, std::size_t b) {
        const long long score_a = std::get<1>(submissions[a]);
        const long long score_b = std::get<1>(submissions[b]);
        if (score_a != score_b) {
            return score_a > score_b;
        }
        return a < b;
    });

    std::vector<std::size_t> rank_id(n);
    for (std::size_t pos = 0; pos < n; ++pos) {
        rank_id[order[pos]] = pos;
    }

    std::vector<long long> bit(n + 1, 0);
    auto add = [&](std::size_t idx, long long delta) {
        for (std::size_t i = idx + 1; i <= n; i += i & (~i + 1)) {
            bit[i] += delta;
        }
    };
    auto prefix_sum = [&](std::size_t count) -> long long {
        long long sum = 0;
        for (std::size_t i = count; i > 0; i -= i & (~i + 1)) {
            sum += bit[i];
        }
        return sum;
    };

    struct PlayerState {
        long long best_score;
        std::size_t rank_id;
    };
    std::unordered_map<std::string_view, PlayerState> players;
    players.reserve(n);

    for (std::size_t i = 0; i < n; ++i) {
        const auto& [name, score] = submissions[i];
        const std::size_t rid = rank_id[i];
        auto [it, inserted] = players.try_emplace(std::string_view(name), PlayerState{score, rid});
        if (inserted) {
            add(rid, 1);
        } else if (score > it->second.best_score) {
            add(it->second.rank_id, -1);
            it->second.best_score = score;
            it->second.rank_id = rid;
            add(rid, 1);
        }
        result[i] = 1 + prefix_sum(it->second.rank_id);
    }

    return result;
}

export function leaderboardRanks(submissions: [string, number][]): number[] {
  const n = submissions.length;
  if (n === 0) {
    return [];
  }

  const order = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    order[i] = i;
  }

  order.sort((a, b) => {
    const scoreDiff = submissions[b][1] - submissions[a][1];
    return scoreDiff !== 0 ? scoreDiff : a - b;
  });

  const rankPos = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    rankPos[order[i]] = i + 1;
  }

  const bit = new Int32Array(n + 1);
  const playerBestIdx = new Map<string, number>();
  const result = new Array<number>(n);

  for (let i = 0; i < n; i++) {
    const sub = submissions[i];
    const player = sub[0];
    const score = sub[1];
    const prevIdx = playerBestIdx.get(player);

    let pos: number;
    if (prevIdx === undefined) {
      playerBestIdx.set(player, i);
      pos = rankPos[i];
      for (let idx = pos; idx <= n; idx += idx & -idx) {
        bit[idx] += 1;
      }
    } else if (score > submissions[prevIdx][1]) {
      const oldPos = rankPos[prevIdx];
      for (let idx = oldPos; idx <= n; idx += idx & -idx) {
        bit[idx] -= 1;
      }
      playerBestIdx.set(player, i);
      pos = rankPos[i];
      for (let idx = pos; idx <= n; idx += idx & -idx) {
        bit[idx] += 1;
      }
    } else {
      pos = rankPos[prevIdx];
    }

    let rank = 0;
    for (let idx = pos; idx > 0; idx -= idx & -idx) {
      rank += bit[idx];
    }
    result[i] = rank;
  }

  return result;
}

package main

import "sort"

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type pstNode struct {
	left  int32
	right int32
	count int32
	sum   int
}

func BudgetPurchases(prices []int, queries []Tuple1) []Tuple2 {
	if len(queries) == 0 {
		return []Tuple2{}
	}

	n := len(prices)
	sorted := make([]int, n)
	copy(sorted, prices)
	sort.Ints(sorted)

	uniq := sorted[:0]
	for _, p := range sorted {
		if len(uniq) == 0 || uniq[len(uniq)-1] != p {
			uniq = append(uniq, p)
		}
	}
	m := len(uniq)

	nodes := make([]pstNode, 1, 1+n*19)
	roots := make([]int32, n+1)

	for i, val := range prices {
		idx := sort.SearchInts(uniq, val)
		prev := roots[i]
		cur := int32(len(nodes))
		nodes = append(nodes, nodes[prev])
		roots[i+1] = cur
		nodes[cur].count++
		nodes[cur].sum += val

		lo, hi := 0, m-1
		for lo < hi {
			mid := (lo + hi) >> 1
			child := int32(len(nodes))
			if idx <= mid {
				pChild := nodes[prev].left
				nodes[cur].left = child
				nodes = append(nodes, nodes[pChild])
				prev = pChild
				hi = mid
			} else {
				pChild := nodes[prev].right
				nodes[cur].right = child
				nodes = append(nodes, nodes[pChild])
				prev = pChild
				lo = mid + 1
			}
			cur = child
			nodes[cur].count++
			nodes[cur].sum += val
		}
	}

	ans := make([]Tuple2, len(queries))
	for qi, q := range queries {
		u := roots[q.F0]
		v := roots[q.F1+1]
		b := q.F2
		lo, hi := 0, m-1
		cnt := 0
		spent := 0

		for lo < hi {
			if nodes[v].count == nodes[u].count {
				break
			}
			ul := nodes[u].left
			vl := nodes[v].left
			leftCount := int(nodes[vl].count - nodes[ul].count)
			leftSum := nodes[vl].sum - nodes[ul].sum
			mid := (lo + hi) >> 1
			if leftSum <= b {
				cnt += leftCount
				spent += leftSum
				b -= leftSum
				u = nodes[u].right
				v = nodes[v].right
				lo = mid + 1
			} else {
				u = ul
				v = vl
				hi = mid
			}
		}

		if lo == hi && nodes[v].count > nodes[u].count {
			avail := int(nodes[v].count - nodes[u].count)
			price := uniq[lo]
			take := b / price
			if take > avail {
				take = avail
			}
			cnt += take
			spent += take * price
		}

		ans[qi] = Tuple2{F0: cnt, F1: spent}
	}

	return ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2) {}

    public record Tuple2(long f0, long f1) {}

    private static final class PersistentSegTree {
        private final int[] left;
        private final int[] right;
        private final int[] cnt;
        private final long[] sum;
        private int nextNode = 1;

        PersistentSegTree(int maxNodes) {
            this.left = new int[maxNodes];
            this.right = new int[maxNodes];
            this.cnt = new int[maxNodes];
            this.sum = new long[maxNodes];
        }

        int update(int prev, int lo, int hi, int idx, long val) {
            int curr = nextNode++;
            cnt[curr] = cnt[prev] + 1;
            sum[curr] = sum[prev] + val;
            if (lo == hi) {
                return curr;
            }
            int mid = (lo + hi) >>> 1;
            if (idx <= mid) {
                left[curr] = update(left[prev], lo, mid, idx, val);
                right[curr] = right[prev];
            } else {
                left[curr] = left[prev];
                right[curr] = update(right[prev], mid + 1, hi, idx, val);
            }
            return curr;
        }

        Tuple2 query(int nodeL, int nodeR, int m, long budget, long[] unique) {
            int lo = 0;
            int hi = m - 1;
            long totalCount = 0;
            long totalSpent = 0;

            while (lo < hi) {
                if (cnt[nodeR] - cnt[nodeL] == 0 || budget == 0) {
                    break;
                }
                int mid = (lo + hi) >>> 1;
                int lL = left[nodeL];
                int lR = left[nodeR];
                long leftSum = sum[lR] - sum[lL];
                if (leftSum <= budget) {
                    int leftCount = cnt[lR] - cnt[lL];
                    totalCount += leftCount;
                    totalSpent += leftSum;
                    budget -= leftSum;
                    nodeL = right[nodeL];
                    nodeR = right[nodeR];
                    lo = mid + 1;
                } else {
                    nodeL = lL;
                    nodeR = lR;
                    hi = mid;
                }
            }

            if (lo == hi && budget > 0) {
                int avail = cnt[nodeR] - cnt[nodeL];
                if (avail > 0) {
                    long price = unique[lo];
                    long take = Math.min((long) avail, budget / price);
                    totalCount += take;
                    totalSpent += take * price;
                }
            }

            return new Tuple2(totalCount, totalSpent);
        }
    }

    public static List<Tuple2> budgetPurchases(List<Long> prices, List<Tuple1> queries) {
        if (queries.isEmpty()) {
            return new ArrayList<>();
        }

        int n = prices.size();
        long[] priceArr = new long[n];
        long[] sorted = new long[n];
        for (int i = 0; i < n; i++) {
            long p = prices.get(i);
            priceArr[i] = p;
            sorted[i] = p;
        }
        Arrays.sort(sorted);

        long[] unique = new long[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                unique[m++] = sorted[i];
            }
        }

        int depth = 32 - Integer.numberOfLeadingZeros(Math.max(1, m - 1)) + 1;
        int maxNodes = 1 + n * (depth + 1);
        PersistentSegTree pst = new PersistentSegTree(maxNodes);

        int[] roots = new int[n + 1];
        for (int i = 0; i < n; i++) {
            int idx = Arrays.binarySearch(unique, 0, m, priceArr[i]);
            roots[i + 1] = pst.update(roots[i], 0, m - 1, idx, priceArr[i]);
        }

        List<Tuple2> result = new ArrayList<>(queries.size());
        for (Tuple1 q : queries) {
            int l = (int) q.f0();
            int r = (int) q.f1();
            long budget = q.f2();
            result.add(pst.query(roots[l], roots[r + 1], m, budget, unique));
        }

        return result;
    }
}

#include <algorithm>
#include <tuple>
#include <vector>

std::vector<std::tuple<long long, long long>> budget_purchases(
    const std::vector<long long>& prices,
    const std::vector<std::tuple<long long, long long, long long>>& queries) {
    if (queries.empty()) {
        return {};
    }

    int n = static_cast<int>(prices.size());
    std::vector<long long> vals = prices;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());

    struct Node {
        int left = 0;
        int right = 0;
        int cnt = 0;
        long long sum = 0;
    };

    int log_m = 0;
    while ((1 << log_m) < m) {
        ++log_m;
    }

    std::vector<Node> tree;
    tree.reserve(1 + static_cast<size_t>(n) * (log_m + 2));
    tree.push_back(Node{0, 0, 0, 0});

    std::vector<int> roots(n + 1, 0);

    for (int i = 0; i < n; ++i) {
        long long p = prices[i];
        int idx = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), p) - vals.begin());

        int prev = roots[i];
        roots[i + 1] = static_cast<int>(tree.size());

        int l = 0;
        int r = m - 1;
        while (true) {
            Node node = tree[prev];
            node.cnt += 1;
            node.sum += p;
            int node_id = static_cast<int>(tree.size());
            tree.push_back(node);

            if (l == r) {
                break;
            }
            int mid = l + (r - l) / 2;
            int next_child = static_cast<int>(tree.size());
            if (idx <= mid) {
                tree[node_id].left = next_child;
                prev = tree[prev].left;
                r = mid;
            } else {
                tree[node_id].right = next_child;
                prev = tree[prev].right;
                l = mid + 1;
            }
        }
    }

    std::vector<std::tuple<long long, long long>> ans;
    ans.reserve(queries.size());

    for (const auto& q : queries) {
        int u = roots[static_cast<size_t>(std::get<0>(q))];
        int v = roots[static_cast<size_t>(std::get<1>(q)) + 1];
        long long budget = std::get<2>(q);

        long long count = 0;
        long long spent = 0;
        int l = 0;
        int r = m - 1;

        while (l < r) {
            int ul = tree[u].left;
            int vl = tree[v].left;
            int left_cnt = tree[vl].cnt - tree[ul].cnt;
            long long left_sum = tree[vl].sum - tree[ul].sum;

            int mid = l + (r - l) / 2;
            if (budget >= left_sum) {
                count += left_cnt;
                spent += left_sum;
                budget -= left_sum;
                u = tree[u].right;
                v = tree[v].right;
                l = mid + 1;
            } else {
                u = ul;
                v = vl;
                r = mid;
            }
        }

        int leaf_cnt = tree[v].cnt - tree[u].cnt;
        if (leaf_cnt > 0 && budget > 0) {
            long long take = std::min<long long>(leaf_cnt, budget / vals[l]);
            count += take;
            spent += take * vals[l];
        }

        ans.emplace_back(count, spent);
    }

    return ans;
}

export function budgetPurchases(
  prices: number[],
  queries: [number, number, number][],
): [number, number][] {
  const q = queries.length;
  if (q === 0) {
    return [];
  }

  const n = prices.length;
  const result: [number, number][] = new Array(q);

  if (n === 0) {
    for (let i = 0; i < q; i++) {
      result[i] = [0, 0];
    }
    return result;
  }

  // Coordinate-compress prices into sorted unique values.
  const sorted = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    sorted[i] = prices[i];
  }
  sorted.sort();

  const uniq = new Int32Array(n);
  let m = 0;
  let prevVal = -1;
  for (let i = 0; i < n; i++) {
    const v = sorted[i];
    if (v !== prevVal) {
      uniq[m++] = v;
      prevVal = v;
    }
  }

  // Persistent segment tree over value ranks [0 .. m - 1].
  // Node 0 acts as the shared empty node.
  const depth = Math.ceil(Math.log2(m > 1 ? m : 2)) + 2;
  const maxNodes = n * depth + 2;
  const left = new Int32Array(maxNodes);
  const right = new Int32Array(maxNodes);
  const cnt = new Int32Array(maxNodes);
  const sum = new Float64Array(maxNodes);
  const roots = new Int32Array(n + 1);

  let nodeCount = 0;

  for (let i = 0; i < n; i++) {
    const val = prices[i];
    let lo = 0;
    let hi = m - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (uniq[mid] < val) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    const idx = lo;

    let prev = roots[i];
    roots[i + 1] = nodeCount + 1;
    lo = 0;
    hi = m - 1;

    while (true) {
      const curr = ++nodeCount;
      cnt[curr] = cnt[prev] + 1;
      sum[curr] = sum[prev] + val;
      if (lo === hi) {
        break;
      }
      const mid = (lo + hi) >> 1;
      if (idx <= mid) {
        right[curr] = right[prev];
        left[curr] = curr + 1;
        prev = left[prev];
        hi = mid;
      } else {
        left[curr] = left[prev];
        right[curr] = curr + 1;
        prev = right[prev];
        lo = mid + 1;
      }
    }
  }

  for (let i = 0; i < q; i++) {
    const query = queries[i];
    const l = query[0];
    const r = query[1];
    const budget = query[2];

    if (budget <= 0) {
      result[i] = [0, 0];
      continue;
    }

    let u = roots[l];
    let v = roots[r + 1];
    const totalSum = sum[v] - sum[u];
    if (totalSum <= budget) {
      result[i] = [cnt[v] - cnt[u], totalSum];
      continue;
    }

    let ansCnt = 0;
    let ansSum = 0;
    let rem = budget;
    let lo = 0;
    let hi = m - 1;

    while (lo < hi && rem > 0 && cnt[v] > cnt[u]) {
      const mid = (lo + hi) >> 1;
      const lu = left[u];
      const lv = left[v];
      const lSum = sum[lv] - sum[lu];
      if (lSum <= rem) {
        ansCnt += cnt[lv] - cnt[lu];
        ansSum += lSum;
        rem -= lSum;
        u = right[u];
        v = right[v];
        lo = mid + 1;
      } else {
        u = lu;
        v = lv;
        hi = mid;
      }
    }

    if (lo === hi && rem > 0) {
      const leafCnt = cnt[v] - cnt[u];
      if (leafCnt > 0) {
        const val = uniq[lo];
        let take = Math.floor(rem / val);
        if (take > leafCnt) {
          take = leafCnt;
        }
        if (take > 0) {
          ansCnt += take;
          ansSum += take * val;
        }
      }
    }

    result[i] = [ansCnt, ansSum];
  }

  return result;
}

package main

import "math"

type Tuple1 struct {
	F0 int
	F1 int
}

func CountRecords(levels []int, margin int, queries []Tuple1) []int {
	qLen := len(queries)
	if qLen == 0 {
		return []int{}
	}

	n := len(levels)

	size := 1
	for size < n {
		size <<= 1
	}

	tree := make([]int, 2*size)
	for i := 0; i < n; i++ {
		tree[size+i] = levels[i]
	}
	for i := n; i < size; i++ {
		tree[size+i] = math.MinInt64
	}
	for i := size - 1; i >= 1; i-- {
		a, b := tree[i<<1], tree[(i<<1)|1]
		if a >= b {
			tree[i] = a
		} else {
			tree[i] = b
		}
	}

	K := 1
	for (1 << K) <= n {
		K++
	}

	jump := make([][]int32, K)
	jump[0] = make([]int32, n+1)
	jump0 := jump[0]

	for i := 0; i < n-1; i++ {
		target := levels[i] + margin
		p := i + 1 + size
		nxt := n
		for {
			if tree[p] >= target {
				for p < size {
					if tree[p<<1] >= target {
						p <<= 1
					} else {
						p = (p << 1) | 1
					}
				}
				nxt = p - size
				break
			}
			if (p & (p + 1)) == 0 {
				break
			}
			if (p & 1) == 0 {
				p++
			} else {
				p = (p + 1) >> 1
			}
		}
		jump0[i] = int32(nxt)
	}
	jump0[n-1] = int32(n)
	jump0[n] = int32(n)

	for k := 1; k < K; k++ {
		prev := jump[k-1]
		cur := make([]int32, n+1)
		for i := 0; i <= n; i++ {
			cur[i] = prev[prev[i]]
		}
		jump[k] = cur
	}

	res := make([]int, qLen)
	for qi, q := range queries {
		curr := q.F0
		r := q.F1
		cnt := 1
		for k := K - 1; k >= 0; k-- {
			nxt := int(jump[k][curr])
			if nxt <= r {
				curr = nxt
				cnt += 1 << k
			}
		}
		res[qi] = cnt
	}

	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1) {}

    public static List<Long> countRecords(List<Long> levels, long margin, List<Tuple1> queries) {
        int qSize = queries.size();
        if (qSize == 0) {
            return new ArrayList<>(0);
        }

        int n = levels.size();
        long[] vals = new long[n];
        int idx = 0;
        for (long v : levels) {
            vals[idx++] = v;
        }

        int[] next = new int[n + 1];
        next[n] = n;

        long[] heapVal = new long[n + 1];
        int[] heapIdx = new int[n + 1];
        int heapSize = 0;

        for (int j = 0; j < n; j++) {
            long v = vals[j];
            while (heapSize > 0 && heapVal[1] <= v) {
                next[heapIdx[1]] = j;
                long topV = heapVal[heapSize];
                int topI = heapIdx[heapSize];
                heapSize--;
                if (heapSize > 0) {
                    int p = 1;
                    int half = heapSize >>> 1;
                    while (p <= half) {
                        int left = p << 1;
                        int right = left + 1;
                        int smallest = (right <= heapSize && heapVal[right] < heapVal[left]) ? right : left;
                        if (heapVal[smallest] >= topV) {
                            break;
                        }
                        heapVal[p] = heapVal[smallest];
                        heapIdx[p] = heapIdx[smallest];
                        p = smallest;
                    }
                    heapVal[p] = topV;
                    heapIdx[p] = topI;
                }
            }

            heapSize++;
            int p = heapSize;
            long target = v + margin;
            while (p > 1) {
                int parent = p >>> 1;
                if (heapVal[parent] > target) {
                    heapVal[p] = heapVal[parent];
                    heapIdx[p] = heapIdx[parent];
                    p = parent;
                } else {
                    break;
                }
            }
            heapVal[p] = target;
            heapIdx[p] = j;
        }

        while (heapSize > 0) {
            next[heapIdx[heapSize--]] = n;
        }

        int log = 1;
        while ((1 << log) <= n) {
            log++;
        }

        int[][] up = new int[log][n + 1];
        up[0] = next;
        for (int k = 1; k < log; k++) {
            int[] prev = up[k - 1];
            int[] curr = up[k];
            for (int i = 0; i <= n; i++) {
                curr[i] = prev[prev[i]];
            }
        }

        List<Long> ans = new ArrayList<>(qSize);
        for (Tuple1 q : queries) {
            int l = (int) q.f0();
            int r = (int) q.f1();
            int curr = l;
            long count = 1L;
            for (int k = log - 1; k >= 0; k--) {
                int nxt = up[k][curr];
                if (nxt <= r) {
                    curr = nxt;
                    count += (1L << k);
                }
            }
            ans.add(count);
        }

        return ans;
    }
}

#include <algorithm>
#include <tuple>
#include <vector>

std::vector<long long> count_records(const std::vector<long long>& levels, long long margin, const std::vector<std::tuple<long long, long long>>& queries) {
    if (queries.empty()) {
        return {};
    }

    int n = static_cast<int>(levels.size());
    std::vector<long long> tree(4 * n);

    auto build = [&](auto& self, int node, int l, int r) -> void {
        if (l == r) {
            tree[node] = levels[l];
            return;
        }
        int mid = l + (r - l) / 2;
        self(self, 2 * node, l, mid);
        self(self, 2 * node + 1, mid + 1, r);
        tree[node] = std::max(tree[2 * node], tree[2 * node + 1]);
    };
    build(build, 1, 0, n - 1);

    auto find_next = [&](auto& self, int node, int l, int r, int min_idx, long long target) -> int {
        if (r < min_idx || tree[node] < target) {
            return n;
        }
        if (l == r) {
            return l;
        }
        int mid = l + (r - l) / 2;
        int res = self(self, 2 * node, l, mid, min_idx, target);
        if (res < n) {
            return res;
        }
        return self(self, 2 * node + 1, mid + 1, r, min_idx, target);
    };

    int log_n = 1;
    while ((1 << log_n) <= n) {
        ++log_n;
    }

    int stride = n + 1;
    std::vector<int> up(static_cast<std::size_t>(log_n) * stride, n);

    for (int i = 0; i < n - 1; ++i) {
        up[i] = find_next(find_next, 1, 0, n - 1, i + 1, levels[i] + margin);
    }

    for (int k = 1; k < log_n; ++k) {
        int prev_offset = (k - 1) * stride;
        int curr_offset = k * stride;
        for (int i = 0; i <= n; ++i) {
            up[curr_offset + i] = up[prev_offset + up[prev_offset + i]];
        }
    }

    std::vector<long long> result;
    result.reserve(queries.size());

    for (const auto& [ql, qr] : queries) {
        int curr = static_cast<int>(ql);
        int r = static_cast<int>(qr);
        long long count = 1;
        for (int k = log_n - 1; k >= 0; --k) {
            int nxt = up[k * stride + curr];
            if (nxt <= r) {
                curr = nxt;
                count += (1LL << k);
            }
        }
        result.push_back(count);
    }

    return result;
}

export function countRecords(
  levels: number[],
  margin: number,
  queries: [number, number][],
): number[] {
  const qLen = queries.length;
  if (qLen === 0) {
    return [];
  }

  const n = levels.length;
  let size = 1;
  while (size < n) {
    size <<= 1;
  }

  const seg = new Float64Array(2 * size);
  seg.fill(-Infinity);
  for (let i = 0; i < n; i++) {
    seg[size + i] = levels[i];
  }
  for (let p = size - 1; p >= 1; p--) {
    const a = seg[p << 1];
    const b = seg[(p << 1) | 1];
    seg[p] = a >= b ? a : b;
  }

  let log = 1;
  while ((1 << log) <= n) {
    log++;
  }

  const stride = n + 1;
  const up = new Int32Array(log * stride);

  for (let i = 0; i < n; i++) {
    const target = levels[i] + margin;
    const start = i + 1;
    let nxt = n;

    if (start < n) {
      let p = size + start;
      if (seg[p] >= target) {
        nxt = start;
      } else {
        let found = 0;
        while (p > 1) {
          if ((p & 1) === 0 && seg[p + 1] >= target) {
            found = p + 1;
            break;
          }
          p >>= 1;
        }
        if (found !== 0) {
          p = found;
          while (p < size) {
            p <<= 1;
            if (seg[p] < target) {
              p |= 1;
            }
          }
          const idx = p - size;
          if (idx < n) {
            nxt = idx;
          }
        }
      }
    }

    up[i] = nxt;
  }
  up[n] = n;

  for (let k = 1; k < log; k++) {
    const prevOff = (k - 1) * stride;
    const curOff = k * stride;
    for (let i = 0; i <= n; i++) {
      up[curOff + i] = up[prevOff + up[prevOff + i]];
    }
  }

  const ans = new Array<number>(qLen);
  for (let q = 0; q < qLen; q++) {
    const l = queries[q][0];
    const r = queries[q][1];
    let curr = l;
    let count = 1;
    for (let k = log - 1; k >= 0; k--) {
      const nxt = up[k * stride + curr];
      if (nxt <= r) {
        curr = nxt;
        count += 1 << k;
      }
    }
    ans[q] = count;
  }

  return ans;
}

import math
import re

_PRINCIPAL_RE = re.compile(r"\A[0-9]+(?:\.[0-9]{1,2})?\Z")
_RATE_RE = re.compile(r"\A[0-9]+(?:\.[0-9]{1,6})?\Z")


def _format_cents(cents: int) -> str:
    dollars, rem = divmod(cents, 100)
    return f"{dollars}.{rem:02d}"


def amortize(
    principal: str, annual_rate_pct: str, months: int
) -> list[tuple[str, str, str]]:
    if not isinstance(principal, str) or _PRINCIPAL_RE.match(principal) is None:
        raise ValueError("Invalid principal format")
    if "." in principal:
        int_part, frac_part = principal.split(".")
        p_cents = int(int_part.lstrip("0") or "0") * 100 + int(frac_part.ljust(2, "0"))
    else:
        p_cents = int(principal.lstrip("0") or "0") * 100
    if p_cents <= 0:
        raise ValueError("Principal must be greater than 0")

    if not isinstance(annual_rate_pct, str) or _RATE_RE.match(annual_rate_pct) is None:
        raise ValueError("Invalid annual_rate_pct format")
    if "." in annual_rate_pct:
        int_part, frac_part = annual_rate_pct.split(".")
        rate_scaled = (
            int(int_part.lstrip("0") or "0") * 1_000_000
            + int(frac_part.ljust(6, "0"))
        )
    else:
        rate_scaled = int(annual_rate_pct.lstrip("0") or "0") * 1_000_000
    if rate_scaled > 100_000_000:
        raise ValueError("annual_rate_pct must be <= 100")

    if isinstance(months, bool) or not isinstance(months, int) or not (1 <= months <= 1200):
        raise ValueError("months must be an int with 1 <= months <= 1200")

    # Monthly rate m = rate_scaled / (100 * 12 * 1_000_000) = m_num / m_den
    if rate_scaled == 0:
        m_num = 0
        m_den = 1
        pay_cents = (p_cents + months - 1) // months
    else:
        den_base = 1_200_000_000
        g = math.gcd(rate_scaled, den_base)
        m_num = rate_scaled // g
        m_den = den_base // g

        # 100 * A = p_cents * m_num * a^n / (m_den * (a^n - b^n))
        # where a = m_den + m_num and b = m_den
        a_n = pow(m_den + m_num, months)
        b_n = pow(m_den, months)
        num = p_cents * m_num * a_n
        den = m_den * (a_n - b_n)
        pay_cents = (num + den - 1) // den

    pay_str = _format_cents(pay_cents)
    schedule: list[tuple[str, str, str]] = []
    bal_cents = p_cents

    for t in range(1, months + 1):
        if m_num == 0:
            interest_cents = 0
        else:
            q, r = divmod(bal_cents * m_num, m_den)
            twice_r = r << 1
            if twice_r > m_den or (twice_r == m_den and (q & 1)):
                interest_cents = q + 1
            else:
                interest_cents = q

        if t == months or bal_cents + interest_cents <= pay_cents:
            final_payment = bal_cents + interest_cents
            schedule.append(
                (_format_cents(final_payment), _format_cents(interest_cents), "0.00")
            )
            break

        bal_cents -= pay_cents - interest_cents
        schedule.append(
            (pay_str, _format_cents(interest_cents), _format_cents(bal_cents))
        )

    return schedule

package main

import (
	"errors"
	"math/big"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
}

func isASCIIDigits(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func parsePrincipalCents(s string) (*big.Int, error) {
	dot := strings.IndexByte(s, '.')
	var combined string
	if dot == -1 {
		if !isASCIIDigits(s) {
			return nil, errors.New("invalid principal")
		}
		combined = s + "00"
	} else {
		intPart := s[:dot]
		fracPart := s[dot+1:]
		if !isASCIIDigits(intPart) || !isASCIIDigits(fracPart) || len(fracPart) < 1 || len(fracPart) > 2 {
			return nil, errors.New("invalid principal")
		}
		if len(fracPart) == 1 {
			combined = intPart + fracPart + "0"
		} else {
			combined = intPart + fracPart
		}
	}
	val, ok := new(big.Int).SetString(combined, 10)
	if !ok || val.Sign() <= 0 {
		return nil, errors.New("invalid principal")
	}
	return val, nil
}

func parseAnnualRateScaled(s string) (*big.Int, error) {
	dot := strings.IndexByte(s, '.')
	var combined string
	if dot == -1 {
		if !isASCIIDigits(s) {
			return nil, errors.New("invalid annual_rate_pct")
		}
		combined = s + "000000"
	} else {
		intPart := s[:dot]
		fracPart := s[dot+1:]
		if !isASCIIDigits(intPart) || !isASCIIDigits(fracPart) || len(fracPart) < 1 || len(fracPart) > 6 {
			return nil, errors.New("invalid annual_rate_pct")
		}
		combined = intPart + fracPart + strings.Repeat("0", 6-len(fracPart))
	}
	val, ok := new(big.Int).SetString(combined, 10)
	if !ok {
		return nil, errors.New("invalid annual_rate_pct")
	}
	if val.Cmp(big.NewInt(100_000_000)) > 0 {
		return nil, errors.New("annual_rate_pct exceeds 100")
	}
	return val, nil
}

func gcdInt64(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func formatCents(c *big.Int) string {
	s := c.String()
	switch len(s) {
	case 1:
		return "0.0" + s
	case 2:
		return "0." + s
	default:
		return s[:len(s)-2] + "." + s[len(s)-2:]
	}
}

func Amortize(principal string, annual_rate_pct string, months int) ([]Tuple1, error) {
	if months < 1 || months > 1200 {
		return nil, errors.New("months out of range")
	}

	pCents, err := parsePrincipalCents(principal)
	if err != nil {
		return nil, err
	}

	rateScaled, err := parseAnnualRateScaled(annual_rate_pct)
	if err != nil {
		return nil, err
	}

	rateVal := rateScaled.Int64()
	nBig := big.NewInt(int64(months))
	one := big.NewInt(1)

	rows := make([]Tuple1, 0, months)
	balCents := new(big.Int).Set(pCents)

	if rateVal == 0 {
		payCents := new(big.Int).Add(pCents, nBig)
		payCents.Sub(payCents, one)
		payCents.Quo(payCents, nBig)
		payStr := formatCents(payCents)

		for t := 1; t <= months; t++ {
			if t == months || balCents.Cmp(payCents) <= 0 {
				rows = append(rows, Tuple1{
					F0: formatCents(balCents),
					F1: "0.00",
					F2: "0.00",
				})
				break
			}
			balCents.Sub(balCents, payCents)
			rows = append(rows, Tuple1{
				F0: payStr,
				F1: "0.00",
				F2: formatCents(balCents),
			})
		}
		return rows, nil
	}

	g := gcdInt64(rateVal, 1_200_000_000)
	numInt := rateVal / g
	denInt := 1_200_000_000 / g

	num := big.NewInt(numInt)
	den := big.NewInt(denInt)
	a := big.NewInt(denInt + numInt)
	b := den

	aPow := new(big.Int).Exp(a, nBig, nil)
	bPow := new(big.Int).Exp(b, nBig, nil)
	diffPow := new(big.Int).Sub(aPow, bPow)

	numer := new(big.Int).Mul(pCents, num)
	numer.Mul(numer, aPow)
	denom := new(big.Int).Mul(den, diffPow)

	payCents := new(big.Int).Add(numer, denom)
	payCents.Sub(payCents, one)
	payCents.Quo(payCents, denom)
	payStr := formatCents(payCents)

	x := new(big.Int)
	q := new(big.Int)
	r := new(big.Int)
	r2 := new(big.Int)
	balPlusInt := new(big.Int)

	for t := 1; t <= months; t++ {
		x.Mul(balCents, num)
		q.QuoRem(x, den, r)
		r2.Lsh(r, 1)
		cmp := r2.Cmp(den)
		if cmp > 0 || (cmp == 0 && q.Bit(0) == 1) {
			q.Add(q, one)
		}

		intStr := formatCents(q)
		balPlusInt.Add(balCents, q)

		if t == months || balPlusInt.Cmp(payCents) <= 0 {
			rows = append(rows, Tuple1{
				F0: formatCents(balPlusInt),
				F1: intStr,
				F2: "0.00",
			})
			break
		}

		balCents.Sub(balPlusInt, payCents)
		rows = append(rows, Tuple1{
			F0: payStr,
			F1: intStr,
			F2: formatCents(balCents),
		})
	}

	return rows, nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2) {}

    public static List<Tuple1> amortize(String principal, String annual_rate_pct, long months) {
        if (months < 1 || months > 1200) {
            throw new IllegalArgumentException("months must be between 1 and 1200");
        }

        BigInteger principalCents = parsePrincipalCents(principal);
        long rateScaled = parseAnnualRateScaled(annual_rate_pct);
        int n = (int) months;

        BigInteger payCents;
        BigInteger aBi = BigInteger.ZERO;
        BigInteger bBi = BigInteger.ONE;

        if (rateScaled == 0L) {
            BigInteger nBi = BigInteger.valueOf(n);
            payCents = principalCents.add(nBi).subtract(BigInteger.ONE).divide(nBi);
        } else {
            long rDen = 1_200_000_000L;
            long g = gcd(rateScaled, rDen);
            long a = rateScaled / g;
            long b = rDen / g;

            aBi = BigInteger.valueOf(a);
            bBi = BigInteger.valueOf(b);
            BigInteger cBi = BigInteger.valueOf(a + b);

            BigInteger cPow = cBi.pow(n);
            BigInteger bPow = bBi.pow(n);

            BigInteger num = principalCents.multiply(aBi).multiply(cPow);
            BigInteger den = bBi.multiply(cPow.subtract(bPow));
            payCents = num.add(den).subtract(BigInteger.ONE).divide(den);
        }

        List<Tuple1> schedule = new ArrayList<>();
        BigInteger balCents = principalCents;

        for (int t = 1; t <= n; t++) {
            BigInteger interestCents;
            if (rateScaled == 0L) {
                interestCents = BigInteger.ZERO;
            } else {
                BigInteger[] qr = balCents.multiply(aBi).divideAndRemainder(bBi);
                BigInteger q = qr[0];
                BigInteger r = qr[1];
                int cmp = r.shiftLeft(1).compareTo(bBi);
                if (cmp > 0 || (cmp == 0 && q.testBit(0))) {
                    interestCents = q.add(BigInteger.ONE);
                } else {
                    interestCents = q;
                }
            }

            BigInteger balPlusInterest = balCents.add(interestCents);
            if (t == n || balPlusInterest.compareTo(payCents) <= 0) {
                schedule.add(new Tuple1(
                        formatCents(balPlusInterest),
                        formatCents(interestCents),
                        "0.00"
                ));
                break;
            } else {
                balCents = balPlusInterest.subtract(payCents);
                schedule.add(new Tuple1(
                        formatCents(payCents),
                        formatCents(interestCents),
                        formatCents(balCents)
                ));
            }
        }

        return schedule;
    }

    private static BigInteger parsePrincipalCents(String principal) {
        if (principal == null || principal.isEmpty()) {
            throw new IllegalArgumentException("Invalid principal");
        }
        int dotIdx = principal.indexOf('.');
        String intPart;
        String fracPart;
        if (dotIdx == -1) {
            intPart = principal;
            fracPart = "";
        } else {
            if (principal.indexOf('.', dotIdx + 1) != -1) {
                throw new IllegalArgumentException("Invalid principal");
            }
            intPart = principal.substring(0, dotIdx);
            fracPart = principal.substring(dotIdx + 1);
            if (fracPart.length() < 1 || fracPart.length() > 2) {
                throw new IllegalArgumentException("Invalid principal");
            }
        }
        if (intPart.isEmpty() || !isAsciiDigits(intPart) || !isAsciiDigits(fracPart)) {
            throw new IllegalArgumentException("Invalid principal");
        }

        BigInteger cents = new BigInteger(intPart).multiply(BigInteger.valueOf(100));
        if (fracPart.length() == 1) {
            cents = cents.add(BigInteger.valueOf((fracPart.charAt(0) - '0') * 10L));
        } else if (fracPart.length() == 2) {
            long f = (fracPart.charAt(0) - '0') * 10L + (fracPart.charAt(1) - '0');
            cents = cents.add(BigInteger.valueOf(f));
        }

        if (cents.signum() <= 0) {
            throw new IllegalArgumentException("Principal must be > 0");
        }
        return cents;
    }

    private static long parseAnnualRateScaled(String rate) {
        if (rate == null || rate.isEmpty()) {
            throw new IllegalArgumentException("Invalid annual_rate_pct");
        }
        int dotIdx = rate.indexOf('.');
        String intPart;
        String fracPart;
        if (dotIdx == -1) {
            intPart = rate;
            fracPart = "";
        } else {
            if (rate.indexOf('.', dotIdx + 1) != -1) {
                throw new IllegalArgumentException("Invalid annual_rate_pct");
            }
            intPart = rate.substring(0, dotIdx);
            fracPart = rate.substring(dotIdx + 1);
            if (fracPart.length() < 1 || fracPart.length() > 6) {
                throw new IllegalArgumentException("Invalid annual_rate_pct");
            }
        }
        if (intPart.isEmpty() || !isAsciiDigits(intPart) || !isAsciiDigits(fracPart)) {
            throw new IllegalArgumentException("Invalid annual_rate_pct");
        }

        BigInteger rateInt = new BigInteger(intPart);
        if (rateInt.compareTo(BigInteger.valueOf(100)) > 0) {
            throw new IllegalArgumentException("annual_rate_pct must be <= 100");
        }

        long intVal = rateInt.longValue();
        long fracVal = 0L;
        long mul = 100_000L;
        for (int i = 0; i < fracPart.length(); i++) {
            fracVal += (fracPart.charAt(i) - '0') * mul;
            mul /= 10L;
        }

        long scaled = intVal * 1_000_000L + fracVal;
        if (scaled > 100_000_000L) {
            throw new IllegalArgumentException("annual_rate_pct must be <= 100");
        }
        return scaled;
    }

    private static boolean isAsciiDigits(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static long gcd(long a, long b) {
        while (b != 0L) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private static String formatCents(BigInteger cents) {
        BigInteger[] qr = cents.divideAndRemainder(BigInteger.valueOf(100));
        long frac = qr[1].longValue();
        StringBuilder sb = new StringBuilder();
        sb.append(qr[0].toString()).append('.');
        if (frac < 10L) {
            sb.append('0');
        }
        sb.append(frac);
        return sb.toString();
    }
}

#include <algorithm>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <numeric>
#include <stdexcept>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

namespace {

struct BigUInt {
    std::vector<uint32_t> limbs;

    BigUInt() = default;

    explicit BigUInt(uint32_t v) {
        if (v != 0) {
            limbs.push_back(v);
        }
    }

    void trim() {
        while (!limbs.empty() && limbs.back() == 0) {
            limbs.pop_back();
        }
    }

    bool is_zero() const {
        return limbs.empty();
    }

    bool is_odd() const {
        return !limbs.empty() && (limbs[0] & 1U) != 0;
    }

    size_t bit_length() const {
        if (limbs.empty()) return 0;
        return (limbs.size() - 1) * 32 + static_cast<size_t>(std::bit_width(limbs.back()));
    }

    void set_bit(size_t bit) {
        size_t idx = bit / 32;
        size_t off = bit % 32;
        if (limbs.size() <= idx) {
            limbs.resize(idx + 1, 0);
        }
        limbs[idx] |= (uint32_t(1) << off);
    }

    static int cmp(const BigUInt& a, const BigUInt& b) {
        if (a.limbs.size() != b.limbs.size()) {
            return a.limbs.size() < b.limbs.size() ? -1 : 1;
        }
        for (size_t i = a.limbs.size(); i-- > 0;) {
            if (a.limbs[i] != b.limbs[i]) {
                return a.limbs[i] < b.limbs[i] ? -1 : 1;
            }
        }
        return 0;
    }

    static BigUInt add(const BigUInt& a, const BigUInt& b) {
        BigUInt res;
        size_t n = std::max(a.limbs.size(), b.limbs.size());
        res.limbs.resize(n);
        uint64_t carry = 0;
        for (size_t i = 0; i < n; ++i) {
            uint64_t sum = carry;
            if (i < a.limbs.size()) sum += a.limbs[i];
            if (i < b.limbs.size()) sum += b.limbs[i];
            res.limbs[i] = static_cast<uint32_t>(sum);
            carry = sum >> 32;
        }
        if (carry > 0) {
            res.limbs.push_back(static_cast<uint32_t>(carry));
        }
        res.trim();
        return res;
    }

    static BigUInt add_u32(const BigUInt& a, uint32_t k) {
        if (k == 0) return a;
        BigUInt res = a;
        uint64_t carry = k;
        for (size_t i = 0; i < res.limbs.size() && carry > 0; ++i) {
            uint64_t sum = static_cast<uint64_t>(res.limbs[i]) + carry;
            res.limbs[i] = static_cast<uint32_t>(sum);
            carry = sum >> 32;
        }
        if (carry > 0) {
            res.limbs.push_back(static_cast<uint32_t>(carry));
        }
        return res;
    }

    static void sub_inplace(BigUInt& a, const BigUInt& b) {
        uint64_t borrow = 0;
        for (size_t i = 0; i < a.limbs.size(); ++i) {
            uint64_t av = a.limbs[i];
            uint64_t bv = (i < b.limbs.size() ? static_cast<uint64_t>(b.limbs[i]) : 0ULL) + borrow;
            if (av >= bv) {
                a.limbs[i] = static_cast<uint32_t>(av - bv);
                borrow = 0;
            } else {
                a.limbs[i] = static_cast<uint32_t>((1ULL << 32) + av - bv);
                borrow = 1;
            }
            if (i >= b.limbs.size() && borrow == 0) {
                break;
            }
        }
        a.trim();
    }

    static BigUInt mul(const BigUInt& a, const BigUInt& b) {
        if (a.is_zero() || b.is_zero()) return BigUInt();
        BigUInt res;
        res.limbs.assign(a.limbs.size() + b.limbs.size(), 0);
        for (size_t i = 0; i < a.limbs.size(); ++i) {
            uint64_t ai = a.limbs[i];
            if (ai == 0) continue;
            uint64_t carry = 0;
            for (size_t j = 0; j < b.limbs.size(); ++j) {
                uint64_t cur = ai * b.limbs[j] + res.limbs[i + j] + carry;
                res.limbs[i + j] = static_cast<uint32_t>(cur);
                carry = cur >> 32;
            }
            res.limbs[i + b.limbs.size()] = static_cast<uint32_t>(carry);
        }
        res.trim();
        return res;
    }

    BigUInt mul_u32(uint32_t k) const {
        if (is_zero() || k == 0) return BigUInt();
        BigUInt res;
        res.limbs.resize(limbs.size());
        uint64_t carry = 0;
        for (size_t i = 0; i < limbs.size(); ++i) {
            uint64_t cur = static_cast<uint64_t>(limbs[i]) * k + carry;
            res.limbs[i] = static_cast<uint32_t>(cur);
            carry = cur >> 32;
        }
        if (carry > 0) {
            res.limbs.push_back(static_cast<uint32_t>(carry));
        }
        res.trim();
        return res;
    }

    uint32_t divmod_u32(uint32_t d) {
        uint64_t rem = 0;
        for (size_t i = limbs.size(); i-- > 0;) {
            uint64_t cur = (rem << 32) | limbs[i];
            limbs[i] = static_cast<uint32_t>(cur / d);
            rem = cur % d;
        }
        trim();
        return static_cast<uint32_t>(rem);
    }

    BigUInt shl(size_t bits) const {
        if (is_zero() || bits == 0) return *this;
        size_t word_shift = bits / 32;
        size_t bit_shift = bits % 32;
        BigUInt res;
        res.limbs.assign(limbs.size() + word_shift + (bit_shift != 0 ? 1 : 0), 0);
        if (bit_shift == 0) {
            for (size_t i = 0; i < limbs.size(); ++i) {
                res.limbs[i + word_shift] = limbs[i];
            }
        } else {
            uint64_t carry = 0;
            for (size_t i = 0; i < limbs.size(); ++i) {
                uint64_t val = (static_cast<uint64_t>(limbs[i]) << bit_shift) | carry;
                res.limbs[i + word_shift] = static_cast<uint32_t>(val);
                carry = val >> 32;
            }
            res.limbs[limbs.size() + word_shift] = static_cast<uint32_t>(carry);
        }
        res.trim();
        return res;
    }

    void shr1() {
        uint32_t carry = 0;
        for (size_t i = limbs.size(); i-- > 0;) {
            uint32_t next_carry = limbs[i] & 1U;
            limbs[i] = (limbs[i] >> 1) | (carry << 31);
            carry = next_carry;
        }
        trim();
    }

    static std::pair<BigUInt, BigUInt> divmod(const BigUInt& a, const BigUInt& b) {
        if (cmp(a, b) < 0) {
            return {BigUInt(), a};
        }
        size_t shift = a.bit_length() - b.bit_length();
        BigUInt d = b.shl(shift);
        BigUInt r = a;
        BigUInt q;
        for (size_t i = shift;; --i) {
            if (cmp(r, d) >= 0) {
                sub_inplace(r, d);
                q.set_bit(i);
            }
            if (i == 0) break;
            d.shr1();
        }
        q.trim();
        return {q, r};
    }

    static BigUInt pow_u32(uint32_t base, long long exp) {
        BigUInt res(1);
        BigUInt b(base);
        while (exp > 0) {
            if ((exp & 1LL) != 0) {
                res = mul(res, b);
            }
            exp >>= 1;
            if (exp > 0) {
                b = mul(b, b);
            }
        }
        return res;
    }

    std::string to_decimal() const {
        if (is_zero()) return "0";
        BigUInt tmp = *this;
        std::vector<uint32_t> chunks;
        while (!tmp.is_zero()) {
            chunks.push_back(tmp.divmod_u32(1000000000U));
        }
        std::string out = std::to_string(chunks.back());
        for (size_t i = chunks.size() - 1; i-- > 0;) {
            std::string part = std::to_string(chunks[i]);
            out.append(9 - part.size(), '0');
            out += part;
        }
        return out;
    }
};

bool is_ascii_digits(const std::string& s) {
    for (char c : s) {
        if (c < '0' || c > '9') return false;
    }
    return true;
}

BigUInt parse_principal(const std::string& principal) {
    size_t dot = principal.find('.');
    std::string cents_str;
    if (dot == std::string::npos) {
        if (principal.empty() || !is_ascii_digits(principal)) {
            throw std::invalid_argument("invalid principal");
        }
        cents_str = principal + "00";
    } else {
        if (principal.find('.', dot + 1) != std::string::npos) {
            throw std::invalid_argument("invalid principal");
        }
        std::string int_part = principal.substr(0, dot);
        std::string frac_part = principal.substr(dot + 1);
        if (int_part.empty() || frac_part.empty() || frac_part.size() > 2 ||
            !is_ascii_digits(int_part) || !is_ascii_digits(frac_part)) {
            throw std::invalid_argument("invalid principal");
        }
        cents_str = int_part + frac_part;
        if (frac_part.size() == 1) {
            cents_str.push_back('0');
        }
    }

    size_t first_nz = cents_str.find_first_not_of('0');
    if (first_nz == std::string::npos) {
        throw std::invalid_argument("principal must be > 0");
    }

    BigUInt val;
    size_t i = first_nz;
    while (i < cents_str.size()) {
        size_t len = std::min<size_t>(9, cents_str.size() - i);
        uint32_t chunk = 0;
        uint32_t pow10 = 1;
        for (size_t j = 0; j < len; ++j) {
            chunk = chunk * 10 + static_cast<uint32_t>(cents_str[i + j] - '0');
            pow10 *= 10;
        }
        val = val.mul_u32(pow10);
        val = BigUInt::add_u32(val, chunk);
        i += len;
    }
    return val;
}

std::pair<uint32_t, uint32_t> parse_monthly_rate(const std::string& annual_rate_pct) {
    size_t dot = annual_rate_pct.find('.');
    std::string int_part;
    std::string frac_part;
    if (dot == std::string::npos) {
        if (annual_rate_pct.empty() || !is_ascii_digits(annual_rate_pct)) {
            throw std::invalid_argument("invalid annual_rate_pct");
        }
        int_part = annual_rate_pct;
    } else {
        if (annual_rate_pct.find('.', dot + 1) != std::string::npos) {
            throw std::invalid_argument("invalid annual_rate_pct");
        }
        int_part = annual_rate_pct.substr(0, dot);
        frac_part = annual_rate_pct.substr(dot + 1);
        if (int_part.empty() || frac_part.empty() || frac_part.size() > 6 ||
            !is_ascii_digits(int_part) || !is_ascii_digits(frac_part)) {
            throw std::invalid_argument("invalid annual_rate_pct");
        }
    }

    size_t first_nz = int_part.find_first_not_of('0');
    std::string stripped_int = (first_nz == std::string::npos) ? "" : int_part.substr(first_nz);
    if (stripped_int.size() > 3) {
        throw std::invalid_argument("annual_rate_pct must be <= 100");
    }

    uint64_t int_val = 0;
    for (char c : stripped_int) {
        int_val = int_val * 10 + static_cast<uint64_t>(c - '0');
    }

    uint64_t frac_val = 0;
    for (size_t i = 0; i < 6; ++i) {
        uint64_t digit = (i < frac_part.size()) ? static_cast<uint64_t>(frac_part[i] - '0') : 0ULL;
        frac_val = frac_val * 10 + digit;
    }

    uint64_t scaled = int_val * 1000000ULL + frac_val;
    if (scaled > 100000000ULL) {
        throw std::invalid_argument("annual_rate_pct must be <= 100");
    }

    if (scaled == 0) {
        return {0U, 1U};
    }

    uint64_t denom = 1200000000ULL;
    uint64_t g = std::gcd(scaled, denom);
    return {static_cast<uint32_t>(scaled / g), static_cast<uint32_t>(denom / g)};
}

std::string format_cents(const BigUInt& cents) {
    std::string s = cents.to_decimal();
    if (s.size() == 1) return "0.0" + s;
    if (s.size() == 2) return "0." + s;
    return s.substr(0, s.size() - 2) + "." + s.substr(s.size() - 2);
}

}  // namespace

std::vector<std::tuple<std::string, std::string, std::string>> amortize(
    const std::string& principal,
    const std::string& annual_rate_pct,
    long long months) {
    BigUInt p_cents = parse_principal(principal);
    auto [u, v] = parse_monthly_rate(annual_rate_pct);
    if (months < 1 || months > 1200) {
        throw std::invalid_argument("months must be in [1, 1200]");
    }

    BigUInt pay;
    if (u == 0) {
        BigUInt num = BigUInt::add_u32(p_cents, static_cast<uint32_t>(months - 1));
        num.divmod_u32(static_cast<uint32_t>(months));
        pay = std::move(num);
    } else {
        uint32_t q = v;
        uint32_t p = v + u;
        BigUInt p_pow = BigUInt::pow_u32(p, months);
        BigUInt q_pow = BigUInt::pow_u32(q, months);
        BigUInt diff_pow = p_pow;
        BigUInt::sub_inplace(diff_pow, q_pow);

        BigUInt den = diff_pow.mul_u32(q);
        BigUInt num = BigUInt::mul(p_cents.mul_u32(u), p_pow);

        BigUInt den_minus_1 = den;
        BigUInt::sub_inplace(den_minus_1, BigUInt(1));
        BigUInt num_adj = BigUInt::add(num, den_minus_1);
        pay = BigUInt::divmod(num_adj, den).first;
    }

    std::vector<std::tuple<std::string, std::string, std::string>> result;
    result.reserve(static_cast<size_t>(months));

    BigUInt bal = std::move(p_cents);
    for (long long t = 1; t <= months; ++t) {
        BigUInt interest;
        if (u > 0) {
            BigUInt prod = bal.mul_u32(u);
            uint32_t rem = prod.divmod_u32(v);
            uint64_t twice_rem = static_cast<uint64_t>(rem) * 2ULL;
            if (twice_rem > v || (twice_rem == v && prod.is_odd())) {
                prod = BigUInt::add_u32(prod, 1);
            }
            interest = std::move(prod);
        }

        BigUInt bal_plus_int = BigUInt::add(bal, interest);
        if (t == months || BigUInt::cmp(bal_plus_int, pay) <= 0) {
            result.emplace_back(format_cents(bal_plus_int), format_cents(interest), "0.00");
            break;
        } else {
            BigUInt::sub_inplace(bal_plus_int, pay);
            bal = std::move(bal_plus_int);
            result.emplace_back(format_cents(pay), format_cents(interest), format_cents(bal));
        }
    }

    return result;
}

const PRINCIPAL_RE = /^[0-9]+(?:\.[0-9]{1,2})?$/;
const RATE_RE = /^[0-9]+(?:\.[0-9]{1,6})?$/;

function gcd(a: bigint, b: bigint): bigint {
  while (b !== 0n) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

function powBigInt(base: bigint, exp: number): bigint {
  let res = 1n;
  let b = base;
  let e = exp;
  while (e > 0) {
    if ((e & 1) === 1) {
      res *= b;
    }
    e >>= 1;
    if (e > 0) {
      b *= b;
    }
  }
  return res;
}

function roundHalfEven(num: bigint, den: bigint): bigint {
  const q = num / den;
  const r = num % den;
  const twiceR = r * 2n;
  if (twiceR > den) {
    return q + 1n;
  }
  if (twiceR < den) {
    return q;
  }
  return (q & 1n) === 1n ? q + 1n : q;
}

function formatCents(cents: bigint): string {
  const whole = cents / 100n;
  const frac = cents % 100n;
  return `${whole}.${frac.toString().padStart(2, "0")}`;
}

export function amortize(
  principal: string,
  annual_rate_pct: string,
  months: number,
): [string, string, string][] {
  if (typeof principal !== "string" || !PRINCIPAL_RE.test(principal)) {
    throw new Error("Invalid principal");
  }
  if (typeof annual_rate_pct !== "string" || !RATE_RE.test(annual_rate_pct)) {
    throw new Error("Invalid annual_rate_pct");
  }
  if (
    typeof months !== "number" ||
    !Number.isInteger(months) ||
    months < 1 ||
    months > 1200
  ) {
    throw new Error("Invalid months");
  }

  const [pInt, pFrac = ""] = principal.split(".");
  const pCents = BigInt(pInt + pFrac.padEnd(2, "0"));
  if (pCents <= 0n) {
    throw new Error("Principal must be greater than 0");
  }

  const [rInt, rFrac = ""] = annual_rate_pct.split(".");
  const rScaled = BigInt(rInt + rFrac.padEnd(6, "0"));
  if (rScaled > 100_000_000n) {
    throw new Error("Annual rate percent must be <= 100");
  }

  // Monthly rate m = a / b in lowest terms.
  let a = 0n;
  let b = 1n;
  let pay: bigint;

  if (rScaled === 0n) {
    const n = BigInt(months);
    pay = (pCents + n - 1n) / n;
  } else {
    const rawDen = 1_200_000_000n;
    const g = gcd(rScaled, rawDen);
    a = rScaled / g;
    b = rawDen / g;

    const abPowN = powBigInt(a + b, months);
    const bPowN = powBigInt(b, months);
    const num = pCents * a * abPowN;
    const den = b * (abPowN - bPowN);
    pay = (num + den - 1n) / den;
  }

  const result: [string, string, string][] = [];
  let bal = pCents;

  for (let t = 1; t <= months; t++) {
    const interest = a === 0n ? 0n : roundHalfEven(bal * a, b);
    const totalDue = bal + interest;
    if (t === months || totalDue <= pay) {
      result.push([formatCents(totalDue), formatCents(interest), "0.00"]);
      break;
    }
    bal = totalDue - pay;
    result.push([formatCents(pay), formatCents(interest), formatCents(bal)]);
  }

  return result;
}

package main

import (
	"errors"
	"math/bits"
	"strconv"
	"strings"
)

func absUint64(x int) uint64 {
	if x < 0 {
		return ^uint64(x) + 1
	}
	return uint64(x)
}

func FormatBase(p int, q int, base int, k int) (string, error) {
	if q == 0 {
		return "", errors.New("q must not be zero")
	}
	if base < 2 || base > 36 {
		return "", errors.New("base must be in 2..36")
	}
	if k < 0 {
		return "", errors.New("k must be non-negative")
	}

	if p == 0 {
		return "0", nil
	}

	neg := (p < 0) != (q < 0)
	a := absUint64(p)
	b := absUint64(q)
	ubase := uint64(base)

	intPart := a / b
	rem := a % b
	parity := intPart & 1

	initCap := k
	if initCap > 256 {
		initCap = 256
	}
	d := make([]byte, 0, initCap)

	for i := 0; i < k && rem != 0; i++ {
		hi, lo := bits.Mul64(rem, ubase)
		quo, r := bits.Div64(hi, lo, b)
		rem = r
		d = append(d, byte(quo))
		parity ^= quo & 1
	}

	if rem != 0 {
		diff := b - rem
		roundUp := false
		if rem > diff {
			roundUp = true
		} else if rem == diff {
			var odd bool
			if k == 0 {
				odd = (intPart & 1) == 1
			} else if base&1 == 0 {
				odd = (d[k-1] & 1) == 1
			} else {
				odd = parity == 1
			}
			roundUp = odd
		}

		if roundUp {
			carry := uint64(1)
			for i := len(d) - 1; i >= 0 && carry > 0; i-- {
				val := uint64(d[i]) + carry
				if val >= ubase {
					d[i] = byte(val - ubase)
					carry = 1
				} else {
					d[i] = byte(val)
					carry = 0
				}
			}
			if carry > 0 {
				intPart++
			}
		}
	}

	end := len(d)
	for end > 0 && d[end-1] == 0 {
		end--
	}
	d = d[:end]

	if intPart == 0 && len(d) == 0 {
		return "0", nil
	}

	const alphabet = "0123456789abcdefghijklmnopqrstuvwxyz"
	for i, v := range d {
		d[i] = alphabet[v]
	}

	intStr := strconv.FormatUint(intPart, base)
	extra := len(intStr)
	if neg {
		extra++
	}
	if len(d) > 0 {
		extra += 1 + len(d)
	}

	var sb strings.Builder
	sb.Grow(extra)
	if neg {
		sb.WriteByte('-')
	}
	sb.WriteString(intStr)
	if len(d) > 0 {
		sb.WriteByte('.')
		sb.Write(d)
	}
	return sb.String(), nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    private static final String DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz";

    public static String formatBase(long p, long q, long base, long k) {
        if (q == 0 || base < 2 || base > 36 || k < 0) {
            throw new IllegalArgumentException();
        }
        if (p == 0) {
            return "0";
        }

        boolean neg = (p < 0) ^ (q < 0);
        BigInteger bigNum = BigInteger.valueOf(p).abs();
        BigInteger bigDen = BigInteger.valueOf(q).abs();
        BigInteger[] qr = bigNum.divideAndRemainder(bigDen);
        BigInteger intPart = qr[0];
        long rem = qr[1].longValue();
        long den = (q < 0) ? -q : q;

        int parity = intPart.testBit(0) ? 1 : 0;
        int cap = (int) Math.min(k, 1024L);
        byte[] digits = new byte[cap];
        int len = 0;

        if (rem != 0 && k > 0) {
            boolean smallDen = Long.compareUnsigned(den, Long.MAX_VALUE / base) <= 0;
            if (smallDen) {
                for (long step = 0; step < k && rem != 0; step++) {
                    long prod = rem * base;
                    long d = prod / den;
                    rem = prod % den;
                    parity = (int) ((parity * base + d) & 1L);
                    if (len == digits.length) {
                        digits = Arrays.copyOf(digits, (int) Math.min(k, (long) digits.length * 2L));
                    }
                    digits[len++] = (byte) d;
                }
            } else {
                double dDen = (den >= 0) ? (double) den : 0x1.0p63;
                double dBase = (double) base;
                for (long step = 0; step < k && rem != 0; step++) {
                    long pLo = rem * base;
                    long pHi = Math.multiplyHigh(rem, base);

                    long d = (long) (((double) rem * dBase) / dDen);
                    if (d >= base) {
                        d = base - 1;
                    } else if (d < 0) {
                        d = 0;
                    }

                    long qLo = d * den;
                    long qHi = Math.unsignedMultiplyHigh(d, den);
                    while (qHi > pHi || (qHi == pHi && Long.compareUnsigned(qLo, pLo) > 0)) {
                        d--;
                        long prevQLo = qLo;
                        qLo -= den;
                        if (Long.compareUnsigned(prevQLo, den) < 0) {
                            qHi--;
                        }
                    }

                    long rLo = pLo - qLo;
                    long rHi = pHi - qHi - (Long.compareUnsigned(pLo, qLo) < 0 ? 1L : 0L);
                    while (rHi > 0 || Long.compareUnsigned(rLo, den) >= 0) {
                        d++;
                        long prevRLo = rLo;
                        rLo -= den;
                        if (Long.compareUnsigned(prevRLo, den) < 0) {
                            rHi--;
                        }
                    }

                    rem = rLo;
                    parity = (int) ((parity * base + d) & 1L);
                    if (len == digits.length) {
                        digits = Arrays.copyOf(digits, (int) Math.min(k, (long) digits.length * 2L));
                    }
                    digits[len++] = (byte) d;
                }
            }
        }

        boolean roundUp = false;
        if (rem != 0) {
            int cmp = Long.compareUnsigned(rem << 1, den);
            if (cmp > 0 || (cmp == 0 && parity == 1)) {
                roundUp = true;
            }
        }

        if (roundUp) {
            int i = len - 1;
            while (i >= 0 && digits[i] == base - 1) {
                digits[i] = 0;
                i--;
            }
            if (i >= 0) {
                digits[i]++;
            } else {
                intPart = intPart.add(BigInteger.ONE);
            }
        }

        while (len > 0 && digits[len - 1] == 0) {
            len--;
        }

        if (len == 0 && intPart.signum() == 0) {
            return "0";
        }

        String intStr = intPart.toString((int) base);
        if (len == 0) {
            return neg ? "-" + intStr : intStr;
        }

        StringBuilder sb = new StringBuilder((neg ? 1 : 0) + intStr.length() + 1 + len);
        if (neg) {
            sb.append('-');
        }
        sb.append(intStr).append('.');
        char[] frac = new char[len];
        for (int i = 0; i < len; i++) {
            frac[i] = DIGITS.charAt(digits[i]);
        }
        sb.append(frac);
        return sb.toString();
    }
}

#include <algorithm>
#include <cstdint>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>

namespace {

constexpr char kDigits[] = "0123456789abcdefghijklmnopqrstuvwxyz";

std::string to_base_u64(std::uint64_t v, std::uint64_t base) {
    if (v == 0) {
        return "0";
    }
    std::string s;
    while (v > 0) {
        s.push_back(kDigits[v % base]);
        v /= base;
    }
    std::reverse(s.begin(), s.end());
    return s;
}

#ifndef __SIZEOF_INT128__
std::pair<std::uint64_t, std::uint64_t> mul_u64(std::uint64_t a, std::uint64_t b) {
    std::uint64_t a0 = a & 0xffffffffULL;
    std::uint64_t a1 = a >> 32;
    std::uint64_t b0 = b & 0xffffffffULL;
    std::uint64_t b1 = b >> 32;
    std::uint64_t p00 = a0 * b0;
    std::uint64_t p01 = a0 * b1;
    std::uint64_t p10 = a1 * b0;
    std::uint64_t p11 = a1 * b1;
    std::uint64_t mid = (p00 >> 32) + (p01 & 0xffffffffULL) + (p10 & 0xffffffffULL);
    std::uint64_t lo = (p00 & 0xffffffffULL) | (mid << 32);
    std::uint64_t hi = p11 + (p01 >> 32) + (p10 >> 32) + (mid >> 32);
    return {hi, lo};
}
#endif

}  // namespace

std::string format_base(long long p, long long q, long long base, long long k) {
    if (q == 0 || base < 2 || base > 36 || k < 0) {
        throw std::invalid_argument("Invalid arguments to format_base");
    }

    if (p == 0) {
        return "0";
    }

    const bool neg = (p < 0) != (q < 0);
    const std::uint64_t ap = p < 0 ? 0ULL - static_cast<std::uint64_t>(p)
                                   : static_cast<std::uint64_t>(p);
    const std::uint64_t aq = q < 0 ? 0ULL - static_cast<std::uint64_t>(q)
                                   : static_cast<std::uint64_t>(q);
    const std::uint64_t ub = static_cast<std::uint64_t>(base);

    std::uint64_t int_part = ap / aq;
    std::uint64_t rem = ap % aq;

    if (k == 0) {
        if (2 * rem > aq || (2 * rem == aq && (int_part & 1ULL) == 1ULL)) {
            int_part += 1;
        }
        if (int_part == 0) {
            return "0";
        }
        std::string res = neg ? "-" : "";
        res += to_base_u64(int_part, ub);
        return res;
    }

    if (rem == 0) {
        std::string res = neg ? "-" : "";
        res += to_base_u64(int_part, ub);
        return res;
    }

    std::uint64_t parity = int_part & 1ULL;
    const std::uint64_t base_odd = ub & 1ULL;
    std::string frac;

    if (aq <= std::numeric_limits<std::uint64_t>::max() / ub) {
        for (long long i = 0; i < k; ++i) {
            const std::uint64_t prod = rem * ub;
            const std::uint64_t d = prod / aq;
            rem = prod - d * aq;
            frac.push_back(kDigits[d]);
            parity = (parity * base_odd + d) & 1ULL;
            if (rem == 0) {
                break;
            }
        }
    } else {
#ifdef __SIZEOF_INT128__
        using u128 = unsigned __int128;
        for (long long i = 0; i < k; ++i) {
            const u128 prod = static_cast<u128>(rem) * ub;
            const std::uint64_t d = static_cast<std::uint64_t>(prod / aq);
            rem = static_cast<std::uint64_t>(prod - static_cast<u128>(d) * aq);
            frac.push_back(kDigits[d]);
            parity = (parity * base_odd + d) & 1ULL;
            if (rem == 0) {
                break;
            }
        }
#else
        for (long long i = 0; i < k; ++i) {
            const auto prod = mul_u64(rem, ub);
            std::uint64_t lo = 0;
            std::uint64_t hi = ub - 1;
            while (lo < hi) {
                const std::uint64_t mid = lo + (hi - lo + 1) / 2;
                if (mul_u64(mid, aq) <= prod) {
                    lo = mid;
                } else {
                    hi = mid - 1;
                }
            }
            const std::uint64_t d = lo;
            const auto sub = mul_u64(d, aq);
            rem = prod.second - sub.second;
            frac.push_back(kDigits[d]);
            parity = (parity * base_odd + d) & 1ULL;
            if (rem == 0) {
                break;
            }
        }
#endif
    }

    if (rem != 0) {
        const bool round_up = (2 * rem > aq) || (2 * rem == aq && parity == 1ULL);
        if (round_up) {
            const char max_digit = kDigits[ub - 1];
            bool carry = true;
            for (std::size_t i = frac.size(); i > 0 && carry; --i) {
                char& c = frac[i - 1];
                if (c == max_digit) {
                    c = '0';
                } else if (c == '9') {
                    c = 'a';
                    carry = false;
                } else {
                    c = static_cast<char>(c + 1);
                    carry = false;
                }
            }
            if (carry) {
                int_part += 1;
            }
        }
    }

    while (!frac.empty() && frac.back() == '0') {
        frac.pop_back();
    }

    if (int_part == 0 && frac.empty()) {
        return "0";
    }

    std::string res;
    res.reserve((neg ? 1 : 0) + 64 + (frac.empty() ? 0 : 1 + frac.size()));
    if (neg) {
        res.push_back('-');
    }
    res += to_base_u64(int_part, ub);
    if (!frac.empty()) {
        res.push_back('.');
        res += frac;
    }
    return res;
}

const CHAR_CODES = new Uint8Array(36);
for (let i = 0; i < 10; i++) CHAR_CODES[i] = 48 + i;
for (let i = 10; i < 36; i++) CHAR_CODES[i] = 87 + i;

const decoder = typeof TextDecoder !== "undefined" ? new TextDecoder() : null;

export function formatBase(p: number, q: number, base: number, k: number): string {
  if (
    !Number.isInteger(p) ||
    !Number.isInteger(q) ||
    !Number.isInteger(base) ||
    !Number.isInteger(k)
  ) {
    throw new Error("All arguments must be integers");
  }
  if (q === 0) {
    throw new Error("Denominator q must not be zero");
  }
  if (base < 2 || base > 36) {
    throw new Error("Base must be between 2 and 36");
  }
  if (k < 0) {
    throw new Error("Precision k must be non-negative");
  }

  if (p === 0) {
    return "0";
  }

  const neg = (p < 0) !== (q < 0);
  let a = BigInt(p);
  if (a < 0n) a = -a;
  let b = BigInt(q);
  if (b < 0n) b = -b;

  let intPart = a / b;
  let r = a % b;

  if (k === 0 || r === 0n) {
    if (r !== 0n) {
      const diff = b - r;
      if (r > diff || (r === diff && (intPart & 1n) === 1n)) {
        intPart += 1n;
      }
    }
    if (intPart === 0n) {
      return "0";
    }
    return (neg ? "-" : "") + intPart.toString(base);
  }

  const digits = new Uint8Array(k);
  const baseOdd = (base & 1) === 1;
  let parity = baseOdd ? Number(intPart & 1n) : 0;
  let len = k;

  const maxFastB = BigInt(Math.floor(Number.MAX_SAFE_INTEGER / base));
  let roundUp = false;

  if (b <= maxFastB) {
    const bNum = Number(b);
    let rNum = Number(r);
    for (let i = 0; i < k; i++) {
      const t = rNum * base;
      let d = (t / bNum) | 0;
      let rem = t - d * bNum;
      if (rem < 0) {
        d--;
        rem += bNum;
      }
      digits[i] = d;
      if (baseOdd) {
        parity ^= d & 1;
      }
      rNum = rem;
      if (rNum === 0) {
        len = i + 1;
        break;
      }
    }
    if (rNum !== 0) {
      if (!baseOdd) {
        parity = digits[k - 1] & 1;
      }
      const diff = bNum - rNum;
      if (rNum > diff || (rNum === diff && parity === 1)) {
        roundUp = true;
      }
    }
  } else {
    const baseBig = BigInt(base);
    for (let i = 0; i < k; i++) {
      const t = r * baseBig;
      const dBig = t / b;
      const d = Number(dBig);
      digits[i] = d;
      if (baseOdd) {
        parity ^= d & 1;
      }
      r = t - dBig * b;
      if (r === 0n) {
        len = i + 1;
        break;
      }
    }
    if (r !== 0n) {
      if (!baseOdd) {
        parity = digits[k - 1] & 1;
      }
      const diff = b - r;
      if (r > diff || (r === diff && parity === 1)) {
        roundUp = true;
      }
    }
  }

  if (roundUp) {
    let carry = 1;
    for (let i = k - 1; i >= 0; i--) {
      const sum = digits[i] + 1;
      if (sum === base) {
        digits[i] = 0;
      } else {
        digits[i] = sum;
        carry = 0;
        break;
      }
    }
    if (carry === 1) {
      intPart += 1n;
    }
  }

  let lastNonZero = len - 1;
  while (lastNonZero >= 0 && digits[lastNonZero] === 0) {
    lastNonZero--;
  }

  if (lastNonZero < 0) {
    if (intPart === 0n) {
      return "0";
    }
    return (neg ? "-" : "") + intPart.toString(base);
  }

  const fracLen = lastNonZero + 1;
  for (let i = 0; i < fracLen; i++) {
    digits[i] = CHAR_CODES[digits[i]];
  }

  let fracStr: string;
  if (decoder !== null) {
    fracStr = decoder.decode(digits.subarray(0, fracLen));
  } else {
    const chunks: string[] = [];
    const CHUNK = 8192;
    for (let i = 0; i < fracLen; i += CHUNK) {
      chunks.push(
        String.fromCharCode(...digits.subarray(i, Math.min(i + CHUNK, fracLen)))
      );
    }
    fracStr = chunks.join("");
  }

  return (neg ? "-" : "") + intPart.toString(base) + "." + fracStr;
}

package main

import (
	"errors"
	"fmt"
	"math/big"
)

func formatFrac(a, b uint64, neg bool) string {
	if a == 0 {
		return "0/1"
	}
	if neg {
		return fmt.Sprintf("-%d/%d", a, b)
	}
	return fmt.Sprintf("%d/%d", a, b)
}

func ClosestFraction(x string, max_num int, max_den int) (string, error) {
	if max_num < 0 || max_den < 1 {
		return "", errors.New("invalid bounds")
	}
	n := len(x)
	if n == 0 {
		return "", errors.New("empty literal")
	}

	i := 0
	neg := false
	if x[i] == '+' {
		i++
	} else if x[i] == '-' {
		neg = true
		i++
	}

	intStart := i
	for i < n && x[i] >= '0' && x[i] <= '9' {
		i++
	}
	intLen := i - intStart

	fracStart, fracLen := 0, 0
	if i < n && x[i] == '.' {
		i++
		fracStart = i
		for i < n && x[i] >= '0' && x[i] <= '9' {
			i++
		}
		fracLen = i - fracStart
	}

	if intLen == 0 && fracLen == 0 {
		return "", errors.New("invalid mantissa")
	}

	expStart, expEnd := 0, 0
	expNeg := false
	if i < n && (x[i] == 'e' || x[i] == 'E') {
		i++
		if i < n && (x[i] == '+' || x[i] == '-') {
			if x[i] == '-' {
				expNeg = true
			}
			i++
		}
		expStart = i
		for i < n && x[i] >= '0' && x[i] <= '9' {
			i++
		}
		expEnd = i
		if expEnd == expStart {
			return "", errors.New("invalid exponent")
		}
	}

	if i != n {
		return "", errors.New("unexpected trailing characters")
	}

	digitsStr := x[intStart:intStart+intLen] + x[fracStart:fracStart+fracLen]
	nz := -1
	for idx := 0; idx < len(digitsStr); idx++ {
		if digitsStr[idx] != '0' {
			nz = idx
			break
		}
	}
	if nz == -1 || max_num == 0 {
		return "0/1", nil
	}

	M := uint64(max_num)
	D := uint64(max_den)

	capVal := int64(len(digitsStr)) + 100
	var expVal int64
	for idx := expStart; idx < expEnd; idx++ {
		if expVal < capVal {
			expVal = expVal*10 + int64(x[idx]-'0')
			if expVal > capVal {
				expVal = capVal
			}
		}
	}
	if expNeg {
		expVal = -expVal
	}

	eTop := int64(intLen) - 1 - int64(nz) + expVal
	if eTop >= 20 {
		return formatFrac(M, 1, neg), nil
	}
	if eTop <= -21 {
		return "0/1", nil
	}

	lz := len(digitsStr) - 1
	for lz > nz && digitsStr[lz] == '0' {
		lz--
	}

	trimmed := digitsStr[nz : lz+1]
	P, ok := new(big.Int).SetString(trimmed, 10)
	if !ok {
		return "", errors.New("failed to parse mantissa")
	}
	Q := big.NewInt(1)
	pow10 := expVal + int64(intLen) - 1 - int64(lz)
	if pow10 > 0 {
		P.Mul(P, new(big.Int).Exp(big.NewInt(10), big.NewInt(pow10), nil))
	} else if pow10 < 0 {
		Q.Exp(big.NewInt(10), big.NewInt(-pow10), nil)
	}

	Mbig := new(big.Int).SetUint64(M)
	if P.Cmp(new(big.Int).Mul(Mbig, Q)) >= 0 {
		return formatFrac(M, 1, neg), nil
	}

	Dbig := new(big.Int).SetUint64(D)
	twoDP := new(big.Int).Mul(Dbig, P)
	twoDP.Lsh(twoDP, 1)
	if twoDP.Cmp(Q) <= 0 {
		return "0/1", nil
	}

	kBig, rem := new(big.Int).QuoRem(P, Q, new(big.Int))
	k := kBig.Uint64()
	if rem.Sign() == 0 {
		return formatFrac(k, 1, neg), nil
	}

	a1, b1 := k, uint64(1)
	a2, b2 := k+1, uint64(1)
	delta1 := rem
	delta2 := new(big.Int).Sub(Q, rem)

	for a1 <= M-a2 && b1 <= D-b2 {
		cmp := delta2.Cmp(delta1)
		if cmp == 0 {
			return formatFrac(a1+a2, b1+b2, neg), nil
		}
		if cmp > 0 {
			tBound := (D - b2) / b1
			if a1 > 0 {
				if tb := (M - a2) / a1; tb < tBound {
					tBound = tb
				}
			}
			q, r := new(big.Int).QuoRem(delta2, delta1, new(big.Int))
			if q.IsUint64() && q.Uint64() <= tBound {
				t := q.Uint64()
				a2 += t * a1
				b2 += t * b1
				if r.Sign() == 0 {
					return formatFrac(a2, b2, neg), nil
				}
				delta2 = r
			} else {
				a2 += tBound * a1
				b2 += tBound * b1
				tmp := new(big.Int).SetUint64(tBound)
				tmp.Mul(tmp, delta1)
				delta2.Sub(delta2, tmp)
			}
		} else {
			tBound := (D - b1) / b2
			if tb := (M - a1) / a2; tb < tBound {
				tBound = tb
			}
			q, r := new(big.Int).QuoRem(delta1, delta2, new(big.Int))
			if q.IsUint64() && q.Uint64() <= tBound {
				t := q.Uint64()
				a1 += t * a2
				b1 += t * b2
				if r.Sign() == 0 {
					return formatFrac(a1, b1, neg), nil
				}
				delta1 = r
			} else {
				a1 += tBound * a2
				b1 += tBound * b2
				tmp := new(big.Int).SetUint64(tBound)
				tmp.Mul(tmp, delta2)
				delta1.Sub(delta1, tmp)
			}
		}
	}

	lhs := new(big.Int).Mul(delta1, new(big.Int).SetUint64(b2))
	rhs := new(big.Int).Mul(delta2, new(big.Int).SetUint64(b1))
	c := lhs.Cmp(rhs)
	if c < 0 {
		return formatFrac(a1, b1, neg), nil
	}
	if c > 0 {
		return formatFrac(a2, b2, neg), nil
	}
	if b1 < b2 {
		return formatFrac(a1, b1, neg), nil
	}
	if b2 < b1 {
		return formatFrac(a2, b2, neg), nil
	}
	return formatFrac(a1, b1, neg), nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public static String closestFraction(String x, long max_num, long max_den) {
        if (x == null || max_num < 0 || max_den < 1) {
            throw new IllegalArgumentException("Invalid arguments");
        }

        int n = x.length();
        int idx = 0;

        boolean negative = false;
        if (idx < n && (x.charAt(idx) == '+' || x.charAt(idx) == '-')) {
            negative = (x.charAt(idx) == '-');
            idx++;
        }

        int intStart = idx;
        while (idx < n && isAsciiDigit(x.charAt(idx))) {
            idx++;
        }
        int intLen = idx - intStart;

        int fracStart = idx;
        int fracLen = 0;
        if (idx < n && x.charAt(idx) == '.') {
            idx++;
            fracStart = idx;
            while (idx < n && isAsciiDigit(x.charAt(idx))) {
                idx++;
            }
            fracLen = idx - fracStart;
        }

        if (intLen == 0 && fracLen == 0) {
            throw new IllegalArgumentException("Invalid decimal literal: " + x);
        }

        long exp = 0;
        if (idx < n && (x.charAt(idx) == 'e' || x.charAt(idx) == 'E')) {
            idx++;
            boolean expNeg = false;
            if (idx < n && (x.charAt(idx) == '+' || x.charAt(idx) == '-')) {
                expNeg = (x.charAt(idx) == '-');
                idx++;
            }
            int expStart = idx;
            while (idx < n && isAsciiDigit(x.charAt(idx))) {
                if (exp < 1_000_000_000L) {
                    exp = exp * 10 + (x.charAt(idx) - '0');
                }
                idx++;
            }
            if (idx == expStart) {
                throw new IllegalArgumentException("Invalid exponent in literal: " + x);
            }
            if (expNeg) {
                exp = -exp;
            }
        }

        if (idx != n) {
            throw new IllegalArgumentException("Invalid decimal literal: " + x);
        }

        StringBuilder digits = new StringBuilder(intLen + fracLen);
        digits.append(x, intStart, intStart + intLen);
        digits.append(x, fracStart, fracStart + fracLen);

        int firstNonZero = 0;
        while (firstNonZero < digits.length() && digits.charAt(firstNonZero) == '0') {
            firstNonZero++;
        }
        if (firstNonZero == digits.length() || max_num == 0) {
            return "0/1";
        }

        int lastNonZero = digits.length() - 1;
        while (digits.charAt(lastNonZero) == '0') {
            lastNonZero--;
        }

        int trailZeros = (digits.length() - 1) - lastNonZero;
        String d = digits.substring(firstNonZero, lastNonZero + 1);
        long pow10 = exp - fracLen + trailZeros;
        long msdExp = pow10 + d.length() - 1;

        if (msdExp >= 19) {
            return format(negative, max_num, 1);
        }
        if (msdExp <= -21) {
            return "0/1";
        }

        BigInteger P;
        BigInteger Q;
        if (pow10 >= 0) {
            P = new BigInteger(d).multiply(BigInteger.TEN.pow((int) pow10));
            Q = BigInteger.ONE;
        } else {
            P = new BigInteger(d);
            Q = BigInteger.TEN.pow((int) (-pow10));
            BigInteger g = P.gcd(Q);
            P = P.divide(g);
            Q = Q.divide(g);
        }

        if (P.compareTo(Q.multiply(BigInteger.valueOf(max_num))) >= 0) {
            return format(negative, max_num, 1);
        }

        BigInteger[] qr = P.divideAndRemainder(Q);
        long k = qr[0].longValueExact();
        if (qr[1].signum() == 0) {
            return format(negative, k, 1);
        }

        long p1 = k;
        long q1 = 1;
        long p2 = k + 1;
        long q2 = 1;

        while (p1 <= max_num - p2 && q1 <= max_den - q2) {
            long pm = p1 + p2;
            long qm = q1 + q2;
            int cmp = Q.multiply(BigInteger.valueOf(pm)).compareTo(P.multiply(BigInteger.valueOf(qm)));
            if (cmp == 0) {
                return format(negative, pm, qm);
            }
            if (cmp < 0) {
                long tBound = Math.min((max_num - p1) / p2, (max_den - q1) / q2);
                BigInteger num = P.multiply(BigInteger.valueOf(q1)).subtract(Q.multiply(BigInteger.valueOf(p1)));
                BigInteger den = Q.multiply(BigInteger.valueOf(p2)).subtract(P.multiply(BigInteger.valueOf(q2)));
                BigInteger[] divRem = num.divideAndRemainder(den);
                int cmpBound = divRem[0].compareTo(BigInteger.valueOf(tBound));
                long t = cmpBound >= 0 ? tBound : divRem[0].longValueExact();
                p1 += t * p2;
                q1 += t * q2;
                if (cmpBound <= 0 && divRem[1].signum() == 0) {
                    return format(negative, p1, q1);
                }
            } else {
                long tBound = (max_den - q2) / q1;
                if (p1 > 0) {
                    tBound = Math.min(tBound, (max_num - p2) / p1);
                }
                BigInteger num = Q.multiply(BigInteger.valueOf(p2)).subtract(P.multiply(BigInteger.valueOf(q2)));
                BigInteger den = P.multiply(BigInteger.valueOf(q1)).subtract(Q.multiply(BigInteger.valueOf(p1)));
                BigInteger[] divRem = num.divideAndRemainder(den);
                int cmpBound = divRem[0].compareTo(BigInteger.valueOf(tBound));
                long t = cmpBound >= 0 ? tBound : divRem[0].longValueExact();
                p2 += t * p1;
                q2 += t * q1;
                if (cmpBound <= 0 && divRem[1].signum() == 0) {
                    return format(negative, p2, q2);
                }
            }
        }

        BigInteger lhs = P.multiply(BigInteger.valueOf(q1))
                .subtract(Q.multiply(BigInteger.valueOf(p1)))
                .multiply(BigInteger.valueOf(q2));
        BigInteger rhs = Q.multiply(BigInteger.valueOf(p2))
                .subtract(P.multiply(BigInteger.valueOf(q2)))
                .multiply(BigInteger.valueOf(q1));

        int cmp = lhs.compareTo(rhs);
        if (cmp < 0) {
            return format(negative, p1, q1);
        } else if (cmp > 0) {
            return format(negative, p2, q2);
        } else {
            if (q1 <= q2) {
                return format(negative, p1, q1);
            } else {
                return format(negative, p2, q2);
            }
        }
    }

    private static boolean isAsciiDigit(char c) {
        return c >= '0' && c <= '9';
    }

    private static String format(boolean negative, long a, long b) {
        if (a == 0) {
            return "0/1";
        }
        return (negative ? "-" : "") + a + "/" + b;
    }
}

#include <algorithm>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace {

struct BigInt {
    static constexpr uint64_t BASE = 1000000000ULL;
    std::vector<uint32_t> limbs;  // little-endian base 10^9

    BigInt() = default;

    explicit BigInt(uint64_t v) {
        while (v > 0) {
            limbs.push_back(static_cast<uint32_t>(v % BASE));
            v /= BASE;
        }
    }

    void trim() {
        while (!limbs.empty() && limbs.back() == 0) {
            limbs.pop_back();
        }
    }

    bool is_zero() const {
        return limbs.empty();
    }

    int cmp(const BigInt& o) const {
        if (limbs.size() != o.limbs.size()) {
            return limbs.size() < o.limbs.size() ? -1 : 1;
        }
        for (size_t i = limbs.size(); i-- > 0;) {
            if (limbs[i] != o.limbs[i]) {
                return limbs[i] < o.limbs[i] ? -1 : 1;
            }
        }
        return 0;
    }

    uint64_t to_u64() const {
        uint64_t res = 0;
        for (size_t i = limbs.size(); i-- > 0;) {
            res = res * BASE + limbs[i];
        }
        return res;
    }

    BigInt sub(const BigInt& b) const {
        BigInt res = *this;
        int64_t borrow = 0;
        for (size_t i = 0; i < res.limbs.size(); ++i) {
            int64_t cur = static_cast<int64_t>(res.limbs[i]) -
                          (i < b.limbs.size() ? static_cast<int64_t>(b.limbs[i]) : 0) -
                          borrow;
            if (cur < 0) {
                cur += static_cast<int64_t>(BASE);
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.limbs[i] = static_cast<uint32_t>(cur);
        }
        res.trim();
        return res;
    }

    static BigInt from_digits(const std::string& s) {
        BigInt res;
        for (size_t end = s.size(); end > 0;) {
            size_t start = end > 9 ? end - 9 : 0;
            uint32_t val = 0;
            for (size_t j = start; j < end; ++j) {
                val = val * 10 + static_cast<uint32_t>(s[j] - '0');
            }
            res.limbs.push_back(val);
            end = start;
        }
        res.trim();
        return res;
    }

    static BigInt pow10(size_t k) {
        BigInt res;
        size_t z = k / 9;
        size_t rem = k % 9;
        res.limbs.assign(z + 1, 0);
        uint32_t p = 1;
        for (size_t i = 0; i < rem; ++i) {
            p *= 10;
        }
        res.limbs[z] = p;
        return res;
    }

    static BigInt mul_u32(const BigInt& a, uint32_t d) {
        if (a.is_zero() || d == 0) {
            return BigInt();
        }
        BigInt res;
        res.limbs.resize(a.limbs.size());
        uint64_t carry = 0;
        for (size_t i = 0; i < a.limbs.size(); ++i) {
            uint64_t cur = static_cast<uint64_t>(a.limbs[i]) * d + carry;
            res.limbs[i] = static_cast<uint32_t>(cur % BASE);
            carry = cur / BASE;
        }
        if (carry > 0) {
            res.limbs.push_back(static_cast<uint32_t>(carry));
        }
        return res;
    }

    static BigInt mul_u64(const BigInt& a, uint64_t x) {
        if (a.is_zero() || x == 0) {
            return BigInt();
        }
        BigInt res;
        size_t shift = 0;
        while (x > 0) {
            uint64_t d = x % BASE;
            x /= BASE;
            if (d > 0) {
                size_t needed = a.limbs.size() + shift;
                if (res.limbs.size() < needed) {
                    res.limbs.resize(needed, 0);
                }
                uint64_t carry = 0;
                for (size_t i = 0; i < a.limbs.size(); ++i) {
                    uint64_t cur = res.limbs[i + shift] +
                                   static_cast<uint64_t>(a.limbs[i]) * d + carry;
                    res.limbs[i + shift] = static_cast<uint32_t>(cur % BASE);
                    carry = cur / BASE;
                }
                size_t idx = a.limbs.size() + shift;
                while (carry > 0) {
                    if (idx >= res.limbs.size()) {
                        res.limbs.push_back(0);
                    }
                    uint64_t cur = res.limbs[idx] + carry;
                    res.limbs[idx] = static_cast<uint32_t>(cur % BASE);
                    carry = cur / BASE;
                    ++idx;
                }
            }
            ++shift;
        }
        res.trim();
        return res;
    }

    static std::pair<BigInt, BigInt> divmod(const BigInt& a, const BigInt& b) {
        if (a.cmp(b) < 0) {
            return {BigInt(), a};
        }
        if (b.limbs.size() == 1) {
            uint64_t d = b.limbs[0];
            BigInt q;
            q.limbs.resize(a.limbs.size(), 0);
            uint64_t rem = 0;
            for (size_t i = a.limbs.size(); i-- > 0;) {
                uint64_t cur = rem * BASE + a.limbs[i];
                q.limbs[i] = static_cast<uint32_t>(cur / d);
                rem = cur % d;
            }
            q.trim();
            return {std::move(q), BigInt(rem)};
        }

        size_t m = b.limbs.size();
        uint64_t hi_b = b.limbs[m - 1];
        BigInt q;
        q.limbs.resize(a.limbs.size(), 0);
        BigInt rem;
        for (size_t i = a.limbs.size(); i-- > 0;) {
            if (!rem.is_zero()) {
                rem.limbs.insert(rem.limbs.begin(), a.limbs[i]);
            } else if (a.limbs[i] != 0) {
                rem.limbs.push_back(a.limbs[i]);
            }
            if (rem.cmp(b) < 0) {
                continue;
            }
            uint64_t hi_rem = rem.limbs.size() > m
                                  ? static_cast<uint64_t>(rem.limbs[m]) * BASE + rem.limbs[m - 1]
                                  : static_cast<uint64_t>(rem.limbs[m - 1]);
            uint64_t lo = hi_rem / (hi_b + 1);
            uint64_t hi = std::min<uint64_t>(BASE - 1, hi_rem / hi_b);
            uint64_t best = lo;
            BigInt best_prod;
            bool have_best = false;
            while (lo <= hi) {
                uint64_t mid = lo + (hi - lo) / 2;
                BigInt prod = mul_u32(b, static_cast<uint32_t>(mid));
                int c = prod.cmp(rem);
                if (c <= 0) {
                    best = mid;
                    best_prod = std::move(prod);
                    have_best = true;
                    lo = mid + 1;
                } else {
                    if (mid == 0) {
                        break;
                    }
                    hi = mid - 1;
                }
            }
            if (!have_best) {
                best_prod = mul_u32(b, static_cast<uint32_t>(best));
            }
            rem = rem.sub(best_prod);
            q.limbs[i] = static_cast<uint32_t>(best);
        }
        q.trim();
        return {std::move(q), std::move(rem)};
    }
};

}  // namespace

std::string closest_fraction(const std::string& x, long long max_num, long long max_den) {
    if (max_num < 0 || max_den < 1) {
        throw std::invalid_argument("Invalid fraction bounds");
    }

    const size_t n = x.size();
    size_t i = 0;

    bool neg = false;
    if (i < n && (x[i] == '+' || x[i] == '-')) {
        neg = (x[i] == '-');
        ++i;
    }

    std::string digits;
    digits.reserve(n);
    size_t int_digits = 0;
    size_t frac_digits = 0;

    while (i < n && x[i] >= '0' && x[i] <= '9') {
        digits.push_back(x[i]);
        ++int_digits;
        ++i;
    }
    if (i < n && x[i] == '.') {
        ++i;
        while (i < n && x[i] >= '0' && x[i] <= '9') {
            digits.push_back(x[i]);
            ++frac_digits;
            ++i;
        }
    }
    if (int_digits + frac_digits == 0) {
        throw std::invalid_argument("Invalid decimal literal");
    }

    long long exp_val = 0;
    if (i < n && (x[i] == 'e' || x[i] == 'E')) {
        ++i;
        bool exp_neg = false;
        if (i < n && (x[i] == '+' || x[i] == '-')) {
            exp_neg = (x[i] == '-');
            ++i;
        }
        if (i >= n || x[i] < '0' || x[i] > '9') {
            throw std::invalid_argument("Invalid exponent");
        }
        long long exp_abs = 0;
        constexpr long long EXP_CAP = 1000000000LL;
        while (i < n && x[i] >= '0' && x[i] <= '9') {
            if (exp_abs < EXP_CAP) {
                exp_abs = exp_abs * 10 + (x[i] - '0');
            }
            ++i;
        }
        exp_val = exp_neg ? -exp_abs : exp_abs;
    }

    if (i != n) {
        throw std::invalid_argument("Invalid decimal literal");
    }

    if (max_num == 0) {
        return "0/1";
    }

    size_t first_nz = 0;
    while (first_nz < digits.size() && digits[first_nz] == '0') {
        ++first_nz;
    }
    if (first_nz == digits.size()) {
        return "0/1";
    }
    size_t last_nz = digits.size();
    while (last_nz > first_nz && digits[last_nz - 1] == '0') {
        --last_nz;
    }

    size_t trailing_zeros = digits.size() - last_nz;
    digits = digits.substr(first_nz, last_nz - first_nz);

    long long E = exp_val - static_cast<long long>(frac_digits) +
                  static_cast<long long>(trailing_zeros);
    long long D = static_cast<long long>(digits.size());

    uint64_t M = static_cast<uint64_t>(max_num);
    uint64_t N = static_cast<uint64_t>(max_den);

    auto fmt = [&](uint64_t num, uint64_t den) -> std::string {
        if (num == 0) {
            return "0/1";
        }
        return (neg ? "-" : "") + std::to_string(num) + "/" + std::to_string(den);
    };

    if (D - 1 + E >= 19) {
        return fmt(M, 1);
    }
    if (D + E <= -19) {
        return "0/1";
    }

    if (E >= 0) {
        uint64_t P = 0;
        for (char c : digits) {
            P = P * 10 + static_cast<uint64_t>(c - '0');
        }
        for (long long k = 0; k < E; ++k) {
            P *= 10;
        }
        return fmt(std::min(P, M), 1);
    }

    size_t K = static_cast<size_t>(-E);
    BigInt A = BigInt::from_digits(digits);
    BigInt B = BigInt::pow10(K);
    BigInt MQ = BigInt::mul_u64(B, M);
    if (A.cmp(MQ) >= 0) {
        return fmt(M, 1);
    }

    uint64_t pL = 0, qL = 1;
    uint64_t pR = 1, qR = 0;

    while (true) {
        if (pL + pR > M || qL + qR > N) {
            break;
        }
        int c = A.cmp(B);
        if (c == 0) {
            return fmt(pL + pR, qL + qR);
        }
        if (c > 0) {
            uint64_t t_bound = (M - pL) / pR;
            if (qR > 0) {
                t_bound = std::min(t_bound, (N - qL) / qR);
            }
            auto [q, r] = BigInt::divmod(A, B);
            BigInt tb(t_bound);
            if (q.cmp(tb) <= 0) {
                uint64_t t = q.to_u64();
                pL += t * pR;
                qL += t * qR;
                if (r.is_zero()) {
                    return fmt(pL, qL);
                }
                A = std::move(r);
            } else {
                pL += t_bound * pR;
                qL += t_bound * qR;
                A = A.sub(BigInt::mul_u64(B, t_bound));
            }
        } else {
            uint64_t t_bound = (N - qR) / qL;
            if (pL > 0) {
                t_bound = std::min(t_bound, (M - pR) / pL);
            }
            auto [q, r] = BigInt::divmod(B, A);
            BigInt tb(t_bound);
            if (q.cmp(tb) <= 0) {
                uint64_t t = q.to_u64();
                pR += t * pL;
                qR += t * qL;
                if (r.is_zero()) {
                    return fmt(pR, qR);
                }
                B = std::move(r);
            } else {
                pR += t_bound * pL;
                qR += t_bound * qL;
                B = B.sub(BigInt::mul_u64(A, t_bound));
            }
        }
    }

    BigInt dL = BigInt::mul_u64(A, qR);
    BigInt dR = BigInt::mul_u64(B, qL);
    int dc = dL.cmp(dR);
    if (dc < 0) {
        return fmt(pL, qL);
    }
    if (dc > 0) {
        return fmt(pR, qR);
    }
    if (qL <= qR) {
        return fmt(pL, qL);
    }
    return fmt(pR, qR);
}

export function closestFraction(x: string, max_num: number, max_den: number): string {
  if (
    typeof x !== "string" ||
    typeof max_num !== "number" ||
    !Number.isInteger(max_num) ||
    max_num < 0 ||
    typeof max_den !== "number" ||
    !Number.isInteger(max_den) ||
    max_den < 1
  ) {
    throw new Error("Invalid arguments");
  }

  const match = /^([+-])?(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?$/.exec(x);
  if (!match) {
    throw new Error("Invalid decimal literal");
  }

  const neg = match[1] === "-";
  const intPart = match[2] ?? "";
  const fracPart = match[3] ?? match[4] ?? "";
  const expVal = match[5] ? parseInt(match[5], 10) : 0;

  const digits = intPart + fracPart;
  let firstNonZero = 0;
  while (firstNonZero < digits.length && digits[firstNonZero] === "0") {
    firstNonZero++;
  }
  if (firstNonZero === digits.length) {
    return "0/1";
  }

  let lastNonZero = digits.length - 1;
  while (lastNonZero > firstNonZero && digits[lastNonZero] === "0") {
    lastNonZero--;
  }

  const stripped = digits.slice(firstNonZero, lastNonZero + 1);
  const trailingZeros = digits.length - 1 - lastNonZero;
  const effExp = expVal - fracPart.length + trailingZeros;

  let P: bigint;
  let Q: bigint;
  if (effExp >= 0) {
    P = BigInt(stripped) * (10n ** BigInt(effExp));
    Q = 1n;
  } else {
    P = BigInt(stripped);
    Q = 10n ** BigInt(-effExp);
  }

  const M = BigInt(max_num);
  const D = BigInt(max_den);

  if (P >= M * Q) {
    return formatFrac(neg, M, 1n);
  }

  // Stern-Brocot search for adjacent bounds p1/q1 < P/Q < p2/q2
  // subject to numerators <= M and denominators <= D.
  let p1 = 0n;
  let q1 = 1n;
  let p2 = 1n;
  let q2 = 0n;

  while (true) {
    const mp = p1 + p2;
    const mq = q1 + q2;
    if (mp > M || mq > D) {
      break;
    }

    const lhs = P * mq;
    const rhs = Q * mp;
    if (lhs === rhs) {
      return formatFrac(neg, mp, mq);
    }

    if (lhs < rhs) {
      // Go left: update right bound p2/q2 -> (p2 + k*p1)/(q2 + k*q1)
      const num = Q * p2 - P * q2;
      const den = P * q1 - Q * p1;
      let k = num / den;
      const kDen = (D - q2) / q1;
      if (kDen < k) {
        k = kDen;
      }
      if (p1 > 0n) {
        const kNum = (M - p2) / p1;
        if (kNum < k) {
          k = kNum;
        }
      }
      p2 += k * p1;
      q2 += k * q1;
      if (P * q2 === Q * p2) {
        return formatFrac(neg, p2, q2);
      }
    } else {
      // Go right: update left bound p1/q1 -> (p1 + k*p2)/(q1 + k*q2)
      const num = P * q1 - Q * p1;
      const den = Q * p2 - P * q2;
      let k = num / den;
      const kNum = (M - p1) / p2;
      if (kNum < k) {
        k = kNum;
      }
      if (q2 > 0n) {
        const kDen = (D - q1) / q2;
        if (kDen < k) {
          k = kDen;
        }
      }
      p1 += k * p2;
      q1 += k * q2;
      if (P * q1 === Q * p1) {
        return formatFrac(neg, p1, q1);
      }
    }
  }

  if (q2 === 0n) {
    return formatFrac(neg, p1, q1);
  }

  const leftDiff = (P * q1 - Q * p1) * q2;
  const rightDiff = (Q * p2 - P * q2) * q1;

  if (leftDiff < rightDiff) {
    return formatFrac(neg, p1, q1);
  }
  if (rightDiff < leftDiff) {
    return formatFrac(neg, p2, q2);
  }
  if (q1 <= q2) {
    return formatFrac(neg, p1, q1);
  }
  return formatFrac(neg, p2, q2);
}

function formatFrac(neg: boolean, num: bigint, den: bigint): string {
  if (num === 0n) {
    return "0/1";
  }
  return `${neg ? "-" : ""}${num}/${den}`;
}

import re

_LITERAL_RE = re.compile(
    r'([+-]?)'
    r'(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))'
    r'(?:[eE]([+-]?[0-9]+))?'
)

_FIVE_25 = 5 ** 25
_LIMIT_Q = 65520 * (1 << 25)


def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a str")
    m = _LITERAL_RE.fullmatch(s)
    if m is None:
        raise ValueError("Invalid decimal literal")

    sign_bit = 0x8000 if m.group(1) == '-' else 0

    int_part = m.group(2) or ""
    frac_part = m.group(3) if m.group(3) is not None else (m.group(4) or "")

    int_nz = int_part.lstrip('0')
    if int_nz:
        pos = len(int_nz) - 1
        frac_nz = None
    else:
        frac_nz = frac_part.lstrip('0')
        if not frac_nz:
            return sign_bit
        pos = -(len(frac_part) - len(frac_nz) + 1)

    exp_str = m.group(5)
    if exp_str is None:
        exp = 0
    else:
        exp_neg = exp_str[0] == '-'
        exp_digits = (exp_str[1:] if exp_str[0] in '+-' else exp_str).lstrip('0')
        if not exp_digits:
            exp = 0
        elif len(exp_digits) > 7:
            return sign_bit if exp_neg else (sign_bit | 0x7C00)
        else:
            exp = -int(exp_digits) if exp_neg else int(exp_digits)

    p = exp + pos
    if p >= 5:
        return sign_bit | 0x7C00
    if p <= -9:
        return sign_bit

    # Extract all digits with place value >= 10**-25 and track any non-zero tail.
    n_keep = p + 26
    if int_nz:
        if len(int_nz) >= n_keep:
            kept_digits = int_nz[:n_keep]
            has_tail = bool(int_nz[n_keep:].strip('0')) or bool(frac_part.strip('0'))
        else:
            need = n_keep - len(int_nz)
            frac_take = frac_part[:need]
            kept_digits = int_nz + frac_take + '0' * (need - len(frac_take))
            has_tail = bool(frac_part[need:].strip('0'))
    else:
        kept_digits = frac_nz[:n_keep]
        if len(frac_nz) < n_keep:
            kept_digits += '0' * (n_keep - len(frac_nz))
            has_tail = False
        else:
            has_tail = bool(frac_nz[n_keep:].strip('0'))

    # v * 2**25 = q + (r + tail) / 5**25
    v_int = int(kept_digits)
    q, r = divmod(v_int, _FIVE_25)
    sticky = (r != 0) or has_tail

    if q >= _LIMIT_Q:
        return sign_bit | 0x7C00

    if q < 2048:
        f_full = q >> 1
        if (q & 1) and (sticky or (f_full & 1)):
            f_full += 1
        return sign_bit | f_full

    e = q.bit_length() - 11
    f_full = q >> e
    rem = q & ((1 << e) - 1)
    half = 1 << (e - 1)
    if rem > half or (rem == half and (sticky or (f_full & 1))):
        f_full += 1
    if f_full == 2048:
        return sign_bit | ((e + 1) << 10)
    return sign_bit | (e << 10) | (f_full - 1024)

package main

import (
	"errors"
	"math/bits"
)

var errInvalidLiteral = errors.New("invalid decimal literal")

const fivePow25 uint64 = 298023223876953125

func DecimalToHalfBits(s string) (int, error) {
	n := len(s)
	if n == 0 {
		return 0, errInvalidLiteral
	}

	i := 0
	signBit := 0
	if s[i] == '+' {
		i++
	} else if s[i] == '-' {
		signBit = 0x8000
		i++
	}

	intStart := i
	for i < n && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	intEnd := i

	fracStart, fracEnd := i, i
	if i < n && s[i] == '.' {
		i++
		fracStart = i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		fracEnd = i
	}

	intLen := intEnd - intStart
	fracLen := fracEnd - fracStart
	totalDigits := intLen + fracLen
	if totalDigits == 0 {
		return 0, errInvalidLiteral
	}

	expVal := 0
	if i < n {
		if s[i] != 'e' && s[i] != 'E' {
			return 0, errInvalidLiteral
		}
		i++
		if i >= n {
			return 0, errInvalidLiteral
		}
		expSign := 1
		if s[i] == '+' {
			i++
		} else if s[i] == '-' {
			expSign = -1
			i++
		}
		if i >= n {
			return 0, errInvalidLiteral
		}
		expCap := n + 100
		for i < n {
			c := s[i]
			if c < '0' || c > '9' {
				return 0, errInvalidLiteral
			}
			if expVal < expCap {
				expVal = expVal*10 + int(c-'0')
			}
			i++
		}
		expVal *= expSign
	}

	digitAt := func(k int) byte {
		if k < intLen {
			return s[intStart+k]
		}
		return s[fracStart+(k-intLen)]
	}

	firstNZ := -1
	for k := 0; k < totalDigits; k++ {
		if digitAt(k) != '0' {
			firstNZ = k
			break
		}
	}
	if firstNZ == -1 {
		return signBit, nil
	}

	lastNZ := firstNZ
	for k := totalDigits - 1; k > firstNZ; k-- {
		if digitAt(k) != '0' {
			lastNZ = k
			break
		}
	}

	p := (intLen - 1 - firstNZ) + expVal
	if p >= 5 {
		return signBit | 0x7C00, nil
	}
	if p <= -9 {
		return signBit, nil
	}

	m := lastNZ - firstNZ + 1
	numDigitsNeeded := p + 26
	hasMore := m > numDigitsNeeded
	take := numDigitsNeeded
	if m < take {
		take = m
	}

	var hi, lo uint64
	for k := 0; k < take; k++ {
		d := uint64(digitAt(firstNZ+k) - '0')
		c1, l1 := bits.Mul64(lo, 10)
		h1 := hi*10 + c1
		var c2 uint64
		lo, c2 = bits.Add64(l1, d, 0)
		hi = h1 + c2
	}
	for k := take; k < numDigitsNeeded; k++ {
		c1, l1 := bits.Mul64(lo, 10)
		hi = hi*10 + c1
		lo = l1
	}

	q, rem := bits.Div64(hi, lo, fivePow25)
	if q >= 65520<<25 {
		return signBit | 0x7C00, nil
	}

	sticky := rem != 0 || hasMore
	var pattern int
	var r, half uint64
	if q < 2048 {
		pattern = int(q >> 1)
		r = q & 1
		half = 1
	} else {
		e := bits.Len64(q) - 11
		f := (q >> e) - 1024
		pattern = (e << 10) | int(f)
		r = q & ((uint64(1) << e) - 1)
		half = uint64(1) << (e - 1)
	}
	if r > half || (r == half && (sticky || (pattern&1) == 1)) {
		pattern++
	}
	return signBit | pattern, nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    private static final BigInteger POW5_25 = BigInteger.valueOf(298023223876953125L);
    private static final BigInteger LIMIT_INF = BigInteger.TEN.pow(25).shiftLeft(16);

    public static long decimalToHalfBits(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Invalid decimal literal");
        }

        final int n = s.length();
        int idx = 0;

        boolean neg = false;
        char first = s.charAt(idx);
        if (first == '+' || first == '-') {
            neg = (first == '-');
            idx++;
        }

        int intStart = idx;
        while (idx < n) {
            char c = s.charAt(idx);
            if (c < '0' || c > '9') {
                break;
            }
            idx++;
        }
        int intEnd = idx;

        int fracStart = idx;
        int fracEnd = idx;
        if (idx < n && s.charAt(idx) == '.') {
            idx++;
            fracStart = idx;
            while (idx < n) {
                char c = s.charAt(idx);
                if (c < '0' || c > '9') {
                    break;
                }
                idx++;
            }
            fracEnd = idx;
        }

        int intLen = intEnd - intStart;
        int fracLen = fracEnd - fracStart;
        if (intLen == 0 && fracLen == 0) {
            throw new IllegalArgumentException("Invalid decimal literal");
        }

        long exp = 0;
        boolean expOverflowPos = false;
        boolean expOverflowNeg = false;
        if (idx < n && (s.charAt(idx) == 'e' || s.charAt(idx) == 'E')) {
            idx++;
            boolean expNeg = false;
            if (idx < n && (s.charAt(idx) == '+' || s.charAt(idx) == '-')) {
                expNeg = (s.charAt(idx) == '-');
                idx++;
            }
            int expStart = idx;
            while (idx < n) {
                char c = s.charAt(idx);
                if (c < '0' || c > '9') {
                    break;
                }
                if (exp <= 1_000_000L) {
                    exp = exp * 10 + (c - '0');
                }
                idx++;
            }
            if (idx == expStart) {
                throw new IllegalArgumentException("Invalid decimal literal");
            }
            if (exp > 1_000_000L) {
                if (expNeg) {
                    expOverflowNeg = true;
                } else {
                    expOverflowPos = true;
                }
            } else if (expNeg) {
                exp = -exp;
            }
        }

        if (idx != n) {
            throw new IllegalArgumentException("Invalid decimal literal");
        }

        // Find the first non-zero digit in the mantissa.
        boolean inFrac = false;
        int nzPos = -1;
        long p0 = 0;
        for (int i = intStart; i < intEnd; i++) {
            if (s.charAt(i) != '0') {
                nzPos = i;
                p0 = (long) (intEnd - 1 - i);
                break;
            }
        }
        if (nzPos == -1) {
            inFrac = true;
            for (int i = fracStart; i < fracEnd; i++) {
                if (s.charAt(i) != '0') {
                    nzPos = i;
                    p0 = (long) (-1 - (i - fracStart));
                    break;
                }
            }
        }

        if (nzPos == -1) {
            return neg ? 0x8000L : 0L;
        }

        if (expOverflowPos) {
            return neg ? 0xFC00L : 0x7C00L;
        }
        if (expOverflowNeg) {
            return neg ? 0x8000L : 0L;
        }

        long p = p0 + exp;
        if (p >= 5) {
            return neg ? 0xFC00L : 0x7C00L;
        }
        if (p <= -9) {
            return neg ? 0x8000L : 0L;
        }

        // Collect digits from 10^p down to 10^-25 into buf, and track any non-zero digit beyond 10^-25.
        char[] buf = new char[(int) (p + 26)];
        Arrays.fill(buf, '0');
        int bufIdx = 0;
        boolean hasExtra = false;

        if (!inFrac) {
            for (int i = nzPos; i < intEnd; i++) {
                char c = s.charAt(i);
                if (bufIdx < buf.length) {
                    buf[bufIdx++] = c;
                } else if (c != '0') {
                    hasExtra = true;
                    break;
                }
            }
            nzPos = fracStart;
        }
        if (!hasExtra) {
            for (int i = nzPos; i < fracEnd; i++) {
                char c = s.charAt(i);
                if (bufIdx < buf.length) {
                    buf[bufIdx++] = c;
                } else if (c != '0') {
                    hasExtra = true;
                    break;
                }
            }
        }

        BigInteger vInt = new BigInteger(new String(buf));
        if (vInt.compareTo(LIMIT_INF) >= 0) {
            return neg ? 0xFC00L : 0x7C00L;
        }

        BigInteger[] qr = vInt.divideAndRemainder(POW5_25);
        long k = qr[0].longValue();
        boolean remNonZero = qr[1].signum() != 0 || hasExtra;

        int e;
        int shiftBits;
        if (k < (1L << 11)) {
            e = 0;
            shiftBits = 1;
        } else {
            int bitLen = Long.SIZE - Long.numberOfLeadingZeros(k);
            e = bitLen - 11;
            shiftBits = e;
        }

        long q = k >>> shiftBits;
        long kLow = k & ((1L << shiftBits) - 1);
        long halfK = 1L << (shiftBits - 1);

        long m;
        if (kLow < halfK) {
            m = q;
        } else if (kLow > halfK || remNonZero) {
            m = q + 1;
        } else {
            // Exact tie: round to even.
            m = q + (q & 1L);
        }

        long pattern = (e == 0) ? m : (((long) e << 10) + (m - 1024));
        return neg ? (pattern | 0x8000L) : pattern;
    }
}

#include <array>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>

namespace {

struct u128 {
    std::uint64_t lo = 0;
    std::uint64_t hi = 0;

    static constexpr u128 from_u64(std::uint64_t x) {
        return {x, 0};
    }

    friend constexpr bool operator==(const u128& a, const u128& b) {
        return a.hi == b.hi && a.lo == b.lo;
    }

    friend constexpr bool operator<(const u128& a, const u128& b) {
        return a.hi < b.hi || (a.hi == b.hi && a.lo < b.lo);
    }

    friend constexpr u128 operator+(const u128& a, const u128& b) {
        std::uint64_t lo = a.lo + b.lo;
        std::uint64_t carry = (lo < a.lo) ? 1ULL : 0ULL;
        std::uint64_t hi = a.hi + b.hi + carry;
        return {lo, hi};
    }
};

constexpr u128 mul_u64(const u128& a, std::uint64_t b) {
    std::uint64_t a0 = a.lo & 0xFFFFFFFFULL;
    std::uint64_t a1 = a.lo >> 32;
    std::uint64_t b0 = b & 0xFFFFFFFFULL;
    std::uint64_t b1 = b >> 32;

    std::uint64_t p00 = a0 * b0;
    std::uint64_t p01 = a0 * b1;
    std::uint64_t p10 = a1 * b0;
    std::uint64_t p11 = a1 * b1;

    std::uint64_t mid = (p00 >> 32) + (p01 & 0xFFFFFFFFULL) + (p10 & 0xFFFFFFFFULL);
    std::uint64_t lo = (p00 & 0xFFFFFFFFULL) | (mid << 32);
    std::uint64_t hi = a.hi * b + p11 + (p01 >> 32) + (p10 >> 32) + (mid >> 32);
    return {lo, hi};
}

constexpr std::uint64_t kFivePow25 = 298023223876953125ULL;

constexpr std::array<u128, 30> make_pow10() {
    std::array<u128, 30> res{};
    res[0] = u128::from_u64(1);
    for (std::size_t i = 1; i < 30; ++i) {
        res[i] = mul_u64(res[i - 1], 10ULL);
    }
    return res;
}

constexpr std::array<u128, 30> kPow10 = make_pow10();

constexpr std::uint64_t get_k(int p) {
    if (p == 31744) {
        return 1ULL << 41;
    }
    if (p < 1024) {
        return static_cast<std::uint64_t>(p) << 1;
    }
    int e = p >> 10;
    int f = p & 1023;
    return static_cast<std::uint64_t>(1024 + f) << e;
}

constexpr u128 get_midpoint(int p) {
    std::uint64_t k_mid = (get_k(p) + get_k(p + 1)) >> 1;
    return mul_u64(u128::from_u64(kFivePow25), k_mid);
}

constexpr bool is_ascii_digit(char c) {
    return c >= '0' && c <= '9';
}

} // namespace

long long decimal_to_half_bits(const std::string& s) {
    const std::size_t n = s.size();
    if (n == 0) {
        throw std::invalid_argument("empty string");
    }

    std::size_t i = 0;
    bool neg = false;
    if (s[i] == '+') {
        ++i;
    } else if (s[i] == '-') {
        neg = true;
        ++i;
    }

    const std::size_t int_start = i;
    while (i < n && is_ascii_digit(s[i])) {
        ++i;
    }
    const std::size_t int_end = i;

    std::size_t frac_start = i;
    std::size_t frac_end = i;
    if (i < n && s[i] == '.') {
        ++i;
        frac_start = i;
        while (i < n && is_ascii_digit(s[i])) {
            ++i;
        }
        frac_end = i;
    }

    if (int_start == int_end && frac_start == frac_end) {
        throw std::invalid_argument("invalid mantissa");
    }

    bool exp_neg = false;
    std::size_t exp_start = i;
    std::size_t exp_end = i;
    if (i < n && (s[i] == 'e' || s[i] == 'E')) {
        ++i;
        if (i < n && (s[i] == '+' || s[i] == '-')) {
            exp_neg = (s[i] == '-');
            ++i;
        }
        exp_start = i;
        while (i < n && is_ascii_digit(s[i])) {
            ++i;
        }
        exp_end = i;
        if (exp_start == exp_end) {
            throw std::invalid_argument("invalid exponent");
        }
    }

    if (i != n) {
        throw std::invalid_argument("trailing characters");
    }

    const long long sign_bit = neg ? 0x8000LL : 0x0000LL;

    // Find the first non-zero digit and its decimal position relative to '.'.
    bool found_nonzero = false;
    long long first_pos = 0;
    for (std::size_t idx = int_start; idx < int_end; ++idx) {
        if (s[idx] != '0') {
            found_nonzero = true;
            first_pos = static_cast<long long>(int_end - 1 - idx);
            break;
        }
    }
    if (!found_nonzero) {
        for (std::size_t idx = frac_start; idx < frac_end; ++idx) {
            if (s[idx] != '0') {
                found_nonzero = true;
                first_pos = -static_cast<long long>(idx - frac_start + 1);
                break;
            }
        }
    }

    if (!found_nonzero) {
        return sign_bit;
    }

    // Parse exponent while avoiding overflow on huge digit strings.
    std::size_t p = exp_start;
    while (p < exp_end && s[p] == '0') {
        ++p;
    }
    if (exp_end - p > 7) {
        return sign_bit | (exp_neg ? 0x0000LL : 0x7C00LL);
    }

    long long exp_val = 0;
    for (; p < exp_end; ++p) {
        exp_val = exp_val * 10 + (s[p] - '0');
    }
    if (exp_neg) {
        exp_val = -exp_val;
    }

    const long long sci_exp = first_pos + exp_val;
    if (sci_exp >= 5) {
        return sign_bit | 0x7C00LL;
    }
    if (sci_exp <= -9) {
        return sign_bit;
    }

    // Represent exact value as (v_int + epsilon) * 10^-25, where 0 <= epsilon < 1
    // and sticky indicates epsilon > 0.
    u128 v_int{0, 0};
    bool sticky = false;

    for (std::size_t idx = int_start; idx < int_end; ++idx) {
        if (s[idx] != '0') {
            long long eff_pos = static_cast<long long>(int_end - 1 - idx) + exp_val;
            if (eff_pos >= -25) {
                v_int = v_int + mul_u64(kPow10[static_cast<std::size_t>(eff_pos + 25)],
                                        static_cast<std::uint64_t>(s[idx] - '0'));
            } else {
                sticky = true;
            }
        }
    }
    for (std::size_t idx = frac_start; idx < frac_end; ++idx) {
        if (s[idx] != '0') {
            long long eff_pos = -static_cast<long long>(idx - frac_start + 1) + exp_val;
            if (eff_pos >= -25) {
                v_int = v_int + mul_u64(kPow10[static_cast<std::size_t>(eff_pos + 25)],
                                        static_cast<std::uint64_t>(s[idx] - '0'));
            } else {
                sticky = true;
            }
        }
    }

    auto cmp_midpoint = [&](int idx) -> int {
        u128 mid = get_midpoint(idx);
        if (v_int < mid) {
            return -1;
        }
        if (mid < v_int || sticky) {
            return 1;
        }
        return 0;
    };

    int lo = 0;
    int hi = 31743;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        int c = cmp_midpoint(mid);
        if (c == 0) {
            int res = mid + (mid & 1);
            return sign_bit | static_cast<long long>(res);
        } else if (c < 0) {
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    return sign_bit | static_cast<long long>(lo);
}

const FIVE_POW_25 = 5n ** 25n;
const OVERFLOW_Q = 4095n << 29n; // 65520 * 2^25

export function decimalToHalfBits(s: string): number {
  if (typeof s !== "string") {
    throw new Error("Expected a string literal");
  }
  const n = s.length;
  if (n === 0) {
    throw new Error("Empty literal");
  }

  let i = 0;
  let signBit = 0;
  const c0 = s.charCodeAt(0);
  if (c0 === 45 /* '-' */) {
    signBit = 0x8000;
    i = 1;
  } else if (c0 === 43 /* '+' */) {
    i = 1;
  }

  const intStart = i;
  while (i < n) {
    const c = s.charCodeAt(i);
    if (c < 48 || c > 57) break;
    i++;
  }
  const intEnd = i;

  let fracStart = i;
  let fracEnd = i;
  if (i < n && s.charCodeAt(i) === 46 /* '.' */) {
    i++;
    fracStart = i;
    while (i < n) {
      const c = s.charCodeAt(i);
      if (c < 48 || c > 57) break;
      i++;
    }
    fracEnd = i;
  }

  if (intEnd === intStart && fracEnd === fracStart) {
    throw new Error("Invalid mantissa");
  }

  let exp = 0;
  if (i < n) {
    const ec = s.charCodeAt(i);
    if (ec !== 101 /* 'e' */ && ec !== 69 /* 'E' */) {
      throw new Error("Invalid character in literal");
    }
    i++;
    let expNeg = false;
    if (i < n) {
      const sc = s.charCodeAt(i);
      if (sc === 45 /* '-' */) {
        expNeg = true;
        i++;
      } else if (sc === 43 /* '+' */) {
        i++;
      }
    }
    if (i === n) {
      throw new Error("Missing exponent digits");
    }
    const expCap = n + 100;
    let expVal = 0;
    while (i < n) {
      const c = s.charCodeAt(i);
      if (c < 48 || c > 57) {
        throw new Error("Invalid character in exponent");
      }
      if (expVal < expCap) {
        expVal = expVal * 10 + (c - 48);
      }
      i++;
    }
    exp = expNeg ? -expVal : expVal;
  }

  if (i !== n) {
    throw new Error("Trailing characters in literal");
  }

  // Locate the first non-zero digit
  let firstIdx = intStart;
  let firstIsFrac = false;
  while (firstIdx < intEnd && s.charCodeAt(firstIdx) === 48) {
    firstIdx++;
  }
  if (firstIdx === intEnd) {
    firstIsFrac = true;
    firstIdx = fracStart;
    while (firstIdx < fracEnd && s.charCodeAt(firstIdx) === 48) {
      firstIdx++;
    }
    if (firstIdx === fracEnd) {
      return signBit;
    }
  }

  const pLead = firstIsFrac
    ? fracStart - 1 - firstIdx + exp
    : intEnd - 1 - firstIdx + exp;

  if (pLead >= 5) {
    // |v| >= 10^5 > 65520
    return signBit | 0x7c00;
  }
  if (pLead <= -9) {
    // |v| < 10^-8 < 2^-25
    return signBit;
  }

  // Accumulate digits down to 10^-25 into K = floor(|v| * 10^25),
  // and track whether any digit at <= 10^-26 is non-zero.
  let K = 0n;
  let p = pLead;
  let hasTail = false;

  if (!firstIsFrac) {
    let idx = firstIdx;
    while (idx < intEnd && p >= -25) {
      K = K * 10n + BigInt(s.charCodeAt(idx) - 48);
      idx++;
      p--;
    }
    while (idx < intEnd) {
      if (s.charCodeAt(idx) !== 48) {
        hasTail = true;
        break;
      }
      idx++;
    }
  }

  let fIdx = firstIsFrac ? firstIdx : fracStart;
  while (fIdx < fracEnd && p >= -25) {
    K = K * 10n + BigInt(s.charCodeAt(fIdx) - 48);
    fIdx++;
    p--;
  }
  if (!hasTail) {
    while (fIdx < fracEnd) {
      if (s.charCodeAt(fIdx) !== 48) {
        hasTail = true;
        break;
      }
      fIdx++;
    }
  }

  if (p >= -25) {
    K *= 10n ** BigInt(p + 26);
  }

  const qBig = K / FIVE_POW_25;
  if (qBig >= OVERFLOW_Q) {
    return signBit | 0x7c00;
  }

  const isExact = K % FIVE_POW_25 === 0n && !hasTail;
  const q = Number(qBig);

  // Subnormals and E = 1 (all have half-step 2^-25)
  if (q < 4095) {
    let m = Math.floor(q / 2);
    if (q % 2 === 1 && (!isExact || (m & 1) === 1)) {
      m += 1;
    }
    return signBit | m;
  }

  // Normals with 2 <= E <= 30
  let E = 2;
  let bound = 8190; // 4095 * 2^(E - 1)
  while (q >= bound) {
    E++;
    bound *= 2;
  }

  const halfStep = 2 ** (E - 1);
  const q2 = Math.floor(q / halfStep);
  const isExact2 = q % halfStep === 0 && isExact;
  let u = Math.floor(q2 / 2);
  if (q2 % 2 === 1 && (!isExact2 || (u & 1) === 1)) {
    u += 1;
  }
  return signBit | (E << 10) | (u - 1024);
}

from bisect import bisect_left, bisect_right


def run_ops(ops: list[tuple]) -> list:
    starts_set = set()
    for op in ops:
        if op[0] == "book" and op[1] < op[2]:
            starts_set.add(op[1])

    if not starts_set:
        out = []
        for op in ops:
            kind = op[0]
            if kind == "book":
                out.append("INVALID")
            elif kind == "cancel":
                out.append(0)
            elif kind == "first_fit":
                out.append(op[1])
            else:  # free_between
                a, b = op[1], op[2]
                out.append(b - a if b > a else 0)
        return out

    S = sorted(starts_set)
    M = len(S)
    start_to_idx = {val: i for i, val in enumerate(S)}

    N = 1 << (M - 1).bit_length()
    INF = 10**18

    max_gap = [-1] * (2 * N)
    sum_len = [0] * (2 * N)
    ends = [0] * M

    def update_full(idx: int, gap_val: int, len_val: int) -> None:
        p = idx + N
        max_gap[p] = gap_val
        sum_len[p] = len_val
        p >>= 1
        while p:
            c = p << 1
            g1 = max_gap[c]
            g2 = max_gap[c + 1]
            max_gap[p] = g1 if g1 > g2 else g2
            sum_len[p] = sum_len[c] + sum_len[c + 1]
            p >>= 1

    def update_gap(idx: int, gap_val: int) -> None:
        p = idx + N
        max_gap[p] = gap_val
        p >>= 1
        while p:
            c = p << 1
            g1 = max_gap[c]
            g2 = max_gap[c + 1]
            ng = g1 if g1 > g2 else g2
            if ng == max_gap[p]:
                break
            max_gap[p] = ng
            p >>= 1

    def rightmost_active(idx: int) -> int:
        if idx < 0:
            return -1
        p = idx + N
        if max_gap[p] >= 0:
            return idx
        while p > 1:
            if p & 1:
                if max_gap[p - 1] >= 0:
                    c = p - 1
                    while c < N:
                        c <<= 1
                        if max_gap[c + 1] >= 0:
                            c += 1
                    return c - N
            p >>= 1
        return -1

    def first_ge(idx: int, d: int) -> int:
        if idx >= M:
            return -1
        p = idx + N
        if max_gap[p] >= d:
            return idx
        while p > 1:
            if not (p & 1):
                if max_gap[p + 1] >= d:
                    c = p + 1
                    while c < N:
                        c <<= 1
                        if max_gap[c] < d:
                            c += 1
                    return c - N
            p >>= 1
        return -1

    def occ(x: int) -> int:
        if x <= 0:
            return 0
        idx = bisect_left(S, x) - 1
        if idx < 0:
            return 0
        j = rightmost_active(idx)
        if j == -1:
            return 0
        e_j = ends[j]
        res = 0
        l = N
        r = j + N
        while l < r:
            if l & 1:
                res += sum_len[l]
                l += 1
            if r & 1:
                r -= 1
                res += sum_len[r]
            l >>= 1
            r >>= 1
        return res + (e_j if e_j < x else x) - S[j]

    out = []
    append = out.append

    for op in ops:
        kind = op[0]
        if kind == "book":
            s, e = op[1], op[2]
            if s >= e:
                append("INVALID")
                continue
            idx = start_to_idx[s]
            if ends[idx] > 0:
                append("CONFLICT")
                continue
            prev_idx = rightmost_active(idx - 1)
            if prev_idx != -1 and ends[prev_idx] > s:
                append("CONFLICT")
                continue
            next_idx = first_ge(idx + 1, 0)
            if next_idx != -1 and e > S[next_idx]:
                append("CONFLICT")
                continue
            ends[idx] = e
            new_gap = (S[next_idx] - e) if next_idx != -1 else INF
            update_full(idx, new_gap, e - s)
            if prev_idx != -1:
                update_gap(prev_idx, s - ends[prev_idx])
            append(True)

        elif kind == "cancel":
            s = op[1]
            idx = start_to_idx.get(s, -1)
            if idx == -1 or ends[idx] == 0:
                append(0)
                continue
            e = ends[idx]
            ends[idx] = 0
            update_full(idx, -1, 0)
            prev_idx = rightmost_active(idx - 1)
            if prev_idx != -1:
                next_idx = first_ge(idx + 1, 0)
                new_gap = (S[next_idx] - ends[prev_idx]) if next_idx != -1 else INF
                update_gap(prev_idx, new_gap)
            append(e - s)

        elif kind == "first_fit":
            t, d = op[1], op[2]
            idx = bisect_right(S, t) - 1
            j = rightmost_active(idx)
            if j != -1 and ends[j] > t:
                i = first_ge(j, d)
                append(ends[i])
            else:
                k = first_ge(idx + 1, 0)
                if k == -1 or S[k] - t >= d:
                    append(t)
                else:
                    i = first_ge(k, d)
                    append(ends[i])

        else:  # free_between
            a, b = op[1], op[2]
            if a >= b:
                append(0)
            else:
                append((b - a) - (occ(b) - occ(a)))

    return out

