import (
	"container/heap"
	"fmt"
	"sort"
)

type Tuple1 struct {
	F0 string
	F1 int
	F2 int
	F3 int
	F4 *int
}

type Tuple2 struct {
	F0 string
	F1 int
	F2 int
}

type Tuple3 struct {
	F0 []Tuple2
	F1 []string
}

type jobHeap []Tuple1

func (h jobHeap) Len() int { return len(h) }

func (h jobHeap) Less(i, j int) bool {
	if h[i].F3 != h[j].F3 {
		return h[i].F3 > h[j].F3
	}
	if h[i].F1 != h[j].F1 {
		return h[i].F1 < h[j].F1
	}
	return h[i].F0 < h[j].F0
}

func (h jobHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *jobHeap) Push(x any) {
	*h = append(*h, x.(Tuple1))
}

func (h *jobHeap) Pop() any {
	old := *h
	n := len(old)
	item := old[n-1]
	*h = old[:n-1]
	return item
}

func Schedule(jobs []Tuple1) (Tuple3, error) {
	seen := make(map[string]struct{}, len(jobs))
	for _, job := range jobs {
		jobID, release, duration := job.F0, job.F1, job.F2
		if _, exists := seen[jobID]; exists {
			return Tuple3{}, fmt.Errorf("duplicate job id %q", jobID)
		}
		seen[jobID] = struct{}{}
		if release < 0 {
			return Tuple3{}, fmt.Errorf("job %q has a negative release time", jobID)
		}
		if duration < 1 {
			return Tuple3{}, fmt.Errorf("job %q has a non-positive duration", jobID)
		}
	}

	sorted := make([]Tuple1, len(jobs))
	copy(sorted, jobs)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].F1 < sorted[j].F1
	})

	runs := make([]Tuple2, 0)
	dropped := make([]string, 0)
	pq := make(jobHeap, 0)
	heap.Init(&pq)

	clock := 0
	nxt := 0
	for nxt < len(sorted) || len(pq) > 0 {
		if len(pq) == 0 && sorted[nxt].F1 > clock {
			clock = sorted[nxt].F1
		}
		for nxt < len(sorted) && sorted[nxt].F1 <= clock {
			heap.Push(&pq, sorted[nxt])
			nxt++
		}

		best := heap.Pop(&pq).(Tuple1)
		jobID, duration, deadline := best.F0, best.F2, best.F4
		if deadline != nil && clock+duration > *deadline {
			dropped = append(dropped, jobID)
			continue
		}
		runs = append(runs, Tuple2{
			F0: jobID,
			F1: clock,
			F2: clock + duration,
		})
		clock += duration
	}

	return Tuple3{
		F0: runs,
		F1: dropped,
	}, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1, long f2, long f3, Long f4) {}

    public record Tuple2(String f0, long f1, long f2) {}

    public record Tuple3(List<Tuple2> f0, List<String> f1) {}

    public static Tuple3 schedule(List<Tuple1> jobs) {
        if (jobs == null) {
            throw new IllegalArgumentException("jobs must not be null");
        }

        int n = jobs.size();
        Set<String> seen = HashSet.newHashSet(n);
        for (Tuple1 job : jobs) {
            if (job == null) {
                throw new IllegalArgumentException("each job must be non-null");
            }
            String jobId = job.f0();
            long release = job.f1();
            long duration = job.f2();
            if (jobId == null) {
                throw new IllegalArgumentException("job_id must not be null");
            }
            if (!seen.add(jobId)) {
                throw new IllegalArgumentException("duplicate job id " + jobId);
            }
            if (release < 0) {
                throw new IllegalArgumentException("job " + jobId + " has a negative release time");
            }
            if (duration < 1) {
                throw new IllegalArgumentException("job " + jobId + " has a non-positive duration");
            }
        }

        Tuple1[] sorted = jobs.toArray(new Tuple1[0]);
        Arrays.sort(sorted, Comparator.comparingLong(Tuple1::f1));

        PriorityQueue<Tuple1> ready = new PriorityQueue<>((a, b) -> {
            int cmp = Long.compare(b.f3(), a.f3()); // higher priority first
            if (cmp != 0) {
                return cmp;
            }
            cmp = Long.compare(a.f1(), b.f1()); // smaller release first
            if (cmp != 0) {
                return cmp;
            }
            return a.f0().compareTo(b.f0()); // smaller job_id first
        });

        List<Tuple2> runs = new ArrayList<>();
        List<String> dropped = new ArrayList<>();

        long clock = 0;
        int nxt = 0;
        while (nxt < n || !ready.isEmpty()) {
            while (nxt < n && sorted[nxt].f1() <= clock) {
                ready.add(sorted[nxt]);
                nxt++;
            }
            if (ready.isEmpty()) {
                clock = sorted[nxt].f1();
                while (nxt < n && sorted[nxt].f1() <= clock) {
                    ready.add(sorted[nxt]);
                    nxt++;
                }
            }

            Tuple1 best = ready.poll();
            String jobId = best.f0();
            long duration = best.f2();
            Long deadline = best.f4();

            if (deadline != null && (clock > Long.MAX_VALUE - duration || clock + duration > deadline)) {
                dropped.add(jobId);
                continue;
            }

            long end = clock + duration;
            runs.add(new Tuple2(jobId, clock, end));
            clock = end;
        }

        return new Tuple3(runs, dropped);
    }
}

