std::tuple<std::vector<std::tuple<std::string, long long, long long>>, std::vector<std::string>>
schedule(const std::vector<std::tuple<std::string, long long, long long, long long, std::optional<long long>>>& jobs) {
    const std::size_t n = jobs.size();
    std::unordered_set<std::string_view> seen;
    seen.reserve(n);

    for (const auto& job : jobs) {
        const auto& [job_id, release, duration, priority, deadline] = job;
        (void)priority;
        (void)deadline;
        if (!seen.insert(job_id).second) {
            throw std::invalid_argument("duplicate job id");
        }
        if (release < 0) {
            throw std::invalid_argument("negative release time");
        }
        if (duration < 1) {
            throw std::invalid_argument("non-positive duration");
        }
    }

    std::vector<std::size_t> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&jobs](std::size_t a, std::size_t b) {
        return std::get<1>(jobs[a]) < std::get<1>(jobs[b]);
    });

    auto cmp = [&jobs](std::size_t a, std::size_t b) {
        const auto& ja = jobs[a];
        const auto& jb = jobs[b];
        if (std::get<3>(ja) != std::get<3>(jb)) {
            return std::get<3>(ja) < std::get<3>(jb);
        }
        if (std::get<1>(ja) != std::get<1>(jb)) {
            return std::get<1>(ja) > std::get<1>(jb);
        }
        return std::get<0>(ja) > std::get<0>(jb);
    };

    std::priority_queue<std::size_t, std::vector<std::size_t>, decltype(cmp)> ready(cmp);
    std::vector<std::tuple<std::string, long long, long long>> runs;
    std::vector<std::string> dropped;
    runs.reserve(n);

    long long clock = 0;
    std::size_t nxt = 0;

    while (nxt < n || !ready.empty()) {
        if (ready.empty() && std::get<1>(jobs[order[nxt]]) > clock) {
            clock = std::get<1>(jobs[order[nxt]]);
        }
        while (nxt < n && std::get<1>(jobs[order[nxt]]) <= clock) {
            ready.push(order[nxt]);
            ++nxt;
        }

        const std::size_t best = ready.top();
        ready.pop();

        const auto& [job_id, release, duration, priority, deadline] = jobs[best];
        (void)release;
        (void)priority;

        if (deadline.has_value() && (*deadline < clock || *deadline - clock < duration)) {
            dropped.push_back(job_id);
            continue;
        }

        runs.emplace_back(job_id, clock, clock + duration);
        clock += duration;
    }

    return {std::move(runs), std::move(dropped)};
}

type Job = [string, number, number, number, number | null];

function isHigherPriority(a: Job, b: Job): boolean {
  if (a[3] !== b[3]) {
    return a[3] > b[3];
  }
  if (a[1] !== b[1]) {
    return a[1] < b[1];
  }
  return a[0] < b[0];
}

function heapPush(heap: Job[], job: Job): void {
  heap.push(job);
  let i = heap.length - 1;
  while (i > 0) {
    const parent = (i - 1) >>> 1;
    if (isHigherPriority(heap[i], heap[parent])) {
      const tmp = heap[i];
      heap[i] = heap[parent];
      heap[parent] = tmp;
      i = parent;
    } else {
      break;
    }
  }
}

function heapPop(heap: Job[]): Job {
  const top = heap[0];
  const last = heap.pop()!;
  if (heap.length > 0) {
    heap[0] = last;
    let i = 0;
    const len = heap.length;
    while (true) {
      const left = 2 * i + 1;
      if (left >= len) {
        break;
      }
      const right = left + 1;
      let best = left;
      if (right < len && isHigherPriority(heap[right], heap[left])) {
        best = right;
      }
      if (isHigherPriority(heap[best], heap[i])) {
        const tmp = heap[i];
        heap[i] = heap[best];
        heap[best] = tmp;
        i = best;
      } else {
        break;
      }
    }
  }
  return top;
}

export function schedule(
  jobs: ([string, number, number, number, number | null])[],
): [[string, number, number][], string[]] {
  const seen = new Set<string>();
  for (let i = 0; i < jobs.length; i++) {
    const job = jobs[i];
    if (!Array.isArray(job) || job.length !== 5) {
      throw new Error("each job must be a 5-tuple");
    }
    const [jobId, release, duration] = job;
    if (seen.has(jobId)) {
      throw new Error(`duplicate job id ${JSON.stringify(jobId)}`);
    }
    seen.add(jobId);
    if (release < 0) {
      throw new Error(`job ${JSON.stringify(jobId)} has a negative release time`);
    }
    if (duration < 1) {
      throw new Error(`job ${JSON.stringify(jobId)} has a non-positive duration`);
    }
  }

  const sorted = jobs.slice().sort((a, b) => (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));

  const runs: [string, number, number][] = [];
  const dropped: string[] = [];
  const ready: Job[] = [];
  let clock = 0;
  let nxt = 0;
  const n = sorted.length;

  while (nxt < n || ready.length > 0) {
    if (ready.length === 0 && sorted[nxt][1] > clock) {
      clock = sorted[nxt][1];
    }
    while (nxt < n && sorted[nxt][1] <= clock) {
      heapPush(ready, sorted[nxt]);
      nxt++;
    }

    const best = heapPop(ready);
    const [jobId, , duration, , deadline] = best;
    if (deadline !== null && clock + duration > deadline) {
      dropped.push(jobId);
      continue;
    }
    runs.push([jobId, clock, clock + duration]);
    clock += duration;
  }

  return [runs, dropped];
}

import heapq


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = {}  # value -> pending lazy deletions
    low_size = 0
    high_size = 0
    out = []

    def prune_low():
        while low:
            val = -low[0]
            cnt = delayed.get(val)
            if not cnt:
                break
            if cnt == 1:
                del delayed[val]
            else:
                delayed[val] = cnt - 1
            heapq.heappop(low)

    def prune_high():
        while high:
            val = high[0]
            cnt = delayed.get(val)
            if not cnt:
                break
            if cnt == 1:
                del delayed[val]
            else:
                delayed[val] = cnt - 1
            heapq.heappop(high)

    def rebalance():
        nonlocal low_size, high_size
        # invariant: low_size == high_size or low_size == high_size + 1
        if low_size > high_size + 1:
            heapq.heappush(high, -heapq.heappop(low))
            low_size -= 1
            high_size += 1
            prune_low()
        elif low_size < high_size:
            heapq.heappush(low, -heapq.heappop(high))
            high_size -= 1
            low_size += 1
            prune_high()

    def add(x):
        nonlocal low_size, high_size
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            low_size += 1
        else:
            heapq.heappush(high, x)
            high_size += 1
        rebalance()

    def remove(x):
        nonlocal low_size, high_size
        delayed[x] = delayed.get(x, 0) + 1
        if x <= -low[0]:
            low_size -= 1
            if x == -low[0]:
                prune_low()
        else:
            high_size -= 1
            if x == high[0]:
                prune_high()
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        out.append(-low[0] if low_size else None)

    return out

