import "errors"

type intHeap struct {
	data []int
	max  bool
}

func (h *intHeap) less(i, j int) bool {
	if h.max {
		return h.data[i] > h.data[j]
	}
	return h.data[i] < h.data[j]
}

func (h *intHeap) push(x int) {
	h.data = append(h.data, x)
	i := len(h.data) - 1
	for i > 0 {
		p := (i - 1) / 2
		if h.less(i, p) {
			h.data[i], h.data[p] = h.data[p], h.data[i]
			i = p
		} else {
			break
		}
	}
}

func (h *intHeap) pop() int {
	top := h.data[0]
	n := len(h.data) - 1
	h.data[0] = h.data[n]
	h.data = h.data[:n]
	i := 0
	for {
		left := 2*i + 1
		if left >= n {
			break
		}
		best := left
		if right := left + 1; right < n && h.less(right, left) {
			best = right
		}
		if !h.less(best, i) {
			break
		}
		h.data[i], h.data[best] = h.data[best], h.data[i]
		i = best
	}
	return top
}

func WindowMedians(readings []*int, k int) ([]*int, error) {
	if k < 1 {
		return nil, errors.New("k must be a positive int")
	}

	low := intHeap{max: true}
	high := intHeap{max: false}
	delayed := make(map[int]int)
	lowSize, highSize := 0, 0
	out := make([]*int, 0, len(readings))

	prune := func(h *intHeap) {
		for len(h.data) > 0 {
			top := h.data[0]
			cnt := delayed[top]
			if cnt == 0 {
				break
			}
			if cnt == 1 {
				delete(delayed, top)
			} else {
				delayed[top] = cnt - 1
			}
			h.pop()
		}
	}

	rebalance := func() {
		if lowSize > highSize+1 {
			high.push(low.pop())
			lowSize--
			highSize++
			prune(&low)
		} else if lowSize < highSize {
			low.push(high.pop())
			highSize--
			lowSize++
			prune(&high)
		}
	}

	add := func(x int) {
		if len(low.data) == 0 || x <= low.data[0] {
			low.push(x)
			lowSize++
		} else {
			high.push(x)
			highSize++
		}
		rebalance()
	}

	remove := func(x int) {
		delayed[x]++
		if x <= low.data[0] {
			lowSize--
			if x == low.data[0] {
				prune(&low)
			}
		} else {
			highSize--
			if x == high.data[0] {
				prune(&high)
			}
		}
		rebalance()
	}

	for i, ptr := range readings {
		if ptr != nil {
			add(*ptr)
		}
		if i >= k && readings[i-k] != nil {
			remove(*readings[i-k])
		}
		if lowSize > 0 {
			m := low.data[0]
			out = append(out, &m)
		} else {
			out = append(out, nil)
		}
	}

	return out, nil
}

import java.util.*;

public final class Solution {
    private static final class MedianTracker {
        private final PriorityQueue<Long> low = new PriorityQueue<>(Comparator.reverseOrder());
        private final PriorityQueue<Long> high = new PriorityQueue<>();
        private final Map<Long, Integer> delayed = new HashMap<>();
        private int lowSize = 0;
        private int highSize = 0;

        private void prune(PriorityQueue<Long> heap) {
            while (!heap.isEmpty()) {
                Long top = heap.peek();
                Integer cnt = delayed.get(top);
                if (cnt == null) {
                    break;
                }
                if (cnt == 1) {
                    delayed.remove(top);
                } else {
                    delayed.put(top, cnt - 1);
                }
                heap.poll();
            }
        }

        private void rebalance() {
            if (lowSize > highSize + 1) {
                high.offer(low.poll());
                lowSize--;
                highSize++;
                prune(low);
            } else if (lowSize < highSize) {
                low.offer(high.poll());
                highSize--;
                lowSize++;
                prune(high);
            }
        }

        void add(long x) {
            if (low.isEmpty() || x <= low.peek()) {
                low.offer(x);
                lowSize++;
            } else {
                high.offer(x);
                highSize++;
            }
            rebalance();
        }

        void remove(long x) {
            delayed.merge(x, 1, Integer::sum);
            long lowTop = low.peek();
            if (x <= lowTop) {
                lowSize--;
                if (x == lowTop) {
                    prune(low);
                }
            } else {
                highSize--;
                if (x == high.peek()) {
                    prune(high);
                }
            }
            rebalance();
        }

        Long median() {
            return lowSize > 0 ? low.peek() : null;
        }
    }

    public static List<Long> windowMedians(List<Long> readings, long k) {
        if (readings == null || k < 1) {
            throw new IllegalArgumentException("k must be a positive integer");
        }
        List<Long> out = new ArrayList<>(readings.size());
        MedianTracker tracker = new MedianTracker();
        Iterator<Long> head = readings.iterator();
        Iterator<Long> tail = readings.iterator();
        for (long i = 0; head.hasNext(); i++) {
            Long x = head.next();
            if (x != null) {
                tracker.add(x);
            }
            if (i >= k) {
                Long old = tail.next();
                if (old != null) {
                    tracker.remove(old);
                }
            }
            out.add(tracker.median());
        }
        return out;
    }
}

