namespace {

struct SplitMix64 {
    std::size_t operator()(long long key) const noexcept {
        std::uint64_t x = static_cast<std::uint64_t>(key);
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return static_cast<std::size_t>(x ^ (x >> 31));
    }
};

} // namespace

std::vector<std::optional<long long>> window_medians(const std::vector<std::optional<long long>>& readings, long long k) {
    if (k < 1) {
        throw std::invalid_argument("k must be a positive int");
    }

    std::priority_queue<long long> low;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> high;
    std::unordered_map<long long, long long, SplitMix64> delayed;
    long long low_size = 0;
    long long high_size = 0;

    auto prune_low = [&]() {
        while (!low.empty()) {
            auto it = delayed.find(low.top());
            if (it == delayed.end() || it->second == 0) {
                break;
            }
            if (--(it->second) == 0) {
                delayed.erase(it);
            }
            low.pop();
        }
    };

    auto prune_high = [&]() {
        while (!high.empty()) {
            auto it = delayed.find(high.top());
            if (it == delayed.end() || it->second == 0) {
                break;
            }
            if (--(it->second) == 0) {
                delayed.erase(it);
            }
            high.pop();
        }
    };

    auto rebalance = [&]() {
        if (low_size > high_size + 1) {
            high.push(low.top());
            low.pop();
            --low_size;
            ++high_size;
            prune_low();
        } else if (low_size < high_size) {
            low.push(high.top());
            high.pop();
            --high_size;
            ++low_size;
            prune_high();
        }
    };

    auto add = [&](long long x) {
        if (low.empty() || x <= low.top()) {
            low.push(x);
            ++low_size;
        } else {
            high.push(x);
            ++high_size;
        }
        rebalance();
    };

    auto remove = [&](long long x) {
        ++delayed[x];
        if (x <= low.top()) {
            --low_size;
            if (x == low.top()) {
                prune_low();
            }
        } else {
            --high_size;
            if (x == high.top()) {
                prune_high();
            }
        }
        rebalance();
    };

    const long long n = static_cast<long long>(readings.size());
    std::vector<std::optional<long long>> out;
    out.reserve(readings.size());

    for (long long i = 0; i < n; ++i) {
        if (readings[static_cast<std::size_t>(i)].has_value()) {
            add(*readings[static_cast<std::size_t>(i)]);
        }
        if (i >= k && readings[static_cast<std::size_t>(i - k)].has_value()) {
            remove(*readings[static_cast<std::size_t>(i - k)]);
        }
        if (low_size > 0) {
            out.push_back(low.top());
        } else {
            out.push_back(std::nullopt);
        }
    }

    return out;
}

function pushMax(heap: number[], val: number): void {
  let i = heap.length;
  heap.push(val);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heap[p] >= val) break;
    heap[i] = heap[p];
    i = p;
  }
  heap[i] = val;
}

function popMax(heap: number[]): number {
  const top = heap[0];
  const last = heap.pop()!;
  const n = heap.length;
  if (n > 0) {
    let i = 0;
    const half = n >> 1;
    while (i < half) {
      let c = (i << 1) + 1;
      const r = c + 1;
      if (r < n && heap[r] > heap[c]) {
        c = r;
      }
      if (last >= heap[c]) break;
      heap[i] = heap[c];
      i = c;
    }
    heap[i] = last;
  }
  return top;
}

function pushMin(heap: number[], val: number): void {
  let i = heap.length;
  heap.push(val);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heap[p] <= val) break;
    heap[i] = heap[p];
    i = p;
  }
  heap[i] = val;
}

function popMin(heap: number[]): number {
  const top = heap[0];
  const last = heap.pop()!;
  const n = heap.length;
  if (n > 0) {
    let i = 0;
    const half = n >> 1;
    while (i < half) {
      let c = (i << 1) + 1;
      const r = c + 1;
      if (r < n && heap[r] < heap[c]) {
        c = r;
      }
      if (last <= heap[c]) break;
      heap[i] = heap[c];
      i = c;
    }
    heap[i] = last;
  }
  return top;
}

export function windowMedians(
  readings: (number | null)[],
  k: number,
): (number | null)[] {
  if (!Number.isInteger(k) || k < 1) {
    throw new Error("k must be a positive integer");
  }

  const low: number[] = []; // max-heap: smaller half, top is lower median
  const high: number[] = []; // min-heap: larger half
  const delayed = new Map<number, number>();
  let lowSize = 0;
  let highSize = 0;

  function pruneMax(): void {
    while (low.length > 0) {
      const top = low[0];
      const cnt = delayed.get(top);
      if (cnt === undefined || cnt === 0) break;
      if (cnt === 1) {
        delayed.delete(top);
      } else {
        delayed.set(top, cnt - 1);
      }
      popMax(low);
    }
  }

  function pruneMin(): void {
    while (high.length > 0) {
      const top = high[0];
      const cnt = delayed.get(top);
      if (cnt === undefined || cnt === 0) break;
      if (cnt === 1) {
        delayed.delete(top);
      } else {
        delayed.set(top, cnt - 1);
      }
      popMin(high);
    }
  }

  function rebalance(): void {
    if (lowSize > highSize + 1) {
      pushMin(high, popMax(low));
      lowSize--;
      highSize++;
      pruneMax();
    } else if (lowSize < highSize) {
      pushMax(low, popMin(high));
      highSize--;
      lowSize++;
      pruneMin();
    }
  }

  function add(x: number): void {
    if (low.length === 0 || x <= low[0]) {
      pushMax(low, x);
      lowSize++;
    } else {
      pushMin(high, x);
      highSize++;
    }
    rebalance();
  }

  function remove(x: number): void {
    delayed.set(x, (delayed.get(x) ?? 0) + 1);
    if (x <= low[0]) {
      lowSize--;
      if (x === low[0]) {
        pruneMax();
      }
    } else {
      highSize--;
      if (x === high[0]) {
        pruneMin();
      }
    }
    rebalance();
  }

  const out: (number | null)[] = new Array(readings.length);
  for (let i = 0; i < readings.length; i++) {
    const x = readings[i];
    if (x !== null) {
      add(x);
    }
    if (i >= k) {
      const old = readings[i - k];
      if (old !== null) {
        remove(old);
      }
    }
    out[i] = lowSize > 0 ? low[0] : null;
  }

  return out;
}

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            i = n if end == -1 else end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
